const tabsH=(items,cur,act)=>`<div class="tabs" role="tablist">${items.map(([k,t])=>`<button class="tab ${cur===k?'on':''}" role="tab" data-a="${act}" data-v="${k}">${t}</button>`).join('')}</div>`;
