document.addEventListener('change',e=>{const t=e.target;if(!t||(t.name!=='hbt'&&t.name!=='h11'))return;const f=t.closest('form'),p=f&&f.querySelector(t.name==='hbt'?'#hth-bt':'#hth-11');if(p)p.hidden=!t.checked});
ACT.d11bt=()=>{const f=$q('#hsff');if(!f)return false;DAY_ALL.forEach(w=>{const a=f.elements['bd'+w],c=f.elements['d'+w];if(a&&c)c.checked=a.checked});return false};
/* thêm các buổi 1-1 cho một bé: mỗi buổi {w: thứ, slot: giờ bắt đầu}; kiểm tra trùng giáo viên, bé, phòng từng ngày */
function add11(k,picks,gv,room){const res={ok:0,bad:[],warn:[]};
 picks.forEach(p=>{const w=p.w,slot=p.slot,rm=room||ROOMS.find(r=>!conflict({day:w,slot,gv,hs:k.id,room:r}))||'',x={id:'l'+uid(),type:'11',day:w,slot,gv,hs:k.id,room:rm,lt:p.lt||null},c=rm?conflict(x):(conflict(Object.assign({},x,{room:''}))||'Không còn phòng trống');   /* hết phòng vì giáo viên hoặc bé đã bận thì báo đúng lý do */
  if(c){res.bad.push(DAYS[w]+': '+c);return}
  DB.lich.push(x);res.ok++;const wn=btWarn(k,w,slot);if(wn)res.warn.push(DAYS[w]+': '+wn)});
 if(res.ok&&!k.gv)k.gv=gv;k.m11=wk11(k.id);return res}
MODALS.hsf=()=>{const id=S.modal.id,k=id?kidBy(id):{n:'',g:'M',dob:addD(TODAY,-365*4),sd:TODAY,st:'dang',nd:NEEDS[0],bt:false,gr:'',gv:'',pn:'',pr:'Mẹ',pp:'',pe:'',dx:[]};
 const f=(n,l,v,t,x)=>`<div><label for="hf-${n}">${l}</label><input id="hf-${n}" name="${n}" type="${t||'text'}" value="${esc(v)}" ${x||''}></div>`;
 return mdl(id?'Sửa hồ sơ '+k.n:'Thêm học sinh',`<form id="hsff" class="f"><div class="f2">${f('n','Họ và tên bé',k.n,'text','required')}<div><label for="hf-g">Giới tính</label><select id="hf-g" name="g">${opts([['M','Nam'],['F','Nữ']],k.g)}</select></div>${f('dob','Ngày sinh',k.dob,'date','required max="'+TODAY+'"')}${f('sd','Ngày nhập học',k.sd,'date')}<div><label for="hf-nd">Nhu cầu chính</label><select id="hf-nd" name="nd">${opts(NEEDS.map(x=>[x,x]),k.nd)}</select></div><div><label for="hf-st">Trạng thái</label><select id="hf-st" name="st">${opts(Object.entries(KST),k.st)}</select><small class="mu">Chọn “Đã nghỉ” khi bé ngưng can thiệp: học phí đã đóng và phí dư không được hoàn.</small></div>
 </div>
 ${hthField(k,!!id)}
 ${dxField(k)}
 <h3>Phụ huynh</h3><div class="f2"><div><label for="hf-pr">Quan hệ</label><select id="hf-pr" name="pr">${opts(['Mẹ','Bố','Ông bà','Người giám hộ'].map(x=>[x,x]),k.pr)}</select></div>${f('pn','Họ tên phụ huynh',k.pn,'text','required')}${f('pp','Điện thoại',k.pp,'tel','required')}${f('pe','Email cổng phụ huynh (hoặc dùng số điện thoại)',k.pe,'email')}</div>
 <p class="note sm">Thông tin đã nhập được giữ lại: mở hồ sơ là thấy sẵn, chỉ sửa chỗ cần đổi rồi bấm Lưu. Hệ thống kiểm tra trùng giáo viên, bé và phòng khi thêm hoặc đổi giờ ca 1-1; nếu có ca không đổi được thì hồ sơ chưa được lưu và báo rõ lý do.</p>
 <div class="acts" style="justify-content:flex-end"><button class="btn" type="button" data-a="mx">Hủy</button><button class="btn p" type="submit">Lưu hồ sơ</button></div></form>`)};
FORM.hsff=f=>{const g=n=>f.elements[n]?f.elements[n].value.trim():'',id=S.modal.id,isNew=!id;
 const old=isNew?null:kidBy(id);
 if(!g('n')||!g('pn')||(!g('pe')&&!telNorm(g('pp')))){toast('Vui lòng nhập tên bé, tên phụ huynh và email hoặc số điện thoại phụ huynh');return false}
 const bt=f.elements.hbt.checked,h11=f.elements.h11.checked,bd=daysOf(f,'bd'),wasSt=isNew?'dang':old.st;
 if(bt&&!bd.length){toast('Hãy tích ít nhất một buổi bán trú trong tuần');return false}
 const room=f.elements.room.value,gv=g('gv'),ltq={};
 LT.forEach(x=>{const c=f.elements['lt_'+x.c];if(h11&&c&&c.checked)ltq[x.c]=Math.min(4,Math.max(1,parseInt(f.elements['lq_'+x.c].value,10)||1))});
 /* Các dòng ca trong biểu mẫu. Dòng có data-lid là ca đã lưu (sửa đúng buổi đó); dòng không có là ca mới. Chỉ những ca đã hiện trong biểu mẫu lúc mở (data-ids) mới có thể bị xóa, nên ca do người khác vừa thêm trong lúc đang sửa không bị mất. */
 const box=f.querySelector('#s11'),loaded=new Set(((box&&box.dataset.ids)||'').split(',').filter(Boolean)),cur=isNew?[]:DB.lich.filter(l=>l.type==='11'&&l.hs===id),old11=cur.length,
  rows=h11?[...f.querySelectorAll('#s11 .s11r')].map(r=>({lid:r.dataset.lid||'',gone:r.classList.contains('gone'),w:+r.querySelector('[name=s11day]').value,lt:r.querySelector('[name=s11lt]').value,slot:String(r.querySelector('[name=s11tm]').value||'').slice(0,5)})):[];
 if(!h11&&old11){toast('Bé đang có '+old11+' buổi 1-1. Muốn bỏ hình thức 1-1, hãy xóa từng buổi: tích lại Can thiệp 1-1 rồi bấm Xóa ca ở từng ca (hoặc xóa ở thẻ Lịch học của hồ sơ bé)');return false}
 const act=rows.filter(r=>!r.gone&&(!r.lid||cur.some(l=>l.id===r.lid))),keepIds=new Set(act.filter(r=>r.lid).map(r=>r.lid)),
  gone=cur.filter(l=>loaded.has(l.id)&&!keepIds.has(l.id)),
  ups=act.filter(r=>r.lid).map(r=>{const l=cur.find(x=>x.id===r.lid);return{r,l,o:Object.assign({},l)}}).filter(u=>u.r.w!==u.o.day||u.r.slot!==u.o.slot||u.r.lt!==(u.o.lt||'')),
  news=act.filter(r=>!r.lid);
 if(h11&&news.length&&!Object.keys(ltq).length){toast('Hãy tích ít nhất một loại 1-1 và ghi số giờ mỗi ngày');return false}
 if(h11&&!act.length&&!old11){toast('Hãy thêm ít nhất một ca 1-1 (hoặc bỏ tích Can thiệp 1-1)');return false}
 const noLt=act.find(r=>r.lt?!ltq[r.lt]:!r.lid);   /* ca cũ chưa có loại thì để nguyên; ca đã có loại hoặc ca mới thì loại phải còn được tích */
 if(noLt){toast(noLt.lid&&noLt.lt?DAYN[noLt.w]+': loại "'+LTM[noLt.lt].n+'" chưa được tích ở phần loại 1-1. Hãy tích lại loại này hoặc đổi loại của ca':'Mỗi ca mới phải chọn một loại 1-1 đã tích');return false}
 const fin=act.map(r=>({w:r.w,lt:r.lt})).concat(cur.filter(l=>!loaded.has(l.id)).map(l=>({w:l.day,lt:l.lt||''})));   /* số ca mỗi loại trong ngày sau khi lưu */
 for(const p of fin){if(!p.lt||!ltq[p.lt])continue;if(fin.filter(q=>q.w===p.w&&q.lt===p.lt).length>ltq[p.lt]){toast(DAYN[p.w]+': '+LTM[p.lt].n+' vượt số giờ đăng ký '+ltq[p.lt]+' giờ/ngày');return false}}
 if(ups.length||news.length){if(news.length&&!gv){toast('Hãy chọn giáo viên 1-1');return false}
  const bad=ups.map(u=>u.r).concat(news).find(p=>!slotValid(p.slot));if(bad){toast(DAYS[bad.w]+': '+slotMsg);return false}}
 /* Sửa và xóa ca đã lưu làm trước, kiểm tra trùng giờ trên trạng thái sau khi đổi; có ca nào không đổi được thì hoàn tác tất cả và chưa lưu gì. */
 if(gone.length||ups.length){const snapL=DB.lich.slice(),undo=()=>{DB.lich=snapL;ups.forEach(u=>Object.assign(u.l,u.o))};
  DB.lich=DB.lich.filter(l=>!gone.some(x=>x.id===l.id));
  ups.forEach(u=>{u.l.day=u.r.w;u.l.slot=u.r.slot});
  for(const u of ups.filter(u=>u.r.w!==u.o.day||u.r.slot!==u.o.slot)){const l=u.l,base={id:l.id,day:l.day,slot:l.slot,gv:l.gv,hs:l.hs},
    keep=l.room&&!conflict(Object.assign({},base,{room:l.room})),rm=keep?l.room:(ROOMS.find(r=>!conflict(Object.assign({},base,{room:r})))||''),
    c=rm?'':(conflict(Object.assign({},base,{room:''}))||'Không còn phòng trống');
   if(c){undo();toast(DAYS[l.day]+' '+slotLb(l.slot)+': '+c+'. Hồ sơ chưa được lưu, hãy chọn thứ hoặc giờ khác');return false}
   l.room=rm}
  ups.forEach(u=>{if(u.r.lt!==(u.o.lt||''))u.l.lt=u.r.lt||null})}
 const k=isNew?{id:newKidId(),m11:0,gv:news.length?gv:null}:old;
 Object.assign(k,{n:g('n'),g:g('g'),dob:g('dob'),sd:g('sd')||TODAY,st:g('st'),nd:g('nd'),bt,gr:bt?(g('gr')||grByAge(g('dob'))):'',pr:g('pr'),pn:g('pn'),pp:g('pp'),pe:g('pe').toLowerCase(),
  dx:[...f.querySelectorAll('input[name=dx]:checked')].map(x=>x.value),dxo:g('dxo'),dxn:g('dxn')});
 if(bt)k.btd=bd;else delete k.btd;
 if(!h11||(old11&&!act.length&&!(old11-gone.length)))delete k.lt;else if(Object.keys(ltq).length)k.lt=ltq;   /* bỏ hết ca thì bỏ luôn số giờ đã ghi; bé cũ có ca 1-1 chưa gắn loại: giữ nguyên, không bắt buộc */
 if(wasSt!=='nghi'&&k.st==='nghi')k.stopAt=TODAY;else if(k.st!=='nghi')delete k.stopAt;   /* ngưng đột ngột: không hoàn phí dư nào (xem settle) */
 if(isNew)DB.kids.push(k);if(!bt)k.gr='';
 const res=news.length?add11(k,news.map(r=>({w:r.w,lt:r.lt,slot:r.slot})),gv,room):null;
 const mvWarn=ups.map(u=>{const w=btWarn(k,u.l.day,u.l.slot);return(u.r.w!==u.o.day||u.r.slot!==u.o.slot)&&w?DAYS[u.l.day]+': '+w:''}).filter(Boolean);
 if(ups.length||gone.length)k.m11=wk11(k.id);
 const out=res||(mvWarn.length?{ok:0,bad:[],warn:[]}:null);if(out)out.warn=out.warn.concat(mvWarn);
 const flag=out&&(out.bad.length||out.warn.length),more=(ups.length?', sửa '+ups.length+' buổi 1-1':'')+(gone.length?', bỏ '+gone.length+' buổi 1-1':'');
 S.modal={t:'hs',id:k.id,tab:flag?'lh':'tt',res:out||null};
 toast(flag?'Đã lưu hồ sơ. Có buổi 1-1 chưa thêm được hoặc cần lưu ý, xem thẻ Lịch học':isNew?'Đã thêm học sinh'+(res?' và '+res.ok+' buổi 1-1':''):wasSt!=='nghi'&&k.st==='nghi'?'Đã lưu: bé ngưng can thiệp, học phí đã đóng và phí dư không hoàn':'Đã lưu hồ sơ'+(res?', thêm '+res.ok+' buổi 1-1':'')+more)};

/* --- thẻ Lịch học trong hồ sơ bé: ngày bán trú, các buổi 1-1 hằng tuần, thời khóa biểu --- */
function hsSchedule(k){const lead=isLead(),m=S.modal,bd=btOf(k),g=grBy(k.gr),$$=canMoney();
 const ls=DB.lich.filter(l=>l.type==='11'&&l.hs===k.id).sort((a,b)=>a.day-b.day||(a.slot<b.slot?-1:a.slot>b.slot?1:0)),inc=new Set(bd.map(w=>incIdW(k,w)).filter(Boolean));
 const miss=bd.filter(w=>!ls.some(l=>l.day===w));
 const bt=`<div class="card"><h2>Bán trú</h2>`+(lead?`<form id="btf" class="f"><div class="f2"><div><label for="bt-on">Học bán trú</label><select id="bt-on" name="bt">${opts([['0','Không'],['1','Có']],k.bt?'1':'0')}</select></div><div><label for="bt-gr">Lớp</label><select id="bt-gr" name="gr">${opts(DB.groups.map(x=>[x.id,x.n]),k.gr||grByAge(k.dob))}</select></div></div>
  <div style="margin-top:8px"><span class="lbl">Ngày bán trú trong tuần</span>${dayBoxes('bd',bd.length?bd:DAY_BT)}</div>
  <p class="sm mu">Mỗi ngày bán trú có một ca 1-1 (${SLOT_MIN} phút) nằm trong gói bán trú${$$?' ('+fmt(DB.cfg.pbtDay)+' mỗi ngày, trong đó '+fmt(DB.cfg.pbtDay11)+' là ca 1-1)':''}. Thứ Bảy chỉ chọn cho bé học thứ Bảy.</p>
  <div class="acts" style="justify-content:flex-end"><button class="btn p" type="submit">Lưu bán trú</button></div></form>`
  :`<p>${bd.length&&g?'Lớp <b>'+esc(g.n)+'</b>, học '+esc(dayTx(bd)):'Bé không học bán trú.'}</p>`)+`</div>`;
 const rows=ls.map(l=>`<tr><td class="nw">${DAYN[l.day]}</td><td class="nw">${slotLb(l.slot)}${l.lt&&LTM[l.lt]?'<br><span class="sm mu">'+esc(LTM[l.lt].n)+'</span>':''}</td><td>${esc(sn(l.gv))}</td><td>${esc(l.room)}</td><td>${inc.has(l.id)?tg('Ca của bán trú','in'):tg('Ca 1-1 thêm','gy')}${$$&&!inc.has(l.id)?' <span class="sm mu">'+fnum(feeSlot(k,l.id))+' ₫</span>':''}${(btWarn(k,l.day,l.slot)?'<br><span class="sm mu">Lưu ý: '+esc(btWarn(k,l.day,l.slot))+'</span>':'')}</td>${lead?`<td class="r"><button class="btn s no" data-a="hslsdel" data-v="${l.id}">Xóa</button></td>`:''}</tr>`).join('');
 const res=m.res?`<div class="note sm" style="margin-bottom:10px">${m.res.ok?'<b>Đã thêm '+m.res.ok+' buổi.</b> ':''}${m.res.bad.length?'<b>Không thêm được:</b> '+esc(m.res.bad.join('; '))+'. ':''}${m.res.warn.length?'<b>Lưu ý:</b> '+esc(m.res.warn.join('; ')):''}</div>`:'';
 const pool=pool11(),one=`<div class="card"><h2>Các buổi 1-1 hằng tuần</h2>${res}${miss.length?`<p class="note sm" style="margin-bottom:10px">Ngày bán trú chưa có ca 1-1: ${esc(miss.map(w=>DAYS[w]).join(', '))}.</p>`:''}`
  +tbl(['Thứ','Ca','Giáo viên','Phòng','Loại'].concat(lead?['']:[]),rows,'Bé chưa có buổi 1-1 cố định.')
  +(lead&&ls.length?`<p class="sm mu" style="margin-top:8px">Muốn đổi thứ, giờ hoặc loại của các ca, mở hồ sơ để sửa: mọi ca đã lưu hiện sẵn, chỉ chỉnh chỗ cần đổi.</p><div class="acts"><button class="btn s" type="button" data-a="hsedit" data-v="${k.id}">Sửa các ca trong hồ sơ</button></div>`:'')
  +(lead?`<form id="lsmf" class="f" style="margin-top:14px"><h3>Thêm buổi 1-1 cho nhiều ngày cùng lúc</h3><div class="f2"><div><label for="lm-g">Giáo viên</label><select id="lm-g" name="gv"><option value="">Chọn giáo viên</option>${opts(pool.map(s=>[s.id,tName(s)]),k.gv&&pool.some(s=>s.id===k.gv)?k.gv:'')}</select></div><div><label for="lm-s">Giờ bắt đầu</label>${slotInput('lm-s',m.slot||SLOTS[1])}<small class="mu">Ca ${SLOT_MIN} phút, tự tính giờ kết thúc.</small></div><div><label for="lm-r">Phòng</label><select id="lm-r" name="room"><option value="">Tự chọn phòng trống</option>${opts(ROOMS.map(r=>[r,r]),'')}</select></div></div>
   <div><span class="lbl">Học vào các ngày</span>${dayBoxes('d',bd.length?bd:[])}</div>
   <p class="sm mu">Mỗi bé chọn ngày riêng: có bé học T2–T7, có bé chỉ vài buổi mỗi tuần. Hệ thống kiểm tra trùng giáo viên, bé, phòng ở từng ngày và chỉ thêm những ngày còn trống.</p>
   <div class="acts" style="justify-content:flex-end"><button class="btn p" type="submit">Thêm các buổi</button></div></form>`:'')+`</div>`;
 const tt=`<div class="card"><h2>Thời khóa biểu của ${esc(given(k.n))}</h2>${kidWeek(k)}</div>`;
 return bt+one+kprCard(k)+tt}
/* Giá riêng của bé theo loại 1-1: chỉ Trưởng TT và Văn phòng thấy và sửa (là dữ liệu tiền). Bỏ trống = giá chung. Khi bỏ hết vẫn ghi {} (không xóa dòng) để máy phụ huynh đồng bộ gia tăng nhận được thay đổi. */
function kprCard(k){if(!canMoney())return'';const o=(DB.kpr||{})[k.id]||{},has=LT.some(x=>o[x.c]!=null);
 return`<div class="card"><h2>Giá riêng của bé</h2><p class="sm mu">Bỏ trống thì tính theo giá chung của loại (Nhân sự → Cài đặt). Giá riêng chỉ áp dụng cho ca 1-1 đã chọn đúng loại đó, tính từ nay; hóa đơn đã lập không tự đổi. Ca cũ chưa chọn loại thì tính theo giá chung 1 buổi 1-1.</p>
 <form id="kprf" class="f"><div class="f2">${LT.map(x=>`<div><label for="kp-${x.c}">${esc(x.n)}</label><input id="kp-${x.c}" name="kp_${x.c}" type="number" min="0" step="any" value="${o[x.c]!=null?esc(o[x.c]):''}" placeholder="${fnum(ltFee(x))} (giá chung)"></div>`).join('')}</div>
 <div class="acts" style="justify-content:flex-end">${has?`<button class="btn" type="button" data-a="kprclr" data-v="${k.id}">Bỏ hết giá riêng</button>`:''}<button class="btn p" type="submit">Lưu giá riêng</button></div></form></div>`}
FORM.kprf=f=>{if(!canMoney())return false;const k=kidBy(S.modal.id);if(!k)return false;const o={};
 LT.forEach(x=>{const v=f.elements['kp_'+x.c].value.trim();if(v!==''){const n=+v;if(isFinite(n))o[x.c]=Math.max(0,n)}});
 if(!DB.kpr)DB.kpr={};if(Object.keys(o).length||DB.kpr[k.id])DB.kpr[k.id]=o;
 toast(Object.keys(o).length?'Đã lưu giá riêng của '+given(k.n):'Không có giá riêng: '+given(k.n)+' tính theo giá chung')};
ACT.kprclr=v=>{const k=kidBy(v);if(!k||!canMoney())return false;ask('Bỏ hết giá riêng của '+given(k.n)+'? Các ca 1-1 sẽ tính theo giá chung của từng loại.',()=>{if(!DB.kpr)DB.kpr={};DB.kpr[v]={};toast('Đã bỏ giá riêng')},'Bỏ')};
FORM.btf=f=>{if(!isLead())return false;const k=kidBy(S.modal.id),bt=f.elements.bt.value==='1',bd=daysOf(f,'bd');
 if(bt&&!bd.length){toast('Hãy chọn ít nhất một ngày bán trú');return false}
 k.bt=bt;if(bt){k.gr=f.elements.gr.value||grByAge(k.dob);k.btd=bd}else{k.gr='';delete k.btd}
 S.modal.res=null;toast('Đã lưu lịch bán trú')};
FORM.lsmf=f=>{if(!isLead())return false;const k=kidBy(S.modal.id),e=f.elements,gv=e.gv.value,slot=String(e.slot.value||'').slice(0,5),days=daysOf(f,'d');
 if(!gv){toast('Hãy chọn giáo viên');return false}
 if(!slotValid(slot)){toast(slotMsg);return false}
 if(!days.length){toast('Hãy chọn ít nhất một ngày');return false}
 const res=add11(k,days.map(w=>({w,slot})),gv,e.room.value);
 S.modal.res=res;S.modal.slot=slot;
 if(res.ok&&!res.bad.length)toast('Đã thêm '+res.ok+' buổi 1-1')};
ACT.hslsdel=v=>{const l=DB.lich.find(x=>x.id===v),k=l&&kidBy(l.hs),back=S.modal;if(!l||!k||!isLead())return false;
 ask('Xóa buổi 1-1 '+DAYN[l.day]+' '+slotLb(l.slot)+' của bé '+k.n+'? Các lần điểm danh trước đây vẫn được giữ.',()=>{DB.lich=DB.lich.filter(x=>x.id!==v);k.m11=wk11(k.id);S.modal=Object.assign({},back,{res:null});toast('Đã xóa buổi học')},'Xóa buổi')};

/* --- xóa hồ sơ bé (Trưởng Trung tâm, Quản lý): nhập sai hoặc bé không còn học; bé chỉ nghỉ thì dùng "Ngưng can thiệp" --- */
function hsDelKid(id){
 if(DB.kpr)delete DB.kpr[id];
 DB.kids=DB.kids.filter(x=>x.id!==id);
 DB.sess=DB.sess.filter(x=>x.k!==id);
 DB.plans=DB.plans.filter(x=>x.k!==id);
 DB.lich=DB.lich.filter(x=>x.hs!==id);
 DB.mk=DB.mk.filter(x=>x.hs!==id);
 DB.rp=DB.rp.filter(x=>x.hs!==id);
 DB.lg=DB.lg.filter(x=>x.hs!==id);
 DB.media.forEach(m=>{if(Array.isArray(m.ks)&&m.ks.includes(id))m.ks=m.ks.filter(x=>x!==id)});
 Object.keys(DB.att).forEach(x=>{if(x.split('|').includes(id))delete DB.att[x]});
 Object.keys(DB.set).forEach(x=>{if(x.split('|').includes(id))delete DB.set[x]});
}
ACT.hsdelk=v=>{const k=kidBy(v);if(!k||!isLead()||!canKid(k.id))return false;
 const n=DB.sess.filter(s=>s.k===k.id).length;
 ask('Xóa hồ sơ của bé '+k.n+' ('+kcode(k)+')? Sẽ xóa cả '+n+' buổi can thiệp, kế hoạch, lịch 1-1, điểm danh, báo cáo và học phí của bé. Không hoàn tác được. Nếu bé chỉ nghỉ, hãy dùng “Ngưng can thiệp” thay vì xóa.',()=>{hsDelKid(k.id);S.modal=null;toast('Đã xóa hồ sơ bé '+k.n);render()},'Xóa hồ sơ');return false};
/* ===== 3b. Can thiệp cá nhân: kế hoạch mục tiêu, buổi can thiệp, ngân hàng mục tiêu ===== */
const trunc=(s,n)=>s.length>n?s.slice(0,n-1)+'…':s;
const domTag=(d,g)=>g&&isPlay(g)?`<span class="tag gy" title="Chơi (thuộc lĩnh vực ${esc(DM[d].n)})">Chơi</span>`:`<span class="tag gy" title="${esc(DM[d].n)}">${esc(DM[d].s)}</span>`;
const supTag=s=>`<span class="sp sp-${s}" title="${esc(SUP[s].n+': '+SUP[s].h)}">${esc(SUP[s].n)}</span>`;
const strip=tr=>`<span class="trs" role="img" aria-label="${trOk(tr)} lượt đúng trên ${trN(tr)} lượt">${tr.split('').map(c=>`<i class="${c==='V'?'tv':c==='X'?'tx':'to'}"></i>`).join('')}</span>`;
/* người phụ trách bé: giáo viên 1-1 của bé, nếu không có thì mọi giáo viên của lớp bán trú (ngang nhau) */
const kidGVs=k=>k.gv?[k.gv]:grTs(grBy(k.gr));
const kidGV=k=>kidGVs(k)[0]||'';
const canEditSess=s=>!!U&&canKid(s.k)&&(isLead()||(isGV()&&(s.by===U.id||kidGVs(kidBy(s.k)||{}).includes(U.id))&&s.date>=addD(TODAY,-14)));
const planBy=id=>DB.plans.find(p=>p.id===id);
function addPlanItem(k,g,h,up){if(DB.plans.some(p=>p.k===k&&p.g===g&&p.s!=='dat'))return false;const o={id:'p'+uid(),k,g,h,s:'dang',from:TODAY,due:addD(TODAY,HZ[h][2]),by:U?U.id:''},l=h==='n'&&up?planBy(up):null;if(l&&l.k===k&&l.h==='d')o.up=up;DB.plans.push(o);return o.id}

/* ---------- Kế hoạch mục tiêu của từng bé ---------- */
function planRow(p){const g=goalOf(p.g),m=masteryOf(p.k,p.g),lr=m.last,ready=m.ready&&p.s==='dang';
 const spark=m.rs.slice(-8).map(r=>{const sc=recSc(r);return`<i style="height:${Math.max(8,sc)}%" title="${sc}/100"></i>`}).join('');
 return`<div class="pl ${p.s==='dat'?'dn':''}"><div class="pl-m"><b>${esc(g?g.n:'(mục tiêu đã xóa)')}</b><div class="sm mu">${g?esc(g.t)+' · '+esc(gSrc(g))+(g.a?' · '+esc(g.a):''):''}</div>
 <div class="pl-t">${g?domTag(g.d,g):''} ${tg(PST[p.s][0],PST[p.s][1])}${ready?' '+tg('Đủ điều kiện đạt','ok'):''} <span class="sm mu">Từ ${vdm(p.from)} · hạn ${vdm(p.due)}${p.dt?' · đạt '+vdm(p.dt):''}</span></div>${g?gxHtml(g,'s',{open:1}):''}</div>
 <div class="pl-r">${lr?`${supTag(lr.sup)} <b>${trPct(lr.tr)}%</b><span class="spk" aria-hidden="true">${spark}</span><span class="sm mu">${m.cnt} buổi</span>`:'<span class="sm mu">Chưa có số liệu</span>'}</div>
 <div class="pl-a">${p.s==='dang'?`<button class="btn s" data-a="plok" data-v="${p.id}">Đánh dấu đạt</button><button class="btn s" data-a="pltam" data-v="${p.id}">Tạm dừng</button>`:`<button class="btn s" data-a="plre" data-v="${p.id}">${p.s==='dat'?'Mở lại':'Tiếp tục'}</button>`}<button class="btn s" data-a="plhz" data-v="${p.id}">${p.h==='n'?'Chuyển sang dài hạn':'Chuyển sang ngắn hạn'}</button><button class="btn s no" data-a="pldel" data-v="${p.id}">Bỏ</button></div></div>`}
function hsPlan(k){const ps=kidPlans(k.id),done=ps.filter(p=>p.s==='dat'),tr=gtStaff(k),T=tr.T,ready=T.shorts.concat(T.longs).filter(n=>n.ready);
 const sug=done.filter(p=>p.dt&&p.dt>=addD(TODAY,-60)).map(p=>nextOf(p.g)).filter(g=>g&&!ps.some(q=>q.g===g.id)).slice(0,3);
 let h=`<div class="acts" style="margin-bottom:12px"><button class="btn p" data-a="pkopen" data-v="${k.id}">Chọn mục tiêu từ ngân hàng</button><button class="btn" data-a="senew" data-v="${k.id}">Ghi buổi can thiệp</button></div>`;
 if(ready.length)h+=`<div class="note" style="margin-bottom:12px"><b>${ready.length} mục tiêu đủ điều kiện đạt</b> (mọi mục tiêu con đã đạt: bé tự làm đúng từ 80% trở lên trong 3 buổi liên tiếp): ${ready.map(n=>esc(gName(n.p.g))).join('; ')}. Hãy kiểm tra rồi bấm “Đánh dấu đạt”.</div>`;
 h+=tr.html;
 if(sug.length)h+=`<div class="note" style="margin-top:12px"><b>Gợi ý mục tiêu kế tiếp</b> (liền sau mục tiêu vừa đạt trong ngân hàng mục tiêu)${sug.map(g=>`<div class="rw"><span>${esc(g.n)}<br><span class="sm mu">${esc(gSrc(g))}</span></span><button class="btn s p" data-a="plnext" data-v="${k.id}|${g.id}">Thêm vào kế hoạch</button></div>`).join('')}</div>`;
 return h}
const planBack=k=>{S.modal={t:'hs',id:k,tab:'kh'}};
ACT.plok=v=>{const p=planBy(v);if(p){p.s='dat';p.dt=TODAY;toast('Đã đánh dấu đạt: '+trunc(gName(p.g),40))}};
ACT.pltam=v=>{const p=planBy(v);if(p)p.s='tam'};
ACT.plre=v=>{const p=planBy(v);if(p){p.s='dang';delete p.dt}};
ACT.plhz=v=>{const p=planBy(v);if(p){p.h=p.h==='n'?'d':'n';p.due=addD(p.from,HZ[p.h][2]);delete p.up;if(p.h==='n')DB.plans.forEach(q=>{if(q.up===p.id)delete q.up})}};
ACT.pldel=v=>{const p=planBy(v);if(!p)return false;const nc=p.h==='d'?DB.plans.filter(q=>q.up===v).length:0;ask('Bỏ mục tiêu “'+gName(p.g)+'” khỏi kế hoạch? Số liệu các buổi đã ghi vẫn được giữ lại.'+(nc?' '+nc+' mục tiêu ngắn hạn thuộc mục tiêu này sẽ chuyển sang nhóm chưa gắn mục tiêu dài hạn.':''),()=>{DB.plans.forEach(q=>{if(q.up===v)delete q.up});DB.plans=DB.plans.filter(x=>x.id!==v);planBack(p.k)},'Bỏ')};
ACT.plnext=v=>{const [k,g]=v.split('|'),src=DB.plans.find(p=>p.k===k&&p.s==='dat'&&nextOf(p.g)&&nextOf(p.g).id===g);if(addPlanItem(k,g,'n',src&&src.h==='n'?src.up:''))toast('Đã thêm vào kế hoạch ngắn hạn')};

/* ---------- Danh sách buổi can thiệp ---------- */
function sessCard(s,showKid){const k=kidBy(s.k),pl=s.st==='kh',rs=s.it.filter(i=>trN(i.tr)),pc=rs.length?Math.round(avg(rs.map(recSc))):null;
 return`<div class="sess"><div class="sess-h"><div><b>${DAYS[dow(s.date)]} ${vd(s.date)}</b>${showKid&&k?' · <b>'+esc(k.n)+'</b>':''} <span class="sm mu">· ${esc(given(sn(s.by)))}</span> ${pl?tg('Kế hoạch','y'):tg('Đã ghi','ok')}${pc!=null?' <span class="sm mu">chỉ số tự làm '+pc+'</span>':''}</div><div class="acts"><button class="btn s" data-a="sesview" data-v="${s.id}">Xem</button>${canEditSess(s)?`<button class="btn s ${pl?'p':''}" data-a="seedit" data-v="${s.id}">${pl?'Ghi kết quả':'Sửa'}</button>`:''}</div></div>
 <div class="sess-d">${(s.dom||[]).map(domTag).join(' ')}</div>
 <ul class="sess-i">${s.it.map(i=>`<li><span class="gn">${esc(gName(i.g))}</span> ${supTag(i.sup)} ${trN(i.tr)?strip(i.tr)+' <b>'+trPct(i.tr)+'%</b>':'<span class="sm mu">chưa ghi kết quả</span>'}</li>`).join('')}</ul>
 ${s.note?`<p class="sm"><b>Nhận xét:</b> ${esc(s.note)}</p>`:''}${s.home?`<p class="sm"><b>Gợi ý ở nhà:</b> ${esc(s.home)}</p>`:''}</div>`}
function hsSess(k){const ss=sessOf(k.id,'','9999-12-31',true).reverse();
 return`<div class="acts" style="margin-bottom:12px"><button class="btn p" data-a="senew" data-v="${k.id}">Ghi buổi can thiệp</button><span class="sm mu">${ss.filter(s=>s.st==='xong').length} buổi đã ghi${ss.some(s=>s.st==='kh')?', '+ss.filter(s=>s.st==='kh').length+' buổi kế hoạch':''}</span></div>`+(ss.length?ss.slice(0,10).map(s=>sessCard(s,false)).join(''):'<p class="empty">Chưa có buổi can thiệp nào. Bấm “Ghi buổi can thiệp” để bắt đầu.</p>')+(ss.length>10?'<p class="sm mu">Hiển thị 10 buổi gần nhất.</p>':'')}
ACT.sesview=v=>{S.modal={t:'sev',id:v,back:S.modal&&S.modal.t==='hs'?S.modal:null}};
MODALS.sev=()=>{const s=DB.sess.find(x=>x.id===S.modal.id);if(!s||!canKid(s.k)){S.modal=null;return''}const k=kidBy(s.k),pl=s.st==='kh';
 return mdl('Buổi can thiệp · '+k.n,`<p class="mu sm" style="margin-bottom:10px">${DAYN[dow(s.date)]}, ${vd(s.date)} · Giáo viên ${esc(sn(s.by))} · ${pl?'Kế hoạch buổi, chưa ghi kết quả':'Đã ghi kết quả'}</p><div class="sess-d" style="margin-bottom:8px">${(s.dom||[]).map(domTag).join(' ')}</div>`
 +tbl(['Mục tiêu','Mức hỗ trợ','Kết quả','>Đúng','>Chỉ số tự làm'],s.it.map(i=>{const g=goalOf(i.g),sc=recSc(i);return`<tr><td>${esc(g?g.n:'(mục tiêu đã xóa)')}<br><span class="sm mu">${g?esc(g.t)+' · '+esc(gSrc(g)):''}</span>${i.nt?`<br><span class="sm">Ghi chú: ${esc(i.nt)}</span>`:''}</td><td>${supTag(i.sup)}</td><td>${trN(i.tr)?strip(i.tr):'<span class="sm mu">Chưa ghi</span>'}</td><td class="r nw">${trN(i.tr)?trOk(i.tr)+'/'+trN(i.tr)+' ('+trPct(i.tr)+'%)':'–'}</td><td class="r">${sc==null?'–':sc}</td></tr>`}).join(''))
 +(s.note?`<p style="margin-top:10px"><b>Nhận xét:</b> ${esc(s.note)}</p>`:'')+(s.home?`<p style="margin-top:6px"><b>Gợi ý luyện tập ở nhà:</b> ${esc(s.home)}</p>`:'')
 +`<div class="acts" style="margin-top:14px;justify-content:flex-end">${S.modal.back?'<button class="btn" data-a="sevback">Quay lại hồ sơ bé</button>':''}${canEditSess(s)?`<button class="btn no" data-a="sedel" data-v="${s.id}">Xóa buổi</button><button class="btn p" data-a="seedit" data-v="${s.id}">${pl?'Ghi kết quả':'Sửa buổi'}</button>`:''}</div>`,1)};
ACT.sevback=()=>{S.modal=S.modal.back||null};
ACT.sedel=v=>{const s=DB.sess.find(x=>x.id===v);if(!s||!canEditSess(s))return false;const back=S.modal.back||null;ask('Xóa buổi can thiệp ngày '+vd(s.date)+' của bé '+kn(s.k)+'? Số liệu của buổi này sẽ không còn trong biểu đồ tiến bộ.',()=>{DB.sess=DB.sess.filter(x=>x.id!==v);S.modal=back;toast('Đã xóa buổi can thiệp')},'Xóa')};

/* ---------- Biểu mẫu ghi buổi can thiệp (theo mẫu ghi dữ liệu của Trung tâm) ---------- */
function seStart(o){const k=kidBy(o.k);if(!k||!canKid(k.id)){toast('Bạn chưa có quyền ghi buổi can thiệp cho bé này');return false}
 const back=S.modal&&S.modal.t==='hs'?S.modal:null,ex=o.id?DB.sess.find(s=>s.id===o.id):DB.sess.find(s=>s.k===o.k&&s.date===o.date&&(isLead()||s.by===U.id));
 if(ex){S.modal={t:'se',id:ex.id,k:ex.k,date:ex.date,by:ex.by,dom:(ex.dom||[]).slice(),it:ex.it.map(i=>Object.assign({nt:''},i,{pl:sePlOf(ex.k,i)})),note:ex.note||'',home:ex.home||'',back};return}
 const m={t:'se',id:'',k:o.k,date:o.date,by:isGV()?U.id:(kidGV(k)||U.id),dom:[],it:[],note:'',home:'',back};
 const act=kidPlans(o.k,'dang'),pool=act.some(p=>p.h==='n')?act.filter(p=>p.h==='n'):act,T=gtTree(o.k);
 pool.sort((a,b)=>(a.h<b.h?1:a.h>b.h?-1:0)||((lastRec(o.k,a.g)||{d:''}).d<(lastRec(o.k,b.g)||{d:''}).d?-1:1)).slice(0,3).forEach(p=>{const nd=T.shorts.find(s=>s.p.id===p.id),op=nd?nd.gs.find(x=>x.st!=='dat'):null;seAddTo(m,[op?op.g:p.g],p.h==='n'?p.id:'')});
 S.modal=m}
/* pl: mã kế hoạch ngắn hạn mà dòng mục tiêu này thuộc về; bỏ trống thì lấy theo lần luyện trước hoặc kế hoạch có cùng mục tiêu */
function sePlOf(k,i){const p=i.pl?planBy(i.pl):null;if(p&&p.k===k&&p.h==='n')return p.id;const o=kidPlans(k).find(q=>q.g===i.g&&q.h==='n'&&q.s!=='dat')||kidPlans(k).find(q=>q.g===i.g&&q.h==='n');return o?o.id:''}
function seAddTo(m,ids,pl){ids.forEach(g=>{if(m.it.some(i=>i.g===g))return;const lr=lastRec(m.k,g);m.it.push({g,sup:lr?lr.sup:'GP',tr:TR0,nt:'',pl:pl!==undefined?pl:sePlOf(m.k,lr?{g,pl:lr.pl}:{g})});const d=gDom(g);if(!m.dom.includes(d))m.dom.push(d)})}
ACT.senew=v=>{const [k,d]=v.split('|');return seStart({k,date:d||(WD<=TODAY?WD:TODAY)})};
ACT.seedit=v=>{const s=DB.sess.find(x=>x.id===v);if(!s||!canEditSess(s)){toast('Bạn chưa thể sửa buổi này');return false}return seStart({k:s.k,id:s.id,date:s.date})};
ACT.seclose=()=>{S.modal=S.modal.back||null};
CHG.sef=(v,t)=>{S.modal[t.dataset.f]=v;return false};
CHG.sein=(v,t)=>{S.modal.it[+t.dataset.v].nt=v;return false};
CHG.sepl=(v,t)=>{S.modal.it[+t.dataset.v].pl=v};
ACT.sedom=v=>{const m=S.modal;m.dom=m.dom.includes(v)?m.dom.filter(x=>x!==v):m.dom.concat(v)};
ACT.seadd=v=>{seAddTo(S.modal,[v])};
ACT.serm=v=>{S.modal.it.splice(+v,1)};
ACT.sesup=v=>{const [x,s]=v.split('|');S.modal.it[+x].sup=s};
ACT.setr=v=>{const [x,p]=v.split('|').map(Number),it=S.modal.it[x],c=it.tr[p];it.tr=it.tr.slice(0,p)+(c==='.'?'V':c==='V'?'X':'.')+it.tr.slice(p+1)};
ACT.setrc=v=>{S.modal.it[+v].tr=TR0};
ACT.sepick=v=>{const m=S.modal;S.modal={t:'gp',mode:'ses',k:m.k,back:m,f:{dom:v||'',src:'',head:'',age:'',q:''},sel:[],hz:'n',pl:'auto'};S.pg.gp=1};
const sePlOpts=(k,cur)=>[['','— Chưa gắn mục tiêu ngắn hạn —']].concat(kidPlans(k).filter(p=>p.h==='n'&&(p.s!=='dat'||p.id===cur)).map(p=>[p.id,gName(p.g)]));
function sePlChain(pl){const p=pl?planBy(pl):null;if(!p)return'<div class="sm mu gt-ch">Chưa gắn: dòng này vẫn tính vào biểu đồ tiến bộ nhưng chưa nằm trong cây mục tiêu.</div>';const l=gtUp(p);
 return`<div class="sm gt-ch">⇒ Mục tiêu ngắn hạn: <b>${esc(gName(p.g))}</b>${l?` ⇒ Mục tiêu dài hạn: <b>${esc(gName(l.g))}</b>`:' <span class="mu">(chưa gắn mục tiêu dài hạn)</span>'}</div>`}
function seItem(i,x){const g=goalOf(i.g),n=trN(i.tr);
 return`<div class="si"><div class="si-h"><div><b>${esc(g?g.n:'(mục tiêu đã xóa)')}</b><div class="sm mu">${g?esc(g.t)+' · '+esc(gSrc(g)):''}</div></div><button class="btn s no" data-a="serm" data-v="${x}" aria-label="Bỏ mục tiêu này khỏi buổi">Bỏ</button></div>
 ${g?gxHtml(g,'s',{open:1}):''}<div class="si-l">Thuộc mục tiêu ngắn hạn <span class="mu">· mục tiêu buổi ⇒ ngắn hạn ⇒ dài hạn</span></div><select class="si-pl" data-c="sepl" data-v="${x}" aria-label="Thuộc mục tiêu ngắn hạn">${opts(sePlOpts(S.modal.k,i.pl||''),i.pl||'')}</select>${sePlChain(i.pl)}
 <div class="si-l">Mức hỗ trợ</div><div class="seg" role="group" aria-label="Mức hỗ trợ">${SUPK.map(s=>`<button type="button" class="sg sp-${s} ${i.sup===s?'on':''}" data-a="sesup" data-v="${x}|${s}" aria-pressed="${i.sup===s}" title="${esc(SUP[s].n+': '+SUP[s].h)}">${esc(SUP[s].a)}</button>`).join('')}</div>
 <div class="si-l">Kết quả 10 lượt <span class="mu">· chạm một lần: đúng, hai lần: sai, ba lần: bỏ trống</span></div>
 <div class="trb" role="group" aria-label="Kết quả từng lượt">${i.tr.split('').map((c,p)=>`<button type="button" class="tb tb-${c==='V'?'v':c==='X'?'x':'o'}" data-a="setr" data-v="${x}|${p}" aria-label="Lượt ${p+1}: ${c==='V'?'đúng':c==='X'?'sai':'chưa làm'}">${c==='V'?'✓':c==='X'?'✗':p+1}</button>`).join('')}</div>
 <div class="si-f"><span class="sm">${n?`<b>${trOk(i.tr)}/${n}</b> đúng · <b>${trPct(i.tr)}%</b> · ${esc(SUP[i.sup].p)}`:'<span class="mu">Chưa ghi kết quả</span>'}</span>${n?`<button class="btn s" data-a="setrc" data-v="${x}">Xóa kết quả</button>`:''}</div>
 <input class="sm" placeholder="Ghi chú riêng cho mục tiêu này (không bắt buộc)" value="${esc(i.nt||'')}" data-c="sein" data-v="${x}" aria-label="Ghi chú mục tiêu"></div>`}
MODALS.se=()=>{const m=S.modal,k=kidBy(m.k);if(!k||!canKid(k.id)){S.modal=null;return''}
 const free=kidPlans(k.id,'dang').filter(p=>!m.it.some(i=>i.g===p.g)),sug=(m.dom.length?free.filter(p=>m.dom.includes(gDom(p.g))):free).slice(0,6),hasRes=m.it.some(i=>trN(i.tr));
 return mdl((m.id?'Sửa buổi can thiệp':'Ghi buổi can thiệp')+' · '+k.n,
 `<p class="mu sm" style="margin-bottom:10px">${age(k.dob)} · ${esc(k.nd)}. Chọn lĩnh vực và mục tiêu của buổi, rồi ghi mức hỗ trợ và kết quả từng lượt. Nếu chưa dạy, lưu như kế hoạch buổi và ghi kết quả sau.</p>
 <div class="f2"><div><label for="se-d">Ngày</label><input id="se-d" type="date" value="${m.date}" max="${addD(TODAY,30)}" data-c="sef" data-f="date"></div><div><label for="se-by">Giáo viên</label>${isLead()?`<select id="se-by" data-c="sef" data-f="by">${opts(DB.staff.filter(isTeacher).map(s=>[s.id,tName(s)]),m.by)}</select>`:`<input id="se-by" value="${esc(sn(m.by))}" disabled>`}</div></div>
 <div style="margin-top:12px"><span class="lb">Lĩnh vực cần can thiệp trong buổi</span><div class="chips">${LDOM.map(d=>`<button type="button" class="chip ${m.dom.includes(d.id)?'on':''}" data-a="sedom" data-v="${d.id}" aria-pressed="${m.dom.includes(d.id)}" title="${esc(d.d)}">${esc(d.s)}</button>`).join('')}</div></div>
 <h3 style="margin-top:14px">Mục tiêu của buổi (${m.it.length})</h3>${m.it.map(seItem).join('')||'<p class="mu sm">Chưa chọn mục tiêu. Chọn từ kế hoạch của bé hoặc từ ngân hàng mục tiêu.</p>'}
 <div class="acts" style="margin:10px 0">${sug.map(p=>`<button class="btn s" data-a="seadd" data-v="${p.g}" title="${esc(gName(p.g))}">+ ${esc(trunc(gName(p.g),42))}</button>`).join('')}${m.dom.map(d=>`<button class="btn s p" data-a="sepick" data-v="${d}">Chọn mục tiêu ${esc(DM[d].s)}</button>`).join('')}<button class="btn s ${m.dom.length?'':'p'}" data-a="sepick" data-v="">${m.dom.length?'Chọn từ toàn bộ ngân hàng mục tiêu':'Chọn từ ngân hàng mục tiêu'}</button></div>
 <div class="f2"><div><label for="se-n">Nhận xét chung về buổi</label><textarea id="se-n" rows="3" data-c="sef" data-f="note">${esc(m.note)}</textarea></div><div><label for="se-h">Gợi ý luyện tập tại nhà</label><textarea id="se-h" rows="3" data-c="sef" data-f="home">${esc(m.home)}</textarea></div></div>
 <div class="gp-f" style="justify-content:flex-end"><button class="btn" data-a="seclose">Hủy</button><button class="btn p" data-a="sesave">${hasRes?'Lưu buổi can thiệp':'Lưu kế hoạch buổi'}</button></div>`,1)};
ACT.sesave=()=>{const m=S.modal,k=kidBy(m.k);if(!k||!canKid(k.id))return false;
 if(!m.date){toast('Hãy chọn ngày');return false}
 if(!m.it.length){toast('Hãy chọn ít nhất một mục tiêu cho buổi');return false}
 const it=m.it.map(i=>{const o={g:i.g,sup:i.sup,tr:i.tr};if(i.nt&&i.nt.trim())o.nt=i.nt.trim();const pp=i.pl?planBy(i.pl):null;if(pp&&pp.k===m.k&&pp.h==='n')o.pl=pp.id;return o}),done=it.some(i=>trN(i.tr));
 if(done&&m.date>TODAY){toast('Chưa đến ngày này nên chưa ghi kết quả được');return false}
 const o={k:m.k,date:m.date,by:m.by,st:done?'xong':'kh',dom:[...new Set(m.dom.concat(it.map(i=>gDom(i.g))))],it,note:(m.note||'').trim(),home:(m.home||'').trim()};
 if(m.id)Object.assign(DB.sess.find(s=>s.id===m.id),o);else DB.sess.push(Object.assign({id:'s'+uid()},o));
 const rd=it.filter(i=>trN(i.tr)).map(i=>i.g).filter(g=>{const p=kidPlans(m.k,'dang').find(q=>q.g===g);return p&&masteryOf(m.k,g).ready});
 toast(done?(rd.length?'Đã lưu buổi can thiệp. Có mục tiêu đủ điều kiện đạt, xem tab Kế hoạch mục tiêu':'Đã lưu buổi can thiệp'):'Đã lưu kế hoạch buổi');
 S.modal=m.back?Object.assign({},m.back,{tab:'bt'}):null};

/* ---------- Trang tổng hợp "Buổi can thiệp" ---------- */
CHG.bidate=v=>{if(v)S.hs.bi.date=v};CHG.bigv=v=>{S.hs.bi.gv=v;S.pg.bi=1};INP.biq=v=>{S.hs.bi.q=v;S.pg.bi=1};
ACT.biday=v=>{let d=addD(S.hs.bi.date,+v);if(!isW(d))d=addD(d,+v);S.hs.bi.date=d};
function hsBi(){const b=S.hs.bi,date=b.date,q=b.q.toLowerCase();
 const ds=dayList(date).filter(s=>s.kind!=='bt').filter(s=>isLead()?(!b.gv||s.gv===b.gv):s.gv===U.id);
 const ofDay=k=>DB.sess.filter(s=>s.k===k.id&&s.date===date);
 let nDone=0,nPlan=0,nNone=0;ds.forEach(s=>{const x=ofDay(s.kids[0]);if(x.some(y=>y.st==='xong'))nDone++;else if(x.length)nPlan++;else nNone++});
 const rows=ds.map(s=>{const k=s.kids[0],x=ofDay(k),a=DB.att[attKey(date,s.sid,k.id)],st=x.some(y=>y.st==='xong')?'xong':x.length?'kh':'';
  return`<div class="rw"><span><b>${esc(k.n)}</b> <span class="sm mu">· ${age(k.dob)}</span><br><span class="sm">${slotLb(s.slot)}${s.kind==='bu'?' '+tg('Học bù','y'):''} · ${esc(given(sn(s.gv)))}</span><br>${a?tg(AC[a],a==='cm'?'ok':a==='kp'?'er':'gy'):'<span class="sm mu">Chưa điểm danh</span>'} ${st==='xong'?tg('Đã ghi','ok'):st==='kh'?tg('Kế hoạch','y'):tg('Chưa ghi','wa')}</span><span class="acts">${x.length?`<button class="btn s" data-a="sesview" data-v="${x[0].id}">Xem</button>`:''}${canKid(k.id)&&date<=addD(TODAY,30)?`<button class="btn s ${st==='xong'?'':'p'}" data-a="senew" data-v="${k.id}|${date}">${st==='xong'?'Sửa':st==='kh'?'Ghi kết quả':'Ghi buổi'}</button>`:''}</span></div>`}).join('');
 const recent=DB.sess.filter(s=>canKid(s.k)&&(!q||kn(s.k).toLowerCase().includes(q))).sort((a,c)=>a.date<c.date?1:a.date>c.date?-1:0),pgd=pg('bi',recent,8);
 return`<div class="grid">${kpi('Lượt 1-1 trong ngày',ds.length,DAYN[dow(date)]+', '+vd(date))}${kpi('Đã ghi buổi',nDone,'có kết quả','ok')}${kpi('Kế hoạch',nPlan,'chưa ghi kết quả')}${kpi('Chưa ghi',nNone,'cần ghi',nNone&&date<=TODAY?'er':'')}</div>
 <div class="card"><div class="f2"><div><label for="bi-d">Ngày</label><input id="bi-d" type="date" data-c="bidate" value="${date}"></div>${isLead()?`<div><label for="bi-g">Giáo viên</label><select id="bi-g" data-c="bigv"><option value="">Tất cả</option>${opts(DB.staff.filter(isTeacher).map(s=>[s.id,tName(s)]),b.gv)}</select></div>`:''}<div style="display:flex;align-items:end;gap:6px"><button class="btn s" data-a="biday" data-v="-1">Ngày trước</button><button class="btn s" data-a="biday" data-v="1">Ngày sau</button></div></div></div>
 <div class="card"><h2>Buổi 1-1 và học bù ngày ${vd(date)}</h2>`+(rows||`<p class="empty">${dow(date)===0?'Chủ nhật trung tâm nghỉ.':'Không có buổi 1-1 nào trong ngày này.'}</p>`)+`<p class="sm mu" style="margin-top:8px">Bé bán trú được ghi buổi trong hồ sơ từng bé: mở hồ sơ, vào tab Buổi can thiệp.</p></div>
 <div class="card"><div class="top" style="margin-bottom:10px"><h2 style="margin:0">Các buổi can thiệp gần đây</h2><div style="min-width:220px"><label for="bi-q" class="sm">Tìm theo tên bé</label><input id="bi-q" data-i="biq" value="${esc(b.q)}"></div></div>`+(pgd.rows.map(s=>sessCard(s,true)).join('')||'<p class="empty">Chưa có buổi nào.</p>')+pgd.html+`</div>`}

/* ---------- Ngân hàng mục tiêu: bộ lọc dùng chung cho tra cứu và chọn mục tiêu ---------- */
const LF=()=>S.modal&&S.modal.t==='gp'?S.modal.f:S.hs.lib,LPG=()=>S.modal&&S.modal.t==='gp'?'gp':'lib';
ACT.lfdom=v=>{const f=LF();f.dom=v;f.head='';S.pg[LPG()]=1};
CHG.lfsrc=v=>{const f=LF();f.src=v;f.head='';f.vbd='';S.pg[LPG()]=1};
CHG.lfhead=v=>{const f=LF();f.head=v;f.vbd='';S.pg[LPG()]=1};
CHG.lfvbd=v=>{LF().vbd=v};
ACT.lfvbt=()=>{const f=LF();f.vbo=!f.vbo};
CHG.lfage=v=>{LF().age=v;S.pg[LPG()]=1};
INP.lfq=v=>{LF().q=v;S.pg[LPG()]=1};
ACT.lfclr=()=>{Object.assign(LF(),{dom:'',src:'',head:'',age:'',q:''});S.pg[LPG()]=1};
/* --- VB-MAPP: chi tiết mốc và bước nhỏ, bảng phương hướng can thiệp --- */
function vbBul(t){const a=String(t||'').split(/\s*\(\d+\)\s*/).map(s=>s.trim()).filter(Boolean).map(s=>s.charAt(0).toUpperCase()+s.slice(1));return a.length>1?`<ul>${a.map(s=>`<li>${esc(s)}</li>`).join('')}</ul>`:`<p>${esc(a[0]||'')}</p>`}
const vbMark=x=>x==='T'?'Kiểm tra trực tiếp (T)':x==='O'?'Quan sát (O)':x==='E'?'Kiểm tra hoặc quan sát (E)':/^TO:/.test(x)?'Quan sát trong thời gian giới hạn '+x.slice(3)+' phút (TO)':'';
function vbDetail(i){const D=LVBD[i.sk]||{},key='vb:'+i.sk+i.ms,par=i.st?GL[key]:null,nst=VBC[key];
 return(i.st?`<p><b>Bước nhỏ ${i.ms+i.st}</b> của mốc ${i.ms}${par?': '+esc(par.n):''}</p>`:`<p><b>Mốc ${i.ms}</b> của kỹ năng ${esc(i.t)}${nst?'. Có '+nst+' bước nhỏ ('+i.ms+'a đến '+i.ms+String.fromCharCode(96+nst)+') để dạy từng bước':' (tài liệu gốc chưa chia bước nhỏ)'}.</p>`)
 +(i.x&&vbMark(i.x)?`<p><b>Cách đánh giá:</b> ${esc(vbMark(i.x))}</p>`:'')
 +(D[i.ms]?`<p><b>Phương hướng can thiệp ở mốc ${i.ms}:</b></p>${vbBul(D[i.ms])}`:'')
 +(i.ms===1&&D[0]?`<p><b>Khi bé chưa đạt mốc nào (điểm 0):</b></p>${vbBul(D[0])}`:'')
 +(i.a?`<p><b>Cấp độ:</b> ${esc(i.a)}</p>`:'')}
function vbPanel(f,P){const open=!!f.vbo,sk=f.vbd||(f.head!==''&&f.head!=null&&VBHK[f.head])||'YC',D=LVBD[sk]||{},ks=Object.keys(D).map(Number).sort((a,b)=>a-b);
 return`<div class="vbp"><button type="button" class="btn s" data-a="lfvbt" aria-expanded="${open}">${open?'Ẩn':'Xem'} bảng phương hướng can thiệp VB-MAPP</button>`
 +(open?`<div class="note" style="margin-top:8px"><label for="${P}-vd">Kỹ năng</label><select id="${P}-vd" data-c="lfvbd">${opts(LVBS,sk)}</select>${ks.map(k=>`<div class="rw" style="align-items:flex-start;flex-wrap:nowrap"><span class="sm" style="width:58px;flex:none"><b>${k===0?'Điểm 0':'Mốc '+k}</b></span><span class="sm" style="flex:1;min-width:0">${vbBul(D[k])}</span></div>`).join('')}</div>`:'')+`</div>`}
function libDetail(i){if(i.s==='vb')return`<details class="gd"><summary class="sm">Chi tiết</summary><div class="sm">${vbDetail(i)}</div></details>`;
 const x=i.s==='ot'?'Cách làm gợi ý':'Ví dụ';
 return`<details class="gd"><summary class="sm">Chi tiết</summary><div class="sm">${i.o?`<p><b>${i.s==='ot'?'Mục đích':'Mô tả'}:</b> ${esc(i.o)}</p>`:''}${i.x?`<p><b>${x}:</b> ${esc(i.x)}</p>`:''}${i.sc&&i.sc.length?`<p><b>Tiêu chí chấm ABLLS-R:</b></p><ul>${i.sc.map(c=>`<li>Điểm ${esc(c[0])}: ${esc(c[1])}</li>`).join('')}</ul>`:''}${i.a?`<p><b>Mốc phát triển:</b> ${esc(i.a)}</p>`:''}${i.lg?`<p><b>Ngôn ngữ thường đi cùng ở giai đoạn này:</b> ${esc(i.lg)}</p>`:''}${(i.ex||[]).map(([l,v])=>v?`<p><b>${esc(l)}:</b> ${esc(v)}</p>`:'').join('')}${i.rf?`<p class="mu">Nguồn: ${esc(i.rf)}</p>`:''}${!i.o&&!i.x&&!i.a&&!(i.sc&&i.sc.length)?'<p class="mu">Không có mô tả thêm trong dữ liệu gốc.</p>':''}</div></details>`}
/* danh sách bài tập của một mục (bl): 3 bài đầu hiện sẵn, còn lại bấm xem thêm */
function blList(i){const a=i.bl||[];if(!a.length)return'';const li=x=>`<li>${esc(x)}</li>`;
 return`<div class="sm" style="margin-top:6px"><b>Bài tập (${a.length}):</b></div><ol class="sm bl">${a.slice(0,3).map(li).join('')}</ol>${a.length>3?`<details class="gd"><summary class="sm">Xem thêm ${a.length-3} bài tập</summary><ol class="sm bl" start="4">${a.slice(3).map(li).join('')}</ol></details>`:''}`}
/* Khối "Vấn đề, mục tiêu và bài tập" của ba bộ ADHD, Tích hợp giác quan, Điều hòa cảm giác (bộ khác trả rỗng).
   mode: 's' nhân viên (kèm lưu ý an toàn), 'p' cổng phụ huynh (không ghi chú lâm sàng, không lưu ý an toàn, bỏ chữ "đề xuất"), 'pdf' bản in (mở hết, không gập). o.open: mở sẵn. */
function gxHtml(g,mode,o){const d=gxData(g);if(!d)return'';o=o||{};
 const par=mode!=='s',pdf=mode==='pdf',age=a=>par?String(a).replace(/\s*\(đề xuất\)/,''):a;
 const row=(l,v)=>v?`<p class="gx-r"><b>${l}:</b> ${esc(v)}</p>`:'';
 const li=e=>e.full?`<li>${esc(e.n)}</li>`:`<li><b>${esc(e.n)}</b>${e.a?` <span class="mu">(${esc(age(e.a))})</span>`:''}${e.o?`<br>${esc(e.o)}`:''}${e.tool?`<br><span class="mu">Dụng cụ: ${esc(e.tool)}</span>`:''}${!par&&e.safe?`<br><span class="mu">Lưu ý: ${esc(e.safe)}</span>`:''}</li>`;
 const a=d.ex,list=a.length?`<p class="gx-r"><b>Bài tập (${a.length}):</b></p><ol class="bl">${(pdf?a:a.slice(0,3)).map(li).join('')}</ol>${!pdf&&a.length>3?`<details class="gd"><summary>Xem thêm ${a.length-3} bài tập</summary><ol class="bl" start="4">${a.slice(3).map(li).join('')}</ol></details>`:''}`:'';
 const body=row('Vấn đề',d.prob+(d.head?' ('+d.head+')':''))+row('Mục tiêu',d.goal)+row('Mô tả',d.crit)+row('Tiêu chí đạt',d.cr2)+(d.how?row('Cách làm',d.how)+row('Mục đích',d.why)+row('Dụng cụ',d.tool)+(par?'':row('Lưu ý an toàn',d.safe)):'')+list,t='Vấn đề, mục tiêu và bài tập';
 return pdf?`<div class="gx"><div class="gx-h">${t}</div>${body}</div>`:`<details class="gx"${o.open?' open':''}><summary>${t}</summary>${body}</details>`}
function libItem(i,o){const tk=o.taken&&o.taken.includes(i.id),on=o.sel&&o.sel.includes(i.id),cnt=DB.plans.filter(p=>p.g===i.id&&p.s==='dang').length;
 return`<div class="gi ${tk?'tk':''}">${o.pick?`<input type="checkbox" id="${o.idp?o.idp+'c':'gc'}-${esc(i.id)}" data-c="${o.cn||'gpsel'}" value="${esc(i.id)}" ${on?'checked':''} ${tk?'disabled':''}>`:''}<div class="gi-b"><${o.pick?`label for="${o.idp?o.idp+'c':'gc'}-${esc(i.id)}"`:'div'} class="gi-n">${i.s==='vb'?tg(i.st?'Bước '+i.ms+i.st:'Mốc '+i.ms,i.st?'gy':'y')+' ':''}${esc(i.n)}</${o.pick?'label':'div'}><div class="sm mu">${domTag(i.d,i)} ${esc(i.t)} · ${esc(gSrc(i))}${i.a?' · '+esc(i.a):''}${tk?' · <b>Đã có</b>':''}${(!o.pick||o.edit)&&cnt?' · '+cnt+' bé đang luyện':''}</div>${i.bt&&i.bt.length?`<div class="sm"><b>Bài tập:</b> ${i.bt.map(esc).join(' · ')}</div>`:''}${blList(i)}${i.s==='tg'?`<div class="sm mu">Giáo viên: ${esc(sn(i.by))} · Bé: ${esc((kidBy(i.kid)||{}).n||'(đã xóa)')}</div>`:''}${libDetail(i)}</div>${o.edit&&i.s==='cu'&&isLead()?`<button class="btn s" data-a="cgedit" data-v="${esc(i.id.slice(3))}">Sửa</button>`:''}${o.edit&&i.s==='tg'&&(isLead()||i.by===(U&&U.id))?`<button class="btn s no" data-a="tgdel" data-v="${esc(i.id.slice(3))}">Xóa</button>`:''}</div>`}
function libPanel(f,o){const P=o.idp||'lf',hs=libHeads(f),all=libFind(f),p=pg(LPG(),all,o.per||20),hasF=f.dom||f.src||f.head||f.age||f.q;
 return`<div class="chips" role="group" aria-label="Lĩnh vực"><button type="button" class="chip ${f.dom?'':'on'}" data-a="lfdom" data-v="" aria-pressed="${!f.dom}">Tất cả lĩnh vực</button>${LCHIPS.map(d=>`<button type="button" class="chip ${f.dom===d.id?'on':''}" data-a="lfdom" data-v="${d.id}" aria-pressed="${f.dom===d.id}" title="${esc(d.d)}">${esc(d.s)}</button>`).join('')}</div>
 <div class="f2" style="margin:10px 0"><div><label for="${P}-s">Bộ công cụ</label><select id="${P}-s" data-c="lfsrc"><option value="">Tất cả</option>${opts(Object.keys(LSRC).filter(s=>s==='tg'?tgItems().length:(s!=='cu'||(DB.cg||[]).length)).map(s=>[s,LSRC[s].n]),f.src)}</select></div><div><label for="${P}-h">Tiêu đề</label><select id="${P}-h" data-c="lfhead"><option value="">Tất cả tiêu đề (${hs.length})</option>${opts(hs,f.head)}</select></div><div><label for="${P}-a">Độ tuổi phát triển</label><select id="${P}-a" data-c="lfage"><option value="">Tất cả</option>${opts(AGEB,f.age)}</select></div><div><label for="${P}-q">Tìm mục tiêu</label><input id="${P}-q" data-i="lfq" value="${esc(f.q)}" placeholder="Ví dụ: bắt chước, đếm, gọi tên"></div></div>
 <div class="acts" style="margin-bottom:8px"><span class="sm"><b>${all.length}</b> mục phù hợp</span>${hasF?'<button class="btn s" data-a="lfclr">Xóa bộ lọc</button>':''}${f.age!==''&&f.age!=null?'<span class="sm mu">Đang lọc theo mốc phát triển của mục tiêu, không theo tuổi thật của bé. Bộ ABLLS-R và hoạt động OT không chia theo mốc tuổi nên không hiện khi lọc.</span>':''}</div>${f.src==='vb'?vbPanel(f,P):''}`
 +(p.rows.length?`<div class="gl">${p.rows.map(i=>libItem(i,o)).join('')}</div>`:'<p class="empty">Không có mục tiêu phù hợp. Hãy nới bộ lọc hoặc đổi từ khóa.</p>')+p.html}
/* ---------- Ngân hàng mục tiêu: chọn mục tiêu trực tiếp cho bé (giáo viên và quản lý) ---------- */
const bkInit=()=>S.bk=Object.assign({kid:'',hz:'n',up:'',sel:[]},S.bk);
const bkKids=()=>myKids().filter(k=>k.st==='dang').sort((a,b)=>a.n.localeCompare(b.n,'vi'));
const dots=n=>String(n).replace(/\B(?=(\d{3})+(?!\d))/g,'.');
function hsLib(){const b=bkInit(),ks=bkKids(),nc=(DB.cg||[]).length,ntg=tgItems().length;
 if(!ks.some(k=>k.id===b.kid))b.kid=ks.length===1?ks[0].id:'';
 const kid=b.kid?kidBy(b.kid):null,own=kid?kidPlans(kid.id).filter(p=>p.s!=='dat'):[],taken=own.map(p=>p.g);
 b.sel=b.sel.filter(g=>!taken.includes(g));
 return`<div class="card"><p class="mu sm" style="margin-bottom:12px">${dots(LIBI.length)} mục tiêu chia theo ${LDOM.length} lĩnh vực (ABLLS-R, ESDM/Denver, VB-MAPP, mốc phát triển Mầm non, hoạt động OT, thang chơi Westby, chuỗi phát triển chơi và Ngôn ngữ trị liệu 0–6 tuổi)${nc?' và '+nc+' mục tiêu do Trung tâm tự thêm':''}${ntg?(nc?', ':' và ')+ntg+' mục do giáo viên tự thêm':''}. Cách chọn: chọn bé, chọn lĩnh vực rồi tick các mục tiêu cần luyện, sau đó bấm “Thêm vào kế hoạch”. Khi ghi buổi can thiệp, bạn cũng chọn mục tiêu theo lĩnh vực từ ngân hàng này.</p>
 <div class="bk-w"><label for="bk-k"><b>Chọn mục tiêu cho bé</b></label><select id="bk-k" data-c="bkkid"><option value="">${ks.length?'Chọn bé…':'Chưa có bé nào để chọn'}</option>${opts(ks.map(k=>[k.id,k.n+' · '+age(k.dob)]),b.kid)}</select>${kid?`<span class="sm mu">${esc(kid.nd)} · đang có ${own.length} mục tiêu trong kế hoạch</span>`:'<span class="sm mu">Chọn bé để thêm mục tiêu vào kế hoạch. Chưa chọn bé vẫn xem và tìm mục tiêu được.</span>'}</div>`
 +libPanel(S.hs.lib,{pick:true,cn:'bksel',idp:'bk',edit:true,sel:b.sel,taken,per:20})
 +`<div class="bk-f"><span class="bk-s sm"><b id="bk-cnt">${b.sel.length}</b> mục đã chọn${kid?' cho '+esc(kid.n):''}</span><button class="btn s" id="bk-clr" data-a="bkclr" ${b.sel.length?'':'disabled'}>Bỏ chọn</button><select id="bk-hz" data-c="bkhz" aria-label="Loại mục tiêu" title="Ngắn hạn: 1–3 tháng. Dài hạn: 6–12 tháng." style="width:auto">${opts([['n','Ngắn hạn'],['d','Dài hạn']],b.hz)}</select><select id="bk-up" data-c="bkup" aria-label="Thuộc mục tiêu dài hạn" title="Chỉ áp dụng cho mục tiêu ngắn hạn" style="width:auto;max-width:100%" ${kid&&b.hz==='n'?'':'disabled'}>${opts([['','Chưa gắn mục tiêu dài hạn']].concat(kid?kidPlans(kid.id).filter(p=>p.h==='d'&&p.s!=='dat').map(p=>[p.id,'Thuộc: '+gName(p.g)]):[]),b.up)}</select><button class="btn p" data-a="bkok">Thêm vào kế hoạch</button></div></div>`}
const bkCount=()=>{const b=S.bk,e=$q('#bk-cnt'),x=$q('#bk-clr');if(e)e.textContent=b.sel.length;if(x)x.disabled=!b.sel.length};
CHG.bkkid=v=>{const b=bkInit();b.kid=v;b.up=''};
CHG.bksel=(v,t)=>{const b=bkInit();b.sel=t.checked?b.sel.filter(x=>x!==v).concat(v):b.sel.filter(x=>x!==v);bkCount();return false};
CHG.bkhz=v=>{const b=bkInit();b.hz=v;const u=$q('#bk-up');if(u)u.disabled=!b.kid||v!=='n';return false};CHG.bkup=v=>{bkInit().up=v;return false};
ACT.bkclr=()=>{bkInit().sel=[]};
ACT.bkok=()=>{const b=bkInit(),k=b.kid?kidBy(b.kid):null;
 if(!k||!canKid(k.id)){toast('Hãy chọn bé ở ô “Chọn mục tiêu cho bé” trước');return false}
 if(!b.sel.length){toast('Hãy tick chọn ít nhất một mục tiêu');return false}
 let n=0;b.sel.forEach(g=>{if(addPlanItem(k.id,g,b.hz,b.hz==='n'?b.up:''))n++});b.sel=[];
 toast('Đã thêm '+n+' mục tiêu vào kế hoạch '+HZ[b.hz][0].toLowerCase()+' của '+k.n);
 S.modal={t:'hs',id:k.id,tab:'kh'}};
VIEWS.mt=()=>{hsInit();return head('Ngân hàng mục tiêu','Chọn mục tiêu theo lĩnh vực để đưa vào kế hoạch và buổi can thiệp của bé',(isLead()?'<button class="btn p" data-a="cgnew">Thêm mục tiêu của Trung tâm</button>':'')+(myKids().length?'<button class="btn" data-a="tgnew">Thêm mục tiêu mới cho bé</button>':''))+hsLib()};

/* ---------- Bộ chọn mục tiêu (thêm vào kế hoạch hoặc vào buổi) ---------- */
ACT.pkopen=v=>{S.modal={t:'gp',mode:'plan',k:v,back:S.modal&&S.modal.t==='hs'?S.modal:null,f:{dom:'',src:'',head:'',age:'',q:''},sel:[],hz:'n'};S.pg.gp=1};
const gpCount=()=>{const m=S.modal,e=$q('#gp-cnt'),b=$q('#gp-ok');if(e)e.textContent=m.sel.length;if(b)b.disabled=!m.sel.length};
CHG.gpsel=(v,t)=>{const m=S.modal;m.sel=t.checked?m.sel.filter(x=>x!==v).concat(v):m.sel.filter(x=>x!==v);gpCount();return false};
CHG.gphz=v=>{S.modal.hz=v;const u=$q('#gp-up');if(u)u.disabled=v!=='n';return false};CHG.gpup=v=>{S.modal.up=v;return false};CHG.gppl=v=>{S.modal.pl=v;return false};
ACT.gpback=()=>{S.modal=S.modal.back||null};
ACT.gpok=()=>{const m=S.modal;if(!m.sel.length)return false;
 if(m.mode==='plan'){let n=0;m.sel.forEach(g=>{if(addPlanItem(m.k,g,m.hz,m.hz==='n'?(m.up||''):''))n++});toast('Đã thêm '+n+' mục tiêu vào kế hoạch '+HZ[m.hz][0].toLowerCase());S.modal=m.back?Object.assign({},m.back,{tab:'kh'}):{t:'hs',id:m.k,tab:'kh'}}
 else{const b=m.back;let nn=0;
  m.sel.forEach(g=>{let pl='';
   if(m.pl&&m.pl!=='auto')pl=m.pl;
   else if(m.pl==='auto'){const dm=gDom(g),all=kidPlans(m.k,'dang').filter(p=>p.h==='n'),own=all.find(p=>p.g===g)||all.find(p=>gDom(p.g)===dm);
    if(own)pl=own.id;else{const id=addPlanItem(m.k,g,'n',gtAutoUp(m.k,g));if(id){pl=id;nn++}}}
   seAddTo(b,[g],pl)});
  S.modal=b;toast('Đã thêm '+m.sel.length+' mục tiêu vào buổi'+(nn?' và tạo '+nn+' mục tiêu ngắn hạn mới':''))}};
MODALS.gp=()=>{const m=S.modal,k=kidBy(m.k);if(!k){S.modal=null;return''}
 const taken=m.mode==='plan'?kidPlans(k.id).filter(p=>p.s!=='dat').map(p=>p.g):m.back.it.map(i=>i.g);
 return mdl('Chọn mục tiêu cho '+k.n,`<p class="mu sm" style="margin-bottom:10px">${m.mode==='plan'?'Chọn một hoặc nhiều mục tiêu để đưa vào kế hoạch của bé.':'Chọn mục tiêu để thêm vào buổi can thiệp.'} Bấm “Chi tiết” để xem mô tả, ví dụ và tiêu chí chấm.</p>`+libPanel(m.f,{pick:true,sel:m.sel,taken,per:12})
 +`<div class="gp-f"><span class="sm"><b id="gp-cnt">${m.sel.length}</b> mục đã chọn</span>${m.mode==='plan'?`<span style="display:flex;gap:6px 10px;align-items:center;flex-wrap:wrap"><label for="gp-hz" class="sm" style="margin:0">Loại mục tiêu</label><select id="gp-hz" data-c="gphz" style="width:auto">${opts([['n','Ngắn hạn (1–3 tháng)'],['d','Dài hạn (6–12 tháng)']],m.hz)}</select><label for="gp-up" class="sm" style="margin:0">Thuộc mục tiêu dài hạn</label><select id="gp-up" data-c="gpup" style="width:auto;max-width:100%" ${m.hz==='n'?'':'disabled'}>${opts([['','Chưa gắn']].concat(kidPlans(k.id).filter(p=>p.h==='d'&&p.s!=='dat').map(p=>[p.id,gName(p.g)])),m.up||'')}</select></span>`:`<span style="display:flex;gap:6px 10px;align-items:center;flex-wrap:wrap"><label for="gp-pl" class="sm" style="margin:0">Thuộc mục tiêu ngắn hạn</label><select id="gp-pl" data-c="gppl" style="width:auto;max-width:100%">${opts([['auto','Tự chọn theo lĩnh vực'],['','Chưa gắn mục tiêu ngắn hạn']].concat(kidPlans(k.id).filter(p=>p.h==='n'&&p.s!=='dat').map(p=>[p.id,gName(p.g)])),m.pl)}</select></span>`}<span class="acts"><button class="btn" data-a="gpback">Quay lại</button><button class="btn p" id="gp-ok" data-a="gpok" ${m.sel.length?'':'disabled'}>${m.mode==='plan'?'Thêm vào kế hoạch':'Thêm vào buổi'}</button></span></div>`,1)};

/* ---------- Mục tiêu do Trung tâm tự thêm ---------- */
ACT.cgnew=()=>{S.modal={t:'cg',id:''}};ACT.cgedit=v=>{S.modal={t:'cg',id:v}};
MODALS.cg=()=>{const id=S.modal.id,c=id?DB.cg.find(x=>x.id===id):{d:'nh',t:'',n:'',o:''};if(!c){S.modal=null;return''}
 return mdl(id?'Sửa mục tiêu của Trung tâm':'Thêm mục tiêu của Trung tâm',`<form id="cgf" class="f"><div class="f2"><div><label for="cg-d">Lĩnh vực</label><select id="cg-d" name="d">${opts(LDOM.map(d=>[d.id,d.n]),c.d)}</select></div><div><label for="cg-t">Tiêu đề</label><input id="cg-t" name="t" value="${esc(c.t)}" placeholder="Ví dụ: Nề nếp lớp học"></div></div><div><label for="cg-n">Mục tiêu cụ thể</label><input id="cg-n" name="n" value="${esc(c.n)}" required></div><div><label for="cg-o">Mô tả hoặc tiêu chí đạt</label><textarea id="cg-o" name="o" rows="3">${esc(c.o)}</textarea></div>
 <div class="acts" style="justify-content:flex-end">${id?'<button class="btn no" type="button" data-a="cgdel" data-v="'+esc(id)+'">Xóa</button>':''}<button class="btn" type="button" data-a="mx">Hủy</button><button class="btn p" type="submit">Lưu</button></div></form>`)};
FORM.cgf=f=>{const e=f.elements,v={d:e.d.value,t:e.t.value.trim(),n:e.n.value.trim(),o:e.o.value.trim()};if(!v.n){toast('Hãy nhập mục tiêu cụ thể');return false}
 DB.cg=DB.cg||[];if(S.modal.id)Object.assign(DB.cg.find(x=>x.id===S.modal.id),v);else DB.cg.push(Object.assign({id:'c'+uid()},v));S.modal=null;toast('Đã lưu mục tiêu')};
ACT.cgdel=v=>{const n=DB.plans.filter(p=>p.g==='cu:'+v).length;ask('Xóa mục tiêu này khỏi ngân hàng mục tiêu?'+(n?' Có '+n+' bé đang có mục tiêu này trong kế hoạch, mục tiêu sẽ hiện là “đã xóa”.':''),()=>{DB.cg=DB.cg.filter(x=>x.id!==v);S.modal=null;toast('Đã xóa mục tiêu')},'Xóa')};

/* ---------- Mục tiêu do giáo viên tự thêm (collection tg) ---------- */
ACT.tgnew=()=>{if(!myKids().length){toast('Chưa có bé nào để gắn mục tiêu');return false}S.modal={t:'tg'}};
MODALS.tg=()=>{const ks=myKids(),lv=[['n','Ngắn hạn (1–3 tháng)'],['d','Dài hạn (6–12 tháng)'],['buoi','Mục tiêu buổi trị liệu (chọn khi ghi buổi)']];
 return mdl('Thêm mục tiêu mới cho bé',`<p class="mu sm" style="margin-bottom:10px">Dùng khi bộ gợi ý chưa có mục tiêu phù hợp. Mục tiêu ngắn hạn và dài hạn được đưa vào kế hoạch của bé ngay; mục tiêu buổi trị liệu được chọn khi ghi buổi can thiệp. Giáo viên chỉ thấy mục tiêu do mình thêm; Trưởng Trung tâm và Quản lý thấy được giáo viên và bé.</p>
 <form id="tgf" class="f"><div class="f2"><div><label for="tg-k">Bé</label><select id="tg-k" name="k" required>${opts(ks.map(k=>[k.id,k.n]),'')}</select></div><div><label for="tg-lv">Loại mục tiêu</label><select id="tg-lv" name="lv">${opts(lv,'n')}</select></div></div>
 <div><label for="tg-d">Lĩnh vực</label><select id="tg-d" name="d">${opts(LDOM.map(d=>[d.id,d.n]),'')}</select></div>
 <div><label for="tg-n">Mục tiêu cụ thể</label><input id="tg-n" name="n" required placeholder="Ví dụ: Trẻ gọi tên bạn khi bạn chào"></div>
 <div><label for="tg-o">Mô tả hoặc tiêu chí đạt</label><textarea id="tg-o" name="o" rows="3"></textarea></div>
 <div class="acts" style="justify-content:flex-end"><button class="btn" type="button" data-a="mx">Hủy</button><button class="btn p" type="submit">Lưu mục tiêu</button></div></form>`)};
FORM.tgf=f=>{const e=f.elements,k=e.k.value,lv=e.lv.value,n=e.n.value.trim();
 if(!n){toast('Hãy nhập mục tiêu cụ thể');return false}
 if(!k||!canKid(k)){toast('Chỉ chọn bé mà bạn đang phụ trách');return false}
 DB.tg=DB.tg||[];const id='t'+uid();
 DB.tg.push({id,by:U.id,kid:k,lv,d:e.d.value,n,o:e.o.value.trim(),at:TODAY});
 if(lv!=='buoi')addPlanItem(k,'tg:'+id,lv,'');
 S.modal=null;toast(lv==='buoi'?'Đã lưu mục tiêu buổi trị liệu. Chọn khi ghi buổi can thiệp':'Đã thêm vào kế hoạch '+HZ[lv][0].toLowerCase()+' của bé');};
ACT.tgdel=v=>{const t=(DB.tg||[]).find(x=>x.id===v);if(!t)return;if(!(isLead()||t.by===U.id)){toast('Chỉ người thêm hoặc Trưởng Trung tâm, Quản lý được xóa');return false}
 const n=DB.plans.filter(p=>p.g==='tg:'+v).length;
 ask('Xóa mục tiêu này khỏi ngân hàng?'+(n?' Có '+n+' bé đang có mục tiêu này trong kế hoạch, mục tiêu sẽ hiện là “đã xóa”.':''),()=>{DB.tg=DB.tg.filter(x=>x.id!==v);S.modal=null;toast('Đã xóa mục tiêu')},'Xóa')};
/* ===== 4. Phân công ===== */
const isGrStaff=id=>DB.groups.some(g=>grHas(g,id));
const pool11=()=>DB.staff.filter(s=>isTeacher(s)&&s.st==='dang'&&!isGrStaff(s.id));
const poolBt=()=>DB.staff.filter(s=>isTeacher(s)&&s.st==='dang'&&!DB.lich.some(l=>l.type==='11'&&l.gv===s.id&&l.day<=5));
VIEWS.pc=()=>{const p=S.pc=Object.assign({tab:'gv',q:'',gv:''},S.pc);
 return head('Phân công','Giáo viên phụ trách từng trẻ và các nhóm bán trú')+tabsH([['gv','Giáo viên 1-1'],['bt','Nhóm bán trú'],['kl','Khối lượng công việc']],p.tab,'pctab')+(p.tab==='gv'?pcGV():p.tab==='bt'?pcBt():pcLoad())};
ACT.pctab=v=>{S.pc.tab=v};
INP.pcq=v=>{S.pc.q=v;S.pg.pc=1};
CHG.pcg=v=>{S.pc.gv=v;S.pg.pc=1};
function pcGV(){const p=S.pc,q=p.q.toLowerCase(),ks=DB.kids.filter(k=>k.st==='dang'&&wk11(k.id)>0&&(!p.gv||k.gv===p.gv)&&(!q||k.n.toLowerCase().includes(q))),pp=pg('pc',ks,12),P=pool11();
 return`<div class="card"><div class="f2" style="margin-bottom:12px"><div><label for="pcq">Tìm theo tên bé</label><input id="pcq" data-i="pcq" value="${esc(p.q)}"></div><div><label for="pcg">Lọc theo giáo viên</label><select id="pcg" data-c="pcg"><option value="">Tất cả</option>${opts(P.map(s=>[s.id,tName(s)]),p.gv)}</select></div></div>`
 +tbl(['Trẻ','Buổi 1-1/tuần','Giáo viên hiện tại','Chuyển sang giáo viên khác'],pp.rows.map(k=>`<tr><td><b>${esc(k.n)}</b><br><span class="sm mu">${age(k.dob)} · ${esc(k.nd)}</span></td><td>${wk11(k.id)}</td><td>${esc(sn(k.gv))}</td><td><label class="sm" for="mv-${k.id}" style="position:absolute;left:-9999px">Chuyển ${esc(k.n)}</label><select id="mv-${k.id}" data-c="pcmv" data-k="${k.id}" style="max-width:240px"><option value="">Chọn giáo viên</option>${opts(P.filter(s=>s.id!==k.gv).map(s=>[s.id,tName(s)+' ('+DB.kids.filter(x=>x.gv===s.id&&x.st==='dang').length+' trẻ)']),'')}</select></td></tr>`).join(''),'Không có trẻ phù hợp.')+pp.html
 +`<p class="note sm" style="margin-top:10px">Khi chuyển, hệ thống kiểm tra giáo viên mới có rảnh đúng các khung giờ cố định của bé không. Nếu trùng sẽ báo rõ và không chuyển.</p></div>`}
function reassign(k,gv,dry){const ls=DB.lich.filter(l=>l.type==='11'&&l.hs===k.id);
 for(const l of ls){const c=conflict(Object.assign({},l,{gv}));if(c)return c+' (bé học '+DAYS[l.day]+' '+slotLb(l.slot)+')'}
 if(!dry){ls.forEach(l=>l.gv=gv);k.gv=gv}return''}
CHG.pcmv=(v,t)=>{const k=kidBy(t.dataset.k);if(!v||!k)return;const c=reassign(k,v,1);
 if(c){toast(c);return}
 ask('Chuyển bé '+k.n+' từ '+sn(k.gv)+' sang '+sn(v)+'? Mọi buổi 1-1 cố định của bé sẽ do giáo viên mới phụ trách.',()=>{reassign(k,v);toast('Đã chuyển bé '+k.n+' sang '+sn(v))},'Chuyển')};
function pcBt(){const free=poolBt();
 return`<div class="two">`+DB.groups.map(g=>{const ks=DB.kids.filter(k=>k.gr===g.id&&k.st==='dang'),ts=grTs(g),P=DB.staff.filter(s=>isTeacher(s)&&(ts.includes(s.id)||(s.st==='dang'&&free.includes(s))));
  const row=s=>{const on=ts.includes(s.id),o=grOf(s.id),other=o&&o.id!==g.id?o:null;
   return`<label class="chk pcts-r" style="display:flex;gap:8px;align-items:center;margin:0;padding:6px 0"><input type="checkbox" data-c="pcts" data-k="${g.id}|${s.id}" aria-label="${esc(tName(s))} phụ trách ${esc(g.n)}" ${on?'checked':''} ${other?'disabled':''}> <span>${esc(tName(s))} <span class="mu sm">${esc(s.pos)}${other?' · đang phụ trách '+esc(other.n):''}</span></span></label>`};
  return`<div class="card"><h2>${esc(g.n)} <span class="mu sm">· ${ks.length} trẻ</span></h2>
 <div role="group" aria-label="Giáo viên bán trú của ${esc(g.n)}"><p class="sm" style="margin:0 0 4px"><b>Giáo viên bán trú</b> <span class="mu">· ${ts.length?ts.length+' người, ngang nhau':'chưa chọn ai'}</span></p>${P.map(row).join('')||'<p class="empty">Chưa có giáo viên nào rảnh từ thứ Hai đến thứ Sáu.</p>'}</div>
 <details style="margin-top:10px"><summary class="sm" style="cursor:pointer">Danh sách trẻ và chuyển nhóm</summary>${ks.map(k=>`<div class="rw"><span>${esc(k.n)} <span class="mu sm">${age(k.dob)}</span></span><select data-c="pcmvg" data-k="${k.id}" aria-label="Chuyển nhóm cho ${esc(k.n)}" style="width:auto">${opts(DB.groups.map(x=>[x.id,x.n]),k.gr)}</select></div>`).join('')||'<p class="empty">Nhóm chưa có trẻ.</p>'}</details></div>`}).join('')+`</div><p class="note sm">Mỗi lớp chọn được nhiều giáo viên, tất cả ngang nhau. Mỗi người chỉ phụ trách một lớp. Giáo viên bán trú phải rảnh từ thứ Hai đến thứ Sáu, nên chỉ những giáo viên không có buổi 1-1 cố định các ngày này mới được chọn.</p>`}
CHG.pcts=(v,t)=>{const [id,sid]=t.dataset.k.split('|'),g=grBy(id),s=stBy(sid);if(!g||!s)return;const ts=grTs(g);
 if(t.checked){if(ts.includes(sid))return;const o=grOf(sid);
  if(o&&o.id!==id){toast(s.n+' đã phụ trách '+o.n+', hãy bỏ khỏi lớp đó trước');return}
  if(!isTeacher(s)||s.st!=='dang'){toast('Người này không thể phụ trách lớp bán trú');return}
  if(DB.lich.some(l=>l.type==='11'&&l.gv===sid&&l.day<=5)){toast(s.n+' đang có buổi 1-1 cố định từ thứ Hai đến thứ Sáu nên chưa thể phụ trách lớp bán trú');return}
  grSet(g,ts.concat(sid));toast('Đã thêm '+s.n+' vào '+g.n)}
 else{if(!ts.includes(sid))return;grSet(g,ts.filter(x=>x!==sid));toast('Đã bỏ '+s.n+' khỏi '+g.n)}};
CHG.pcmvg=(v,t)=>{const k=kidBy(t.dataset.k);if(k&&v){k.gr=v;toast('Đã chuyển '+k.n+' sang '+grBy(v).n)}};
function pcLoad(){const rows=DB.staff.filter(s=>isTeacher(s)&&s.st==='dang').map(s=>{const gr=grOf(s.id),n=DB.lich.filter(l=>l.type==='11'&&l.gv===s.id).length,ks=DB.kids.filter(k=>k.gv===s.id&&k.st==='dang').length;return{s,gr,n,ks,u:Math.min(100,Math.round(n*100/LOAD_MAX))}});
 return`<div class="card">`+tbl(['Giáo viên','Vai trò','Trẻ 1-1','Buổi 1-1/tuần','Mức tải so với '+LOAD_MAX+' buổi/tuần'],rows.map(r=>`<tr><td><b>${esc(r.s.n)}</b></td><td>${esc(r.s.pos)}${r.gr?'<br><span class="sm mu">'+esc(r.gr.n)+' · giáo viên bán trú'+'</span>':''}</td><td>${r.ks}</td><td>${r.n}</td><td style="min-width:160px"><div style="display:flex;gap:8px;align-items:center"><div style="flex:1">${bar(r.u,r.u>75?'var(--er)':'')}</div><span class="sm">${r.u}%</span></div></td></tr>`).join(''))+`<p class="sm mu" style="margin-top:8px">Khung giờ 1-1 là ${DAY_OPEN}–${DAY_CLOSE}, ${SLOTS.length} ca mỗi ngày (mỗi ca ${SLOT_MIN} phút), thứ Hai đến thứ Bảy. Mức tải tính theo ${LOAD_MAX} buổi 1-1 mỗi tuần là đủ tải.</p></div>`}
/* ===== 5. Lịch học ===== */
const monOf=d=>{let x=d;while(dow(x)!==1)x=addD(x,-1);return x};
const onLeave=(id,d)=>DB.lr.some(x=>x.st===id&&x.s==='duyet'&&x.f<=d&&d<=x.t);
VIEWS.lh=()=>isPH()?lhParent():lhStaff();
const lhStaff=()=>{const h=S.lh=Object.assign({tab:'wk',mode:'gv',wk:monOf(WD),gv:'',room:ROOMS[0],kid:''},S.lh);
 const bv=btView();if(!bv&&h.tab==='bt')h.tab='wk';
 if(isGV()){h.mode='gv';h.gv=U.id}else if(!h.gv)h.gv=(pool11().find(s=>U&&s.id===U.id)||pool11()[0]||{}).id||'';
 if(!h.kid)h.kid=(myKids().find(k=>k.st==='dang'&&wk11(k.id))||{}).id||'';
 return head(isGV()?'Lịch dạy của tôi':'Lịch học','Lịch 1-1 cố định theo tuần ('+DAY_OPEN+'–'+DAY_CLOSE+', mỗi ca '+SLOT_MIN+' phút), lịch học bù'+(bv?' và thời khóa biểu bán trú':''))+tabsH([['wk','Lịch 1-1 theo tuần']].concat(bv?[['bt','Thời khóa biểu bán trú']]:[],[['hol','Ngày nghỉ lễ']]),h.tab,'lhtab')+(h.tab==='wk'?lhWeek(h):h.tab==='hol'?holTab():lhBt())};
ACT.lhtab=v=>{S.lh.tab=v};
ACT.lhwk=v=>{S.lh.wk=v==='0'?monOf(WD):addD(S.lh.wk,+v)};
CHG.lhmode=v=>{S.lh.mode=v};CHG.lhgv=v=>{S.lh.gv=v};CHG.lhroom=v=>{S.lh.room=v};CHG.lhkid=v=>{S.lh.kid=v};
/* các dòng giờ của lưới tuần: chỉ những khung giờ đang có giáo viên dạy 1-1 cho trẻ (theo bộ lọc đang xem), không vẽ sẵn các mốc giờ của hệ thống cho khỏi rối mắt; muốn thêm ca ở giờ khác thì dùng nút "+ Thêm buổi 1-1" */
function slotRows(days,pred){const ds=new Set(days),ex=DB.lich.filter(l=>l.slot&&(l.type==='11'||ds.has(l.date))&&(!pred||pred(l))).map(l=>l.slot);return[...new Set(ex)].sort()}
function lhWeek(h){const mon=h.wk,days=[0,1,2,3,4,5].map(i=>addD(mon,i));
 const ctl=isGV()?'':`<div class="f2" style="margin-bottom:12px"><div><label for="lhm">Xem theo</label><select id="lhm" data-c="lhmode">${opts([['gv','Giáo viên'],['room','Phòng'],['kid','Từng bé'],['all','Tổng hợp số buổi']],h.mode)}</select></div>
 ${h.mode==='gv'?`<div><label for="lhg">Giáo viên</label><select id="lhg" data-c="lhgv">${opts(pool11().map(s=>[s.id,tName(s)]),h.gv)}</select></div>`:h.mode==='room'?`<div><label for="lhr">Phòng</label><select id="lhr" data-c="lhroom">${opts(ROOMS.map(r=>[r,r]),h.room)}</select></div>`:h.mode==='kid'?`<div><label for="lhk">Bé</label><select id="lhk" data-c="lhkid">${opts(DB.kids.filter(k=>k.st==='dang'&&wk11(k.id)).map(k=>[k.id,k.n]),h.kid)}</select></div>`:''}</div>`;
 const gr=h.mode==='gv'&&grOf(h.gv);
 const mineL=l=>h.mode==='gv'?l.gv===h.gv:h.mode==='room'?l.room===h.room:h.mode==='kid'?l.hs===h.kid:true;
 const canAdd=isLead()&&h.mode==='gv'&&!!h.gv&&!isGrStaff(h.gv),sr=slotRows(days,mineL),
  rows=sr.length?sr.map(s=>`<tr><th class="nw">${slotLb(s)}</th>${days.map((d,i)=>lhCell(h,d,i+1,s)).join('')}</tr>`).join(''):`<tr><td colspan="7" class="empty">${h.mode==='gv'?(gr?'Giáo viên này phụ trách lớp bán trú nên không có ca 1-1.':isGV()?'Bạn chưa có buổi 1-1 cố định nào.':'Giáo viên này chưa có buổi 1-1 nào.'):h.mode==='room'?'Phòng này chưa có buổi 1-1 nào.':h.mode==='kid'?'Bé này chưa có buổi 1-1 nào.':'Chưa có buổi 1-1 nào.'}${canAdd?' Bấm “+ Thêm buổi 1-1” để thêm.':''}</td></tr>`;
 return`<div class="card">${ctl}<div class="acts" style="justify-content:space-between;margin-bottom:10px"><div class="acts"><button class="btn s" data-a="lhwk" data-v="-7">Tuần trước</button><button class="btn s" data-a="lhwk" data-v="0">Tuần này</button><button class="btn s" data-a="lhwk" data-v="7">Tuần sau</button></div><span class="acts">${canAdd?'<button class="btn s p" type="button" data-a="lsadd" data-v="1|">+ Thêm buổi 1-1</button>':''}<b>${vd(days[0])} đến ${vd(days[5])}</b></span></div>
 ${gr?`<p class="note sm" style="margin-bottom:10px">${esc(sn(h.gv))} phụ trách ${esc(gr.n)} từ thứ Hai đến thứ Sáu nên không có ca 1-1 các ngày này.</p>`:''}
 <div class="tw"><table class="wkt"><thead><tr><th></th>${days.map(d=>`<th>${DAYN[dow(d)]}<br><span class="mu">${vdm(d)}</span>${isClosed(d)?'<br>'+tg('Nghỉ','in'):''}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table></div>
 <p class="sm mu" style="margin-top:8px">Chỉ hiện các khung giờ đang có giáo viên dạy 1-1. Ô vàng là buổi học bù, ô đỏ nhạt là buổi nghỉ. ${canAdd?'Bấm “+ Thêm buổi 1-1” để thêm ca ở giờ mới, hoặc rê chuột vào ô trống rồi bấm dấu cộng để thêm cùng giờ vào ngày khác.':''}</p></div>`}
function lhCell(h,d,w,s){if(isClosed(d))return`<td class="cell off"><span class="sm mu">${esc(holOf(d).n)}</span></td>`;const ls=lichAt(w,s,d);
 if(h.mode==='all')return`<td class="cell"><span class="tag ${ls.length>=ROOMS.length?'er':ls.length?'in':'gy'}">${ls.length}/${ROOMS.length}</span></td>`;
 const mine=ls.filter(l=>h.mode==='gv'?l.gv===h.gv:h.mode==='room'?l.room===h.room:l.hs===h.kid),off=h.mode==='gv'&&onLeave(h.gv,d);
 const it=l=>{const k=kidBy(l.hs),c=DB.att[d+'|'+l.id+'|'+l.hs],sub=h.mode==='gv'?l.room:h.mode==='room'?given(sn(l.gv)):given(sn(l.gv))+' · '+l.room;
  return`<button class="ls ${l.type==='bu'?'bu':''} ${c&&c!=='cm'?'x':''}" data-a="lsopen" data-v="${l.id}|${d}">${esc(h.mode==='kid'?'Buổi 1-1':given(k?k.n:'?'))}<small>${esc(sub)}${l.type==='bu'?' · bù':''}${c&&c!=='cm'?' · '+AC[c]:''}</small></button>`};
 const add=isLead()&&h.mode==='gv'&&!off&&!mine.length&&!isGrStaff(h.gv)&&w>=1?`<button class="ls add" data-a="lsadd" data-v="${w}|${s}" aria-label="Thêm buổi">+</button>`:'';
 return`<td class="cell ${off?'off':''}">${off?'<span class="sm mu">Nghỉ phép</span>':mine.map(it).join('')+add}</td>`}
/* --- thêm, sửa, xóa buổi cố định --- */
ACT.lsadd=v=>{const [day,slot]=v.split('|');S.modal={t:'ls',id:'',day:+day,slot,err:''}};
ACT.lsopen=v=>{const [id,d]=v.split('|'),l=DB.lich.find(x=>x.id===id);if(!l)return;S.modal={t:'ls',id,day:l.day,slot:l.slot,date:d,err:''}};
MODALS.ls=()=>{const m=S.modal,l=m.id?DB.lich.find(x=>x.id===m.id):null;
 if(l&&l.type==='bu'){const k=kidBy(l.hs);return mdl('Buổi học bù',`<p><b>${esc(k?k.n:'')}</b> học bù ngày ${vd(l.date)}, ${slotLb(l.slot)}, ${esc(l.room)}, giáo viên ${esc(sn(l.gv))}.</p><div class="acts" style="margin-top:12px"><button class="btn" data-a="nav" data-v="hb">Mở mục Học bù</button></div>`)}
 const gv=l?l.gv:S.lh.gv,editable=isLead(),kid=l?kidBy(l.hs):null;
 if(l&&!editable){return mdl('Buổi 1-1',`<p><b>${esc(kid?kid.n:'')}</b><br>${DAYN[l.day]}, ${slotLb(l.slot)}, ${esc(l.room)}</p>`)}
 const ks=DB.kids.filter(k=>k.st==='dang'&&(k.gv===gv||!k.gv));
 return mdl(l?'Sửa buổi 1-1 cố định':'Thêm buổi 1-1 cố định',`<form id="lsf" class="f"><p class="mu sm">Giáo viên: <b>${esc(sn(gv))}</b></p><div class="f2"><div><label for="ls-k">Bé</label><select id="ls-k" name="hs" ${l?'disabled':''}>${opts(ks.map(k=>[k.id,k.n+(k.gv?'':' (chưa phân công)')]),l?l.hs:'')}</select></div><div><label for="ls-d">Thứ</label><select id="ls-d" name="day">${opts([1,2,3,4,5,6].map(i=>[i,DAYN[i]]),m.day)}</select></div><div><label for="ls-s">Giờ bắt đầu</label>${slotInput('ls-s',m.slot)}<small class="mu">Ca ${SLOT_MIN} phút, tự tính giờ kết thúc. Chọn giờ gợi ý hoặc nhập giờ khác.</small></div><div><label for="ls-r">Phòng</label><select id="ls-r" name="room"><option value="">Tự chọn phòng trống</option>${opts(ROOMS.map(r=>[r,r]),l?l.room:'')}</select></div></div><div class="err" role="alert">${esc(m.err)}</div>
 <div class="acts" style="justify-content:space-between"><span>${l?`<button class="btn no" type="button" data-a="lsdel" data-v="${l.id}">Xóa buổi này</button>`:''}</span><span class="acts"><button class="btn" type="button" data-a="mx">Hủy</button><button class="btn p" type="submit">Lưu</button></span></div></form>`)};
FORM.lsf=f=>{const m=S.modal,e=f.elements,old=m.id?DB.lich.find(x=>x.id===m.id):null,gv=old?old.gv:S.lh.gv,hs=old?old.hs:e.hs.value;
 if(!hs){m.err='Hãy chọn bé';return}
 const slot=String(e.slot.value||'').slice(0,5);m.day=+e.day.value;m.slot=slot;
 if(!slotValid(slot)){m.err=slotMsg+'.';return}
 const day=+e.day.value,room=e.room.value||ROOMS.find(r=>!conflict({id:old?old.id:'',day,slot,gv,hs,room:r}))||'',x={id:old?old.id:'l'+uid(),type:'11',day,slot,gv,hs,room},
  c=room?conflict(x):(conflict(Object.assign({},x,{room:''}))||'Không còn phòng trống');   /* hết phòng vì giáo viên hoặc bé đã bận thì báo đúng lý do */
 if(c){m.err=c+' (ca '+slotLb(slot)+'). Hãy chọn thứ, giờ hoặc phòng khác.';return}
 if(old)Object.assign(old,x);else DB.lich.push(x);
 const k=kidBy(hs);if(!k.gv)k.gv=gv;k.m11=wk11(hs);S.modal=null;toast('Đã lưu buổi học')};
ACT.lsdel=v=>{const l=DB.lich.find(x=>x.id===v),k=l&&kidBy(l.hs);if(!l)return;ask('Xóa buổi 1-1 cố định '+DAYN[l.day]+' '+slotLb(l.slot)+' của bé '+(k?k.n:'')+'? Các lần điểm danh trước đây vẫn được giữ.',()=>{DB.lich=DB.lich.filter(x=>x.id!==v);if(k)k.m11=wk11(k.id);toast('Đã xóa buổi học')},'Xóa buổi')};
/* --- bán trú: thời khóa biểu lớp (kiểu mầm non) ghép giờ can thiệp 1-1 của từng bé --- */
CHG.lhbtg=v=>{S.lh.btg=v};CHG.lhbtk=v=>{S.lh.btk=v};ACT.lhbtm=v=>{S.lh.btm=v};
const ovl1=(l,r)=>tmin(l.slot)<tmin(r.e)&&tmin(slotEnd(l.slot))>tmin(r.s);
const rowAt=(rows,l)=>rows.find(r=>tmin(r.s)<=tmin(l.slot)&&tmin(l.slot)<tmin(r.e));
const kindTag=r=>TKB_K[r.k]?tg(TKB_K[r.k][0],TKB_K[r.k][1]):'';
const tkRowHead=r=>`<th class="nw">${r.s}–${r.e}</th><td class="tkn"><b>${esc(r.n)}</b> ${kindTag(r)}${r.x?`<small>${esc(r.x)}</small>`:''}</td>`;
/* bảng của một lớp: mỗi ô có tên bé đang học 1-1 vào giờ đó */
function tkbClass(g,ks){const rows=tkbRows(g.id),byId={};ks.forEach(k=>{byId[k.id]=k});
 const ss=DB.lich.filter(l=>l.type==='11'&&byId[l.hs]&&btHas(byId[l.hs],l.day)).sort((a,b)=>a.slot<b.slot?-1:a.slot>b.slot?1:0);
 const chip=l=>`<span class="kc" title="${esc(sn(l.gv)+' · '+l.room+' · '+slotLb(l.slot))}">${esc(given(byId[l.hs].n))} <small>${l.slot}</small></span>`;
 const head=`<tr><th>Giờ</th><th>Hoạt động</th>${DAY_ALL.map(w=>`<th>${DAYN[w]}<br><small class="mu">${ks.filter(k=>btHas(k,w)).length} bé</small></th>`).join('')}</tr>`;
 const body=rows.map(r=>`<tr>${tkRowHead(r)}${DAY_ALL.map(w=>{const t=(r.d&&r.d[w])||'',c=ss.filter(l=>l.day===w&&rowAt(rows,l)===r);return`<td class="cell ${grOpen(g,w)?'':'off'}">${t?`<div class="tkc">${esc(t)}</div>`:''}${c.length?`<div class="tko"><small class="mu">Học 1-1:</small> ${c.map(chip).join('')}</div>`:''}</td>`}).join('')}</tr>`).join('');
 const out=ss.filter(l=>!rowAt(rows,l)),sl=[...new Set(out.map(l=>l.slot))].sort();
 const ex=sl.map(sv=>`<tr><th class="nw">${slotLb(sv)}</th><td class="tkn"><b>Ngoài khung thời khóa biểu</b></td>${DAY_ALL.map(w=>{const c=out.filter(l=>l.slot===sv&&l.day===w);return`<td class="cell">${c.length?c.map(chip).join(''):''}</td>`}).join('')}</tr>`).join('');
 return rows.length?`<div class="tw"><table class="wkt tkt"><thead>${head}</thead><tbody>${body}${ex}</tbody></table></div>`:'<p class="empty">Lớp chưa có thời khóa biểu.'+(isLead()?' Bấm “Sửa thời khóa biểu” để thêm các dòng hoạt động.':'')+'</p>'}
/* bảng tuần của một bé: thời khóa biểu lớp ghép với các ca 1-1 của riêng bé */
function kidWeek(k){const bd=btOf(k),g=bd.length?grBy(k.gr):null,ls=DB.lich.filter(l=>l.type==='11'&&l.hs===k.id).sort((a,b)=>a.slot<b.slot?-1:a.slot>b.slot?1:0);
 if(!ls.length&&!g)return'<p class="empty">Bé chưa có lịch học cố định.</p>';
 const chip=l=>`<div class="ls st"><b>1-1 · ${slotLb(l.slot)}</b><small>${esc(given(sn(l.gv)))} · ${esc(l.room)}</small></div>`;
 const rows=g?tkbRows(g.id):[];
 if(!rows.length){   /* chưa có thời khóa biểu lớp: bảng theo ca như trước */
  const slots=[...new Set(ls.map(l=>l.slot))].sort(),bt=g?`<tr><th class="nw">${BTLB}</th><td class="tkn"><b>Bán trú ${esc(g.n)}</b></td>${DAY_ALL.map(w=>`<td class="cell">${bd.includes(w)?'<div class="ls st bt"><b>Bán trú</b><small>'+esc(g.n)+'</small></div>':''}</td>`).join('')}</tr>`:'';
  return`<div class="tw"><table class="wkt tkt"><thead><tr><th>Giờ</th><th>Hoạt động</th>${DAY_ALL.map(w=>`<th>${DAYN[w]}</th>`).join('')}</tr></thead><tbody>${bt}${slots.map(sv=>`<tr><th class="nw">${slotLb(sv)}</th><td class="tkn"><b>Can thiệp 1-1</b></td>${DAY_ALL.map(w=>`<td class="cell">${ls.filter(l=>l.day===w&&l.slot===sv).map(chip).join('')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
 const body=rows.map(r=>`<tr>${tkRowHead(r)}${DAY_ALL.map(w=>{const on=bd.includes(w),mine=ls.filter(l=>l.day===w&&ovl1(l,r)),t=on?((r.d&&r.d[w])||''):'';
  return`<td class="cell ${on?'':'off'}">${t?`<div class="tkc ${mine.length?'dim':''}">${esc(t)}</div>`:''}${mine.map(l=>rowAt(rows,l)===r?chip(l):'<div class="sm mu">Đang học 1-1</div>').join('')}</td>`}).join('')}</tr>`).join('');
 const out=ls.filter(l=>!rowAt(rows,l)),sl=[...new Set(out.map(l=>l.slot))].sort();
 const ex=sl.map(sv=>`<tr><th class="nw">${slotLb(sv)}</th><td class="tkn"><b>Ngoài khung thời khóa biểu</b></td>${DAY_ALL.map(w=>`<td class="cell">${out.filter(l=>l.slot===sv&&l.day===w).map(chip).join('')}</td>`).join('')}</tr>`).join('');
 return`<div class="tw"><table class="wkt tkt"><thead><tr><th>Giờ</th><th>Hoạt động</th>${DAY_ALL.map(w=>`<th>${DAYN[w]}<br><small class="mu">${bd.includes(w)?'Bán trú':'Không bán trú'}</small></th>`).join('')}</tr></thead><tbody>${body}${ex}</tbody></table></div><p class="sm mu" style="margin-top:8px">Ô xanh là ca can thiệp 1-1 của bé (${SLOT_MIN} phút); hoạt động của lớp trong khung giờ đó bé không tham gia.</p>`}
function lhBt(){const gs=isGV()?myGroups():DB.groups;
 if(!gs.length)return'<div class="card"><p class="empty">Bạn không phụ trách lớp bán trú nào.</p></div>';
 const h=S.lh;if(!gs.some(g=>g.id===h.btg))h.btg=gs[0].id;if(!h.btm)h.btm='lop';
 const g=grBy(h.btg),ks=DB.kids.filter(k=>k.gr===g.id&&k.st==='dang'&&k.bt);
 if(!ks.some(k=>k.id===h.btk))h.btk=(ks[0]||{}).id||'';
 const miss=ks.filter(k=>btOf(k).some(w=>!DB.lich.some(l=>l.type==='11'&&l.hs===k.id&&l.day===w)));
 const ctl=`<div class="card"><div class="top" style="align-items:flex-end"><div class="f2" style="flex:1">${gs.length>1?`<div><label for="lhbg">Lớp</label><select id="lhbg" data-c="lhbtg">${opts(gs.map(x=>[x.id,x.n]),h.btg)}</select></div>`:''}${h.btm==='be'?`<div><label for="lhbk">Bé</label><select id="lhbk" data-c="lhbtk">${opts(ks.map(k=>[k.id,k.n]),h.btk)}</select></div>`:''}</div>${isLead()&&h.btm==='lop'?`<button class="btn p" data-a="tkbedit">Sửa thời khóa biểu</button>`:''}</div>
  <div style="margin-top:10px">${tabsH([['lop','Thời khóa biểu lớp'],['be','Từng bé']],h.btm,'lhbtm')}</div></div>`;
 const sum=`<div class="card"><h2>${esc(g.n)} <span class="mu sm">· ${ks.length} trẻ</span></h2><p class="sm">Giáo viên bán trú <b>${esc(grNames(g))}</b> · ${BTLB}<br>Số bé theo ngày: ${DAY_ALL.map(w=>DAYS[w]+' '+ks.filter(k=>btHas(k,w)).length).join(' · ')}</p>${miss.length?`<p class="note sm" style="margin-top:8px"><b>Bé chưa đủ ca 1-1 cho các ngày bán trú:</b> ${esc(miss.map(k=>given(k.n)).join(', '))}. Mở hồ sơ bé, thẻ Lịch học, để xếp ca.</p>`:''}</div>`;
 if(h.btm==='be'){const k=kidBy(h.btk);return ctl+(k?`<div class="card"><h2>Thời khóa biểu của ${esc(k.n)}</h2><p class="sm mu" style="margin-bottom:8px">${esc(progOf(k))}${isLead()?' · <button class="lk" data-a="hsopenlh" data-v="'+k.id+'">Sửa lịch học của bé</button>':''}</p>${kidWeek(k)}</div>`:'<div class="card"><p class="empty">Lớp chưa có bé nào.</p></div>')}
 return ctl+sum+`<div class="card"><h2>Thời khóa biểu lớp ${esc(g.n)}</h2>${tkbClass(g,ks)}<p class="sm mu" style="margin-top:8px">Các hoạt động chung của lớp theo khung giờ. Tên bé hiện ở ô giờ bé ra học can thiệp 1-1 (giờ ghi cạnh tên); mỗi ngày bán trú mỗi bé có một ca 1-1 ${SLOT_MIN} phút. Bé được chọn ngày bán trú riêng: thứ Hai đến thứ Sáu hoặc thứ Hai đến thứ Bảy.</p></div>`}
ACT.hsopenlh=v=>{S.modal={t:'hs',id:v,tab:'lh'}};
/* --- sửa thời khóa biểu của lớp --- */
ACT.tkbedit=()=>{const g=S.lh.btg;S.modal={t:'tkb',gr:g,rows:(DB.tkb||[]).filter(r=>r.gr===g).sort((a,b)=>tmin(a.s)-tmin(b.s)).map(r=>JSON.parse(JSON.stringify(r)))}};
function tkbRead(f){const m=S.modal,e=f.elements;return m.rows.map((r,i)=>{const d={};DAY_ALL.forEach(w=>{const v=(e['d'+i+'_'+w].value||'').trim();if(v)d[w]=v});
 const x={id:r.id,gr:m.gr,s:e['s'+i].value,e:e['e'+i].value,n:e['n'+i].value.trim(),k:e['k'+i].value,x:e['x'+i].value.trim()};if(Object.keys(d).length)x.d=d;return x})}
const tkbSync=()=>{const f=$q('#tkbf');if(f&&S.modal&&S.modal.t==='tkb')S.modal.rows=tkbRead(f)};
ACT.tkbadd=()=>{tkbSync();const m=S.modal,last=m.rows.slice().sort((a,b)=>tmin(a.e)-tmin(b.e)).pop(),s0=last?last.e:'08:00',e0=pad(Math.min(23,Math.floor((tmin(s0)+45)/60)))+':'+pad((tmin(s0)+45)%60);
 m.rows.push({id:'tk'+m.gr+'-'+uid(),gr:m.gr,s:s0,e:e0,n:'',k:'hoc',x:''})};
ACT.tkbdel=v=>{tkbSync();S.modal.rows.splice(+v,1)};
ACT.tkbreset=()=>{const m=S.modal;ask('Thay các dòng đang sửa bằng thời khóa biểu mẫu của lớp này? Các thay đổi chưa lưu sẽ mất.',()=>{S.modal=Object.assign({},m,{rows:tkbDefault([grBy(m.gr)]).map(r=>r)})},'Dùng mẫu')};
MODALS.tkb=()=>{const m=S.modal,g=grBy(m.gr);if(!g||!isLead()){S.modal=null;return''}
 const KO=Object.entries(TKB_K).map(([k,v])=>[k,v[0]]);
 const row=(r,i)=>`<div class="card tkrow"><div class="f2"><div><label for="tk-s${i}">Từ giờ</label><input id="tk-s${i}" name="s${i}" type="time" value="${esc(r.s)}" required></div><div><label for="tk-e${i}">Đến giờ</label><input id="tk-e${i}" name="e${i}" type="time" value="${esc(r.e)}" required></div><div><label for="tk-k${i}">Loại</label><select id="tk-k${i}" name="k${i}">${opts(KO,r.k)}</select></div></div>
  <div class="f2" style="margin-top:6px"><div><label for="tk-n${i}">Tên hoạt động</label><input id="tk-n${i}" name="n${i}" value="${esc(r.n)}" required></div><div><label for="tk-x${i}">Mô tả chung cho mọi ngày</label><input id="tk-x${i}" name="x${i}" value="${esc(r.x||'')}"></div></div>
  <details style="margin-top:6px"><summary class="sm" style="cursor:pointer">Nội dung riêng từng thứ${r.d&&Object.keys(r.d).length?' (đã có)':''}</summary><div class="f2" style="margin-top:6px">${DAY_ALL.map(w=>`<div><label for="tk-d${i}-${w}">${DAYN[w]}</label><input id="tk-d${i}-${w}" name="d${i}_${w}" value="${esc((r.d||{})[w]||'')}"></div>`).join('')}</div></details>
  <div class="acts" style="justify-content:flex-end;margin-top:6px"><button class="btn s no" type="button" data-a="tkbdel" data-v="${i}">Xóa dòng</button></div></div>`;
 return mdl('Thời khóa biểu lớp '+g.n,`<form id="tkbf" class="f"><p class="sm mu">Mỗi dòng là một khung giờ hoạt động của lớp. Giờ can thiệp 1-1 của từng bé được ghép tự động lên thời khóa biểu theo lịch cá nhân của bé, nên không cần ghi ở đây.</p>${m.rows.map(row).join('')||'<p class="empty">Chưa có dòng nào.</p>'}
  <div class="acts" style="justify-content:space-between"><span class="acts"><button class="btn" type="button" data-a="tkbadd">Thêm dòng</button><button class="btn" type="button" data-a="tkbreset">Dùng thời khóa biểu mẫu</button></span><span class="acts"><button class="btn" type="button" data-a="mx">Hủy</button><button class="btn p" type="submit">Lưu thời khóa biểu</button></span></div></form>`,1)};
FORM.tkbf=f=>{if(!isLead())return false;const m=S.modal,rows=tkbRead(f);
 for(const r of rows){if(!r.n){toast('Mỗi dòng cần có tên hoạt động');return false}if(!r.s||!r.e||tmin(r.s)>=tmin(r.e)){toast('Giờ của “'+r.n+'” chưa hợp lệ: giờ bắt đầu phải trước giờ kết thúc');return false}}
 const so=rows.slice().sort((a,b)=>tmin(a.s)-tmin(b.s));
 for(let i=1;i<so.length;i++)if(tmin(so[i].s)<tmin(so[i-1].e)){toast('“'+so[i].n+'” chồng giờ với “'+so[i-1].n+'”');return false}
 DB.tkb=(DB.tkb||[]).filter(r=>r.gr!==m.gr).concat(so);S.modal=null;toast('Đã lưu thời khóa biểu')};

/* --- góc nhìn phụ huynh: lịch học, giờ 1-1 và giờ bán trú của bé --- */
ACT.lhk=v=>{S.lh.kid=v};
function lhParent(){const ks=myKids().filter(k=>k.st==='dang');
 if(!ks.length)return head('Lịch học của bé','')+'<div class="card"><p class="empty">Tài khoản này chưa gắn với bé nào đang học. Hãy liên hệ Trung tâm.</p></div>';
 const h=S.lh=Object.assign({kid:ks[0].id},S.lh);if(!ks.some(k=>k.id===h.kid))h.kid=ks[0].id;
 const k=kidBy(h.kid),g=btOf(k).length?grBy(k.gr):null,ls=DB.lich.filter(l=>l.type==='11'&&l.hs===k.id);
 const days=[];for(let i=0;i<14;i++){const d=addD(TODAY,i);if(!isW(d))continue;const xs=sched(k,d.slice(0,7)).filter(x=>x.d===d).sort((a,b)=>a.slot<b.slot?-1:1);if(xs.length)days.push({d,xs})}
 const line=(d,x)=>{const l=x.kind==='bt'?null:DB.lich.find(y=>y.id===x.sid),c=DB.att[d+'|'+x.sid+'|'+k.id];
  const what=x.kind==='bt'?'Bán trú '+esc(g?g.n:'')+' · '+BTLB:(x.kind==='bu'?'Học bù ':'Can thiệp 1-1 ')+slotLb(x.slot)+(l?' · '+esc(given(sn(l.gv)))+' · '+esc(l.room):'');
  return`<div class="rw"><span>${what}</span>${c?tg(AC[c],c==='cm'?'ok':c==='kp'?'er':c==='p'?'wa':'in'):''}</div>`};
 return head('Lịch học của bé','Giờ học 1-1 và giờ bán trú của bé trong tuần')+(ks.length>1?tabsH(ks.map(x=>[x.id,given(x.n)]),h.kid,'lhk'):'')
 +`<div class="grid"><div class="card kpi"><div class="mu sm">Học 1-1</div><div class="big">${ls.length} buổi</div><div class="sm mu">mỗi tuần${ls.length?', '+esc(given(mainGV(k))):''}</div></div><div class="card kpi"><div class="mu sm">Bán trú</div><div class="big">${g?esc(g.n):'Không'}</div><div class="sm mu">${g?BTLB+', '+esc(dayTx(btOf(k))):'Bé chưa đăng ký bán trú'}</div></div></div>`
 +`<div class="card"><h2>Thời khóa biểu của ${esc(given(k.n))}</h2>${kidWeek(k)}<p class="sm mu" style="margin-top:8px">Khi cần nghỉ hoặc đổi giờ, phụ huynh báo trong nhóm chung hoặc đăng ký học bù ở mục Học bù.</p></div>`
 +`${holCard(60)}<div class="card"><h2>Lịch 14 ngày tới</h2>${days.length?days.map(({d,xs})=>`<div class="mday" style="margin-bottom:8px"><div class="mh"><b>${DAYN[dow(d)]}</b> <span class="mu sm">${vdm(d)}</span>${d===TODAY?' '+tg('Hôm nay','y'):''}</div>${xs.map(x=>line(d,x)).join('')}</div>`).join(''):'<p class="empty">Chưa có lịch trong 14 ngày tới.</p>'}<div class="acts" style="margin-top:10px">${g?'<button class="btn s" data-a="nav" data-v="tn">Thực đơn bán trú</button>':''}<button class="btn s" data-a="nav" data-v="hb">Đăng ký học bù</button></div></div>`}
/* ===== 6. Chấm công nhân viên ===== */
const hm=()=>{const d=new Date();return pad(d.getHours())+':'+pad(d.getMinutes())};
const CSYM={ok:['x','Đủ công'],late:['M','Đi muộn'],leave:['P','Nghỉ phép'],kl:['K','Nghỉ không lương'],abs:['A','Vắng không phép'],chua:['·','Chưa chấm'],hol:['L','Nghỉ lễ']};
const LRT={phep:'Nghỉ phép',om:'Nghỉ ốm',kl:'Nghỉ không lương'};
const LRS={cho:['Chờ duyệt','wa'],duyet:['Đã duyệt','ok'],tuchoi:['Từ chối','er']};
/* Chấm công do Quản lý hoặc Trưởng Trung tâm thực hiện cho nhân sự làm giờ cố định (lương cố định tháng); giáo viên không tự chấm công. Nhân sự chỉ trả lương theo ca 1-1 (s.cc===false) không cần chấm công, xem needCC ở p04-domain.js. */
const ccIn=()=>DB.cfg.ccIn||'07:15',ccOut=()=>DB.cfg.ccOut||'18:00';
const selfCC=()=>!!U&&!isGV()&&!isPH()&&needCC(stBy(U.id));   /* Trưởng Trung tâm, Quản lý, Văn phòng vẫn tự chấm công của mình */
const ccStaff=()=>DB.staff.filter(s=>s.st==='dang'&&needCC(s));
const ccDay=()=>{const d=S.cc&&S.cc.d;return d&&d<=TODAY?d:WD};
const lrDays=l=>{let n=0;for(let d=l.f;d<=l.t;d=addD(d,1))if(isW(d))n++;return n};
VIEWS.cc=()=>{const c=S.cc=Object.assign({tab:'hn',m:CM},S.cc),pend=DB.lr.filter(l=>l.s==='cho').length;
 const tabs=seesAll()?[['hn','Hôm nay'],['bang','Bảng công tháng'],['don','Đơn nghỉ phép'+(pend?' ('+pend+')':'')]]:[['hn','Chấm công của tôi'],['don','Đơn nghỉ phép của tôi']];
 if(!tabs.some(t=>t[0]===c.tab))c.tab='hn';
 return head(isGV()?'Chấm công của tôi':'Chấm công',isGV()?'Quản lý chấm công cho giáo viên làm giờ cố định; giáo viên trả theo ca không cần chấm công':'Quản lý chấm công cho nhân sự làm giờ cố định; nhân sự trả theo ca 1-1 không cần chấm công',c.tab==='don'?'<button class="btn p" data-a="lrnew">Tạo đơn nghỉ</button>':'')+tabsH(tabs,c.tab,'cctab')+(c.tab==='hn'?ccToday():c.tab==='bang'?ccGrid():ccLeave())};
ACT.cctab=v=>{S.cc.tab=v};
ACT.ccm=v=>{S.cc.m=sm(S.cc.m,+v)};
ACT.ci=()=>{if(!selfCC())return false;const k=U.id+'|'+WD,r=DB.ts[k]||(DB.ts[k]={i:'',o:''});if(!r.i){r.i=hm();toast('Đã chấm công vào lúc '+r.i)}else if(!r.o){r.o=hm();toast('Đã chấm công ra lúc '+r.o)}};
function ccMe(){const me=stBy(U.id),t=DB.ts[U.id+'|'+WD],st=tsSt(U.id,WD);
 if(!needCC(me))return`<div class="card"><h2>Chấm công</h2><p>Bạn được trả lương theo ca 1-1 nên <b>không cần chấm công</b>. Tiền công tính theo số ca bạn đã dạy và điểm danh của bé.</p></div>`;
 if(!selfCC())return`<div class="card"><h2>Chấm công ngày ${DAYN[dow(WD)]} ${vd(WD)}</h2><p>${st==='leave'||st==='kl'?'Hôm nay bạn nghỉ phép đã được duyệt.':t&&t.i?'Quản lý đã chấm công: vào lúc <b>'+t.i+'</b>'+(st==='late'?' '+tg('Đi muộn','wa'):'')+(t.o?', ra lúc <b>'+t.o+'</b>':''):'Quản lý chưa chấm công cho bạn.'}</p><p class="sm mu" style="margin-top:8px">Giáo viên làm giờ cố định không tự chấm công. Quản lý hoặc Trưởng Trung tâm chấm công cho bạn mỗi ngày; nếu thấy sai, hãy báo Quản lý. Đi muộn nếu vào sau ${DB.cfg.lateAfter}.</p></div>`;
 return`<div class="card"><h2>Chấm công ngày ${DAYN[dow(WD)]} ${vd(WD)}</h2><p>${t&&t.i?'Vào lúc <b>'+t.i+'</b>'+(st==='late'?' '+tg('Đi muộn','wa'):''):'Bạn chưa chấm công vào.'}${t&&t.o?', ra lúc <b>'+t.o+'</b>':''}</p><div class="acts" style="margin-top:10px"><button class="btn y" data-a="ci" ${t&&t.o?'disabled':''}>${t&&t.i?'Chấm công ra':'Chấm công vào'}</button></div><p class="sm mu" style="margin-top:8px">Quy định: vào sau ${DB.cfg.lateAfter} tính là đi muộn. ${WD!==TODAY?'Hôm nay là ngày nghỉ nên hệ thống ghi vào ngày làm việc gần nhất.':''}</p></div>`}
function ccToday(){let h=ccMe();
 if(seesAll())h+=ccRoster();
 else if(needCC(stBy(U.id)))h+=ccMine(S.cc.m);
 return h}
/* Bảng chấm công trong ngày do Quản lý, Trưởng Trung tâm thực hiện (Văn phòng chỉ xem) */
function ccRoster(){const d=ccDay(),st=ccStaff(),cnt={},skip=DB.staff.filter(s=>s.st==='dang'&&!needCC(s)),open=isW(d)&&!isClosed(d),edit=isLead()&&open;
 st.forEach(s=>{const k=tsSt(s.id,d);cnt[k]=(cnt[k]||0)+1});
 const todo=(cnt.chua||0)+(cnt.abs||0);
 return`<div class="card"><div class="top"><h2>Chấm công ngày ${DAYN[dow(d)]} ${vd(d)}</h2><div class="acts"><div><label class="sm mu" for="cc-d">Ngày</label><input id="cc-d" type="date" data-c="ccdate" value="${d}" max="${TODAY}"></div>${edit?`<button class="btn p" data-a="ccall" ${todo?'':'disabled'}>Chấm có mặt cho ${todo} người chưa chấm</button>`:''}</div></div>
 <div class="grid">${kpi('Đúng giờ',cnt.ok||0,'ngày '+vdm(d),'ok')}${kpi('Đi muộn',cnt.late||0,'vào sau '+DB.cfg.lateAfter)}${kpi('Nghỉ phép',(cnt.leave||0)+(cnt.kl||0),'đã duyệt')}${kpi('Chưa chấm công',todo,'chưa có giờ vào',todo?'er':'')}</div>
 ${open?'':`<p class="note sm" style="margin:10px 0">Ngày ${vdm(d)} là ngày nghỉ, không chấm công.</p>`}
 `+tbl(['Nhân viên','Chức vụ','Giờ vào','Giờ ra','Trạng thái',''],st.map(s=>{const t=DB.ts[s.id+'|'+d],k=tsSt(s.id,d),can=edit&&k!=='leave'&&k!=='kl'&&k!=='hol';
  return`<tr><td><b>${esc(s.n)}</b></td><td>${esc(s.pos)}</td><td>${t?t.i||'–':'–'}</td><td>${t?t.o||'–':'–'}</td><td>${k?tg(CSYM[k]?CSYM[k][1]:'–',k==='ok'?'ok':k==='late'?'wa':k==='leave'||k==='kl'?'in':k==='abs'?'er':'gy'):''}</td><td class="nw">${can&&(k==='chua'||k==='abs')?`<button class="btn s p" data-a="ccon" data-v="${s.id}|${d}" title="Ghi vào ${ccIn()}, ra ${ccOut()}">Có mặt</button> `:''}${can?`<button class="btn s" data-a="tsedit" data-v="${s.id}|${d}">Sửa giờ</button>`:''}</td></tr>`}).join(''),'Chưa có nhân sự cần chấm công.')
 +`<p class="sm mu" style="margin-top:8px">${isLead()?`Nút "Có mặt" ghi giờ vào ${ccIn()} và giờ ra ${ccOut()} (hôm nay chưa đến giờ ra thì chỉ ghi giờ vào). Nhân sự đi muộn hoặc về sớm thì bấm "Sửa giờ". Đổi giờ mặc định ở Nhân sự, Cài đặt.`:'Chỉ xem, việc chấm công do Quản lý hoặc Trưởng Trung tâm thực hiện.'}</p>`
 +(skip.length?`<p class="sm mu" style="margin-top:6px">Không cần chấm công (trả lương theo ca 1-1): ${skip.map(s=>esc(s.n)).join(', ')}.</p>`:'')+`</div>`}
/* ghi có mặt đủ giờ cho một người trong ngày d; chỉ khi ngày đó còn trống (chưa chấm hoặc vắng) */
function ccMark(id,d){const s=stBy(id);if(!s||!needCC(s)||d>TODAY)return false;const k=tsSt(id,d);if(k!=='chua'&&k!=='abs')return false;
 const now=hm();DB.ts[id+'|'+d]={i:d===TODAY&&now<ccIn()?now:ccIn(),o:d<TODAY||now>=ccOut()?ccOut():''};return true}
CHG.ccdate=v=>{if(!v||v>TODAY)return false;S.cc.d=v};
ACT.ccon=v=>{if(!isLead())return false;const [id,d]=v.split('|');if(!ccMark(id,d))return false;toast('Đã chấm công cho '+sn(id))};
ACT.ccall=()=>{if(!isLead())return false;const d=ccDay();let n=0;ccStaff().forEach(s=>{if(ccMark(s.id,d))n++});if(!n)return false;toast('Đã chấm có mặt cho '+n+' người')};
function ccMine(m){const s=stBy(U.id),p=payroll(s,m),rows=mDates(m).filter(d=>isW(d)&&d<=TODAY);
 return`<div class="card"><div class="top"><h2>${mLabel(m)}</h2><div class="acts"><button class="btn s" data-a="ccm" data-v="-1">Tháng trước</button><button class="btn s" data-a="ccm" data-v="1" ${m>=CM?'disabled':''}>Tháng sau</button></div></div><p class="mu sm" style="margin-bottom:8px">Công ${p.cong}/${DB.cfg.cc} · đi muộn ${p.late} lần · nghỉ phép ${p.leave} ngày · vắng ${p.abs} ngày</p>`
 +tbl(['Ngày','Giờ vào','Giờ ra','Trạng thái'],rows.reverse().map(d=>{const t=DB.ts[U.id+'|'+d],k=tsSt(U.id,d);return`<tr><td class="nw">${DAYS[dow(d)]} ${vdm(d)}</td><td>${t?t.i||'–':'–'}</td><td>${t?t.o||'–':'–'}</td><td>${k?tg(CSYM[k][1],k==='ok'?'ok':k==='late'?'wa':k==='leave'||k==='kl'?'in':k==='abs'?'er':'gy'):''}</td></tr>`}).join(''),'Chưa có ngày làm việc nào.')+`</div>`}
function ccGrid(){const m=S.cc.m,ds=mDates(m),st=ccStaff(),skip=DB.staff.filter(s=>s.st==='dang'&&!needCC(s));
 return`<div class="card"><div class="top"><h2>Bảng công ${mLabel(m)}</h2><div class="acts"><button class="btn s" data-a="ccm" data-v="-1">Tháng trước</button><button class="btn s" data-a="ccm" data-v="1" ${m>=CM?'disabled':''}>Tháng sau</button><button class="btn s" data-a="ccxl">Xuất Excel</button></div></div>
 <div class="legend">${Object.entries(CSYM).map(([k,v])=>`<span><i class="sc sc-${v[0]==='·'?'q':v[0]}">${v[0]}</i> ${v[1]}</span>`).join('')}</div>
 <div class="tw"><table class="sheet"><thead><tr><th class="s1">Nhân viên</th>${ds.map(d=>`<th class="dc ${dow(d)===0?'sun':''}">${pd(d).getDate()}<br><span class="mu">${DAYS[dow(d)]}</span></th>`).join('')}<th class="r">Công</th><th class="r">Muộn</th><th class="r">Phép</th></tr></thead><tbody>
 ${st.map(s=>{const p=payroll(s,m);return`<tr><td class="s1"><b>${esc(given(s.n))}</b></td>${ds.map(d=>{const k=dow(d)===0?'':tsSt(s.id,d),sy=k?CSYM[k][0]:'';return`<td class="dc ${dow(d)===0?'sun':''}">${sy?`<button class="sc sc-${sy==='·'?'q':sy}" data-a="tsedit" data-v="${s.id}|${d}" title="${CSYM[k][1]}" ${isLead()&&d<=TODAY?'':'disabled'}>${sy}</button>`:''}</td>`}).join('')}<td class="r"><b>${p.cong}</b></td><td class="r">${p.late}</td><td class="r">${p.leave}</td></tr>`}).join('')}</tbody></table></div><p class="sm mu" style="margin-top:8px">${isLead()?'Bấm vào một ô để sửa giờ vào ra. ':'Chỉ xem, việc sửa công do Quản lý hoặc Trưởng Trung tâm thực hiện. '}Công chuẩn mỗi tháng là ${DB.cfg.cc} ngày.${skip.length?' Không cần chấm công (trả lương theo ca 1-1): '+skip.map(s=>esc(s.n)).join(', ')+'.':''}</p></div>`}
ACT.ccxl=()=>{const m=S.cc.m,ds=mDates(m).filter(isW);exportXLSX('bang-cong-nhan-vien-'+m+'.xlsx',[{n:'Bảng công',rows:[['Mã','Nhân viên','Chức vụ'].concat(ds.map(d=>pd(d).getDate()+'/'+(+m.slice(5,7))),['Công','Đi muộn','Nghỉ phép','Vắng'])].concat(ccStaff().map(s=>{const p=payroll(s,m);return[s.id,s.n,s.pos].concat(ds.map(d=>{const k=tsSt(s.id,d);return k?CSYM[k][0]:''}),[p.cong,p.late,p.leave,p.abs])}))}])};
ACT.tsedit=v=>{const [id,d]=v.split('|');if(!isLead()||!needCC(stBy(id)))return false;S.modal={t:'tse',id,d}};
MODALS.tse=()=>{const m=S.modal,t=DB.ts[m.id+'|'+m.d]||{i:'',o:''};
 return mdl('Chấm công '+sn(m.id),`<form id="tsef" class="f"><p class="mu sm">${DAYN[dow(m.d)]} ${vd(m.d)}</p><div class="f2"><div><label for="ts-i">Giờ vào</label><input id="ts-i" name="i" type="time" value="${t.i}"></div><div><label for="ts-o">Giờ ra</label><input id="ts-o" name="o" type="time" value="${t.o}"></div></div><div class="acts" style="justify-content:flex-end"><button class="btn no" type="button" data-a="tsclr">Xóa chấm công</button><button class="btn" type="button" data-a="mx">Hủy</button><button class="btn p" type="submit">Lưu</button></div></form>`)};
FORM.tsef=f=>{if(!isLead())return false;const m=S.modal,i=f.elements.i.value,o=f.elements.o.value;if(!i&&!o)delete DB.ts[m.id+'|'+m.d];else DB.ts[m.id+'|'+m.d]={i,o};S.modal=null;toast('Đã cập nhật chấm công')};
ACT.tsclr=()=>{if(!isLead())return false;delete DB.ts[S.modal.id+'|'+S.modal.d];S.modal=null;toast('Đã xóa chấm công')};
/* --- đơn nghỉ phép --- */
function ccLeave(){const rows=DB.lr.filter(l=>seesAll()||l.st===U.id).sort((a,b)=>a.s===b.s?(a.f<b.f?1:-1):a.s==='cho'?-1:1);
 return`<div class="card">`+tbl(['Nhân viên','Loại','Thời gian','Số ngày','Lý do','Trạng thái',''],rows.map(l=>`<tr><td><b>${esc(sn(l.st))}</b></td><td>${LRT[l.type]}</td><td class="nw">${vdm(l.f)}${l.t!==l.f?' đến '+vdm(l.t):''}</td><td>${lrDays(l)}</td><td>${esc(l.why)}</td><td>${tg(LRS[l.s][0],LRS[l.s][1])}</td><td class="nw">${l.s==='cho'&&isLead()?`<button class="btn s p" data-a="lrok" data-v="${l.id}">Duyệt</button> <button class="btn s no" data-a="lrno" data-v="${l.id}">Từ chối</button>`:l.s==='cho'&&l.st===U.id?`<button class="btn s no" data-a="lrdel" data-v="${l.id}">Hủy đơn</button>`:''}</td></tr>`).join(''),'Chưa có đơn nghỉ nào.')+`<p class="note sm" style="margin-top:10px">Khi duyệt đơn nghỉ của giáo viên, các buổi 1-1 rơi vào thời gian nghỉ tự động được ghi "Trung tâm/GV nghỉ" và tạo yêu cầu học bù cho từng bé.${feeTx(' Nếu gia đình không nhận học bù, trung tâm hoàn phí buổi đó theo quy định.')}</p></div>`}
function applyLeave(l){let n=0;
 for(let d=l.f;d<=l.t;d=addD(d,1)){if(!isW(d))continue;
  DB.lich.forEach(x=>{if(x.gv===l.st&&((x.type==='11'&&x.day===dow(d))||(x.type==='bu'&&x.date===d))){const key=d+'|'+x.id+'|'+x.hs;
   if(!DB.att[key]){DB.att[key]='tt';n++;if(x.type==='11'&&!DB.mk.some(r=>r.hs===x.hs&&r.from.d===d&&r.from.sid===x.id))DB.mk.push({id:'mk'+uid(),hs:x.hs,from:{d,sid:x.id,kind:'11',slot:x.slot},by:'gv',why:'Giáo viên nghỉ phép',s:'dk',props:[],pick:null,log:[{at:TODAY,by:'tt',tx:'Tạo tự động khi duyệt đơn nghỉ của giáo viên'}]})}}})}
 return n}
ACT.lrok=v=>{if(!isLead())return false;const l=DB.lr.find(x=>x.id===v);if(!l)return;l.s='duyet';const n=applyLeave(l);toast(n?'Đã duyệt. '+n+' buổi học được ghi nhận Trung tâm/GV nghỉ':'Đã duyệt đơn nghỉ')};
ACT.lrno=v=>{if(!isLead())return false;const l=DB.lr.find(x=>x.id===v);if(l){l.s='tuchoi';toast('Đã từ chối đơn')}};
ACT.lrdel=v=>{DB.lr=DB.lr.filter(x=>x.id!==v);toast('Đã hủy đơn')};
ACT.lrnew=()=>{S.modal={t:'lr'}};
MODALS.lr=()=>mdl('Tạo đơn nghỉ',`<form id="lrf" class="f">${isLead()?`<div><label for="lr-s">Nhân viên</label><select id="lr-s" name="st">${opts(DB.staff.filter(s=>s.st==='dang').map(s=>[s.id,s.n]),U.id)}</select></div>`:''}<div class="f2"><div><label for="lr-t">Loại nghỉ</label><select id="lr-t" name="type">${opts(Object.entries(LRT),'phep')}</select></div><div><label for="lr-f">Từ ngày</label><input id="lr-f" name="f" type="date" value="${addD(TODAY,1)}" required></div><div><label for="lr-e">Đến ngày</label><input id="lr-e" name="t" type="date" value="${addD(TODAY,1)}" required></div></div><div><label for="lr-w">Lý do</label><input id="lr-w" name="why" required></div><div class="acts" style="justify-content:flex-end"><button class="btn" type="button" data-a="mx">Hủy</button><button class="btn p" type="submit">Gửi đơn</button></div></form>`);
FORM.lrf=f=>{const e=f.elements,fr=e.f.value,to=e.t.value;if(to<fr){toast('Ngày kết thúc phải sau ngày bắt đầu');return false}
 DB.lr.push({id:'lr'+uid(),st:e.st?e.st.value:U.id,type:e.type.value,f:fr,t:to,why:e.why.value.trim(),s:'cho'});S.modal=null;toast('Đã gửi đơn nghỉ, chờ duyệt')};
/* ===== 7. Điểm danh: theo ngày ===== */
const STB={'11':['cm','p','kp','tt'],bt:['cm','p','kp','bv','tt'],bu:['cm','p','kp'],inc:['cm','p','kp','bv','tt']};
const canEditAtt=d=>d<=TODAY&&(isLead()||(isGV()&&d>=addD(TODAY,-7)));
const attKey=(d,s,h)=>d+'|'+s+'|'+h;
const mkFor=(h,d,sid)=>DB.mk.find(r=>r.hs===h&&r.from.d===d&&r.from.sid===sid);
VIEWS.dd=()=>{const t=S.dd=Object.assign({tab:seesAll()?'sheet':'roll',date:WD,m:WD.slice(0,7),q:'',pr:'',fl:'',gv:'',kid:'',un:false},S.dd);
 if(t.tab==='rule'&&!canMoney())t.tab='sheet';
 return head(isVP()?'Ngày học và phép':'Điểm danh',canMoney()?'Điểm danh từng ngày và bảng chấm công học sinh để tính học phí, hoàn phí':'Điểm danh từng ngày và bảng chấm công học sinh: số ngày học, nghỉ có phép và không phép')+tabsH([['roll','Điểm danh theo ngày'],['sheet',isGV()?'Bảng chấm công của lớp':'Bảng chấm công học sinh']].concat(canMoney()?[['rule','Quy định học phí và hoàn phí']]:[]),t.tab,'ddtab')+(t.tab==='roll'?ddRoll():t.tab==='sheet'?ddSheet():ddRule())};
ACT.ddtab=v=>{S.dd.tab=v};
ACT.ddkid=v=>{go('dd',{dd:Object.assign(S.dd||{},{tab:'sheet',kid:v,fl:'',pr:'',q:''})})};
CHG.dddate=v=>{if(v)S.dd.date=v};
ACT.ddday=v=>{let d=addD(S.dd.date,+v);if(!isW(d))d=addD(d,+v);S.dd.date=d};
CHG.ddgv=v=>{S.dd.gv=v};
CHG.ddun=(v,t)=>{S.dd.un=t.checked};
const stb=(d,s,k,can)=>{const cur=DB.att[attKey(d,s.sid,k.id)]||'';
 return`<div class="stb" role="group" aria-label="Trạng thái của ${esc(k.n)}">${STB[s.inc?'inc':s.kind].map(c=>`<button class="st st-${c} ${cur===c?'on':''}" data-a="att" data-v="${d}|${s.sid}|${k.id}|${c}" aria-pressed="${cur===c}" ${can?'':'disabled'}>${AC[c]}</button>`).join('')}</div>`};
const feeNote=(d,s,k)=>{const cur=DB.att[attKey(d,s.sid,k.id)];if(!cur||cur==='cm')return'';
 if(s.kind==='bu')return noFee()?'':'<span class="sm mu">Buổi học bù, không tính thêm phí</span>';
 if(s.inc)return canMoney()?'<span class="sm mu">Ca 1-1 nằm trong phí bán trú, tính theo ngày bán trú</span>':'';
 if(!canMoney())return'';
 const o=feeOf(k,s.kind,d,s.sid,cur,d.slice(0,7));
 return`<span class="sm">${esc(o.note)}${o.ls||o.rf?'. Mất <b>'+fnum(o.ls)+' ₫</b>, hoàn <b>'+fnum(o.rf)+' ₫</b>':''}</span>`};
const mkBtn=(d,s,k)=>{const cur=DB.att[attKey(d,s.sid,k.id)];if(s.kind!=='11'||s.inc||!['p','kp','tt'].includes(cur)||!canEditAtt(d))return'';
 const r=mkFor(k.id,d,s.sid);return r?`<button class="btn s" data-a="nav" data-v="hb">Học bù: ${esc(MKS[r.s]?MKS[r.s][0]:'')}</button>`:`<button class="btn s" data-a="mkfrom" data-v="${d}|${s.sid}|${k.id}">Tạo yêu cầu học bù</button>`};
ACT.att=v=>{const [d,sid,h,c]=v.split('|');if(!canKid(h)||!canEditAtt(d)){toast('Bạn chưa thể sửa điểm danh này');return false}
 const key=attKey(d,sid,h),old=DB.att[key];if(old===c)delete DB.att[key];else DB.att[key]=c;
 /* ngày bán trú: ca 1-1 trong gói đi theo tình trạng nghỉ của ngày (ghi nghỉ thì ca 1-1 cũng nghỉ; bỏ hoặc đổi sang có mặt thì bỏ theo) */
 const k=kidBy(h);if(k&&grBy(sid)){const li=incSession(k,d);if(li){const lk=attKey(d,li,h),cur=DB.att[lk],now=DB.att[key];
  if(now&&now!=='cm'){if(!cur||cur===old)DB.att[lk]=now}else if(cur&&old&&old!=='cm'&&cur===old)delete DB.att[lk]}}};
ACT.attall=v=>{const [d,sid]=v.split('|'),s=dayList(d).find(x=>x.sid===sid);if(!s||!canEditAtt(d)){toast('Bạn chưa thể sửa điểm danh này');return false}
 let n=0;s.kids.forEach(k=>{const key=attKey(d,sid,k.id);if(!DB.att[key]){DB.att[key]='cm';n++}});toast(n?'Đã ghi có mặt cho '+n+' trẻ':'Mọi trẻ đã được điểm danh')};
function ddRoll(){const t=S.dd,d=t.date,can=canEditAtt(d);
 let ds=dayList(d).filter(s=>seesAll()?(!t.gv||rowHas(s,t.gv)):rowHas(s,U.id));
 const pend=s=>s.kids.some(k=>!DB.att[attKey(d,s.sid,k.id)]);if(t.un)ds=ds.filter(pend);
 const one=ds.filter(s=>s.kind!=='bt'),grp=ds.filter(s=>s.kind==='bt');let tot=0,rec=0,cm=0;
 ds.forEach(s=>s.kids.forEach(k=>{tot++;const c=DB.att[attKey(d,s.sid,k.id)];if(c){rec++;if(c==='cm')cm++}}));
 const ctl=`<div class="card"><div class="f2"><div><label for="dd-d">Ngày</label><input id="dd-d" type="date" data-c="dddate" value="${d}" max="${TODAY}"></div>${seesAll()?`<div><label for="dd-g">Giáo viên</label><select id="dd-g" data-c="ddgv"><option value="">Tất cả</option>${opts(DB.staff.filter(isTeacher).map(s=>[s.id,tName(s)]),t.gv)}</select></div>`:''}<div style="display:flex;align-items:end"><label class="chk" style="margin:0 0 8px"><input type="checkbox" data-c="ddun" ${t.un?'checked':''}> Chỉ hiện lượt chưa điểm danh</label></div></div>
 <div class="acts" style="margin-top:10px"><button class="btn s" data-a="ddday" data-v="-1">Ngày trước</button><button class="btn s" data-a="ddday" data-v="1" ${addD(d,1)>TODAY?'disabled':''}>Ngày sau</button><b>${DAYN[dow(d)]}, ${vd(d)}</b>${d===WD&&WD!==TODAY?'<span class="mu sm">(ngày làm việc gần nhất)</span>':''}</div>
 ${!can?`<p class="note sm" style="margin-top:10px">${d>TODAY?'Chưa đến ngày này nên chưa điểm danh được.':isVP()?'Văn phòng chỉ xem điểm danh. Việc ghi và sửa do giáo viên, Quản lý hoặc Trưởng Trung tâm thực hiện.':'Giáo viên chỉ sửa được điểm danh trong 7 ngày gần nhất. Nhờ Quản lý hoặc Trưởng Trung tâm chỉnh giúp.'}</p>`:''}</div>`;
 const kp=`<div class="grid">${kpi('Lượt học',tot,'trong ngày')}${kpi('Đã điểm danh',rec+'/'+tot,tot?Math.round(rec*100/tot)+'%':'',rec<tot?'er':'ok')}${kpi('Có mặt',cm,rec?Math.round(cm*100/rec)+'% số đã ghi':'')}${kpi('Nghỉ',rec-cm,'P, KP, TT/GV nghỉ, nhập viện')}</div>`;
 if(!ds.length)return ctl+`<div class="card"><p class="empty">${dow(d)===0?'Chủ nhật trung tâm nghỉ.':isClosed(d)?'Trung tâm nghỉ ngày này: '+esc(holOf(d).n)+'. Ngày nghỉ không tính học phí và không cần điểm danh.':'Không có buổi học nào phù hợp trong ngày này.'}</p></div>`;
 const hint=`<p class="note sm" style="margin-bottom:12px"><b>Cách ghi P và KP:</b> Nghỉ P khi phụ huynh báo trong nhóm chung trước 7g sáng cùng ngày với ca sáng, trước 12g với ca chiều và tối (bán trú: báo trước 1 ngày hoặc trước 7g sáng). Báo sau mốc này hoặc không báo thì ghi KP. Bấm lại vào trạng thái đang chọn để xóa.</p>`;
 const t1=one.length?`<div class="card"><h2>Can thiệp 1-1 và học bù</h2>`+tbl(['Ca','Bé','Giáo viên','Phòng','Trạng thái','Ghi chú'],one.map(s=>{const k=s.kids[0];return`<tr><td class="nw">${slotLb(s.slot)}${s.kind==='bu'?'<br>'+tg('Học bù','y'):''}${s.inc?'<br>'+tg('1-1 của bán trú','in'):''}</td><td><b>${esc(k.n)}</b></td><td>${esc(given(sn(s.gv)))}</td><td class="nw">${esc(s.room)}</td><td>${stb(d,s,k,can)}</td><td>${feeNote(d,s,k)} ${mkBtn(d,s,k)}</td></tr>`}).join(''))+`</div>`:'';
 const t2=grp.map(s=>`<div class="card"><div class="top"><div><h2>${esc(s.label)}</h2><p class="mu sm">Giáo viên ${esc(s.ts.map(sn).join(', ')||'Chưa phân công')} · ${s.kids.length} trẻ</p></div><button class="btn s" data-a="attall" data-v="${d}|${s.sid}" ${can?'':'disabled'}>Ghi mọi trẻ có mặt</button></div>`+tbl(['Bé','Trạng thái','Ghi chú'],s.kids.map(k=>`<tr><td><b>${esc(k.n)}</b></td><td>${stb(d,s,k,can)}</td><td>${feeNote(d,s,k)}</td></tr>`).join(''))+`</div>`).join('');
 return ctl+kp+hint+t1+t2}
/* --- sửa nhanh một ô trong bảng chấm công --- */
ACT.scopen=v=>{const [h,d]=v.split('|');S.modal={t:'sc',id:h,d}};
MODALS.sc=()=>{const m=S.modal,k=kidBy(m.id),xs=sched(k,m.d.slice(0,7)).filter(x=>x.d===m.d),can=canEditAtt(m.d);
 return mdl(k.n+' · '+DAYN[dow(m.d)]+' '+vd(m.d),(can?'':'<p class="note sm" style="margin-bottom:10px">Bạn chưa sửa được ngày này.</p>')+(xs.map(x=>{const s={sid:x.sid,kind:x.kind,inc:x.inc};return`<div class="card"><b>${x.kind==='bt'?'Bán trú · '+esc((grBy(x.sid)||{}).n||''):x.kind==='bu'?'Học bù · '+slotLb(x.slot):(x.inc?'Ca 1-1 của bán trú · ':'Can thiệp 1-1 · ')+slotLb(x.slot)}</b><div style="margin:8px 0">${stb(m.d,s,k,can)}</div>${feeNote(m.d,s,k)} ${mkBtn(m.d,s,k)}</div>`}).join('')||'<p class="empty">Bé không có lịch học ngày này.</p>'))};
/* ===== Bảng chấm công học sinh ===== */
const SYM={L:'Nghỉ lễ, Trung tâm nghỉ',x:'Có mặt',P:'Nghỉ có phép',K:'Nghỉ không phép',N:'Trung tâm/GV nghỉ',V:'Nhập viện (bán trú)',B:'Học bù có mặt','?':'Chưa ghi'};
const symCls=c=>c==='?'?'q':c;
const billed=(h,m)=>{const e=DB.lg.filter(x=>x.hs===h&&x.kind==='hp'&&x.m===m);return e.length?e.reduce((s,x)=>s+x.amt,0):invoice(kidBy(h),m)};
const progShort=k=>{const bd=btOf(k),e=ex11(k);return [bd.length?'Bán trú '+dayTx(bd):'',e>0?'1-1 x'+e+(bd.length?' thêm':''):''].filter(Boolean).join(' + ')||(k.bt?'Bán trú':'–')};
const postState=(k,r,m)=>{const s=DB.set[k.id+'|'+m];if(!r.refund&&!s)return['–',''];if(s&&s.amt===r.refund)return['Đã ghi','ok'];return[s?'Cần ghi lại':'Chưa ghi',s?'wa':'gy']};
function sheetRows(){const t=S.dd,m=t.m;if(t.fl==='ref'&&!canMoney())t.fl='';const q=t.q.toLowerCase(),has=new Set();for(const key in DB.att)if(key.startsWith(m))has.add(key.split('|')[2]);
 return myKids().filter(k=>t.kid?k.id===t.kid:(k.st==='dang'||has.has(k.id))).filter(k=>!q||(k.n+' '+k.id).toLowerCase().includes(q))
  .map(k=>({k,r:settle(k,m),inv:canMoney()?billed(k.id,m):0}))
  .filter(x=>(x.r.plan+x.r.planBt+x.r.bu)>0&&(!t.pr||(t.pr==='11'?x.r.plan>0:x.r.planBt>0))&&(!t.fl||(t.fl==='abs'?x.r.p+x.r.kp+x.r.tt+x.r.bv>0:t.fl==='none'?x.r.none>0:(x.r.refund+x.r.lost)>0)))}
ACT.ddm=v=>{S.dd.m=sm(S.dd.m,+v);S.pg.ddsh=1};
ACT.ddclr=()=>{S.dd.kid='';S.pg.ddsh=1};
INP.ddq=v=>{S.dd.q=v;S.pg.ddsh=1};CHG.ddpr=v=>{S.dd.pr=v;S.pg.ddsh=1};CHG.ddfl=v=>{S.dd.fl=v;S.pg.ddsh=1};
const cellH=(k,r,d)=>{if(dow(d)===0)return'<td class="dc sun"></td>';if(isClosed(d))return`<td class="dc"><i class="sc sc-L" title="${esc(holOf(d).n)}">L</i></td>`;const c=r.cells[d];
 return`<td class="dc">${c?`<button class="dcell" data-a="scopen" data-v="${k.id}|${d}" title="${vd(d)}">${c.map(x=>`<i class="sc sc-${symCls(x)}">${x}</i>`).join('')}</button>`:''}</td>`};
function ddSheet(){const t=S.dd,m=t.m,ds=mDates(m),rows=sheetRows(),L=canMoney(),p=pg('ddsh',rows,20);
 const T=rows.reduce((a,x)=>({inv:a.inv+x.inv,lost:a.lost+x.r.lost,ref:a.ref+x.r.refund,none:a.none+x.r.none,cm:a.cm+x.r.cm,ab:a.ab+x.r.p+x.r.kp+x.r.tt+x.r.bv}),{inv:0,lost:0,ref:0,none:0,cm:0,ab:0});
 const need=rows.filter(x=>x.r.refund>0).length,done=rows.filter(x=>x.r.refund>0&&DB.set[x.k.id+'|'+m]&&DB.set[x.k.id+'|'+m].amt===x.r.refund).length;
 const kp=L?`<div class="grid">${kpi('Học phí '+mLow(m),fmt(T.inv),rows.length+' trẻ có lịch học')}${kpi('Phí mất do nghỉ',fmt(T.lost),'nghỉ không phép và nghỉ có phép')}${kpi('Hoàn trừ vào tháng sau',fmt(T.ref),'đã ghi '+done+'/'+need+' khoản','ok')}${kpi('Lượt chưa ghi',T.none,'cần điểm danh bổ sung',T.none?'er':'ok')}</div>`:`<div class="grid">${kpi('Trẻ có lịch',rows.length,mLabel(m))}${kpi('Lượt có mặt',T.cm,'')}${kpi('Lượt nghỉ',T.ab,'P, KP, TT/GV nghỉ, nhập viện')}${kpi('Lượt chưa ghi',T.none,'cần điểm danh bổ sung',T.none?'er':'ok')}</div>`;
 const ctl=`<div class="card"><div class="top" style="margin-bottom:10px"><div class="acts"><button class="btn s" data-a="ddm" data-v="-1">Tháng trước</button><b>${mLabel(m)}</b><button class="btn s" data-a="ddm" data-v="1" ${m>=CM?'disabled':''}>Tháng sau</button></div><div class="acts"><button class="btn s" data-a="ddxl">Xuất Excel</button><button class="btn s" data-a="ddpdf">Xuất PDF</button>${L?`<button class="btn y s" data-a="ddpost" ${need?'':'disabled'}>Ghi khoản hoàn vào công nợ</button>`:''}</div></div>
 <div class="f2"><div><label for="ddq">Tìm bé</label><input id="ddq" data-i="ddq" value="${esc(t.q)}"></div><div><label for="ddpr">Chương trình</label><select id="ddpr" data-c="ddpr"><option value="">Tất cả</option>${opts([['11','Có can thiệp 1-1'],['bt','Có bán trú']],t.pr)}</select></div><div><label for="ddfl">Hiển thị</label><select id="ddfl" data-c="ddfl"><option value="">Mọi trẻ</option>${opts([['abs','Trẻ có nghỉ'],['none','Trẻ còn lượt chưa ghi']].concat(L?[['ref','Trẻ có phí mất hoặc hoàn']]:[]),t.fl)}</select></div></div>
 ${t.kid?`<p style="margin-top:10px">${tg('Đang xem riêng: '+kn(t.kid),'in')} <button class="btn s" data-a="ddclr">Xem tất cả trẻ</button></p>`:''}</div>`;
 const head1=`<tr><th class="s1">Bé</th><th class="s2">Chương trình</th>${ds.map(d=>`<th class="dc ${dow(d)===0?'sun':''}">${pd(d).getDate()}<br><span class="mu">${DAYS[dow(d)]}</span></th>`).join('')}<th class="r" title="Số ca 1-1 tính riêng theo lịch (không kể ca 1-1 trong gói bán trú)">KH 1-1</th><th class="r" title="Số ngày bán trú theo lịch">KH BT</th><th class="r">Có mặt</th><th class="r">P</th><th class="r">KP</th><th class="r">TT/GV</th><th class="r">Viện</th><th class="r">Bù</th><th class="r">Chưa ghi</th>${L?'<th class="r">Học phí</th><th class="r">Phí mất</th><th class="r">Hoàn</th><th>Ghi nhận</th>':''}</tr>`;
 const body=p.rows.map(({k,r,inv})=>{const ps=postState(k,r,m);
  return`<tr><td class="s1"><button class="lk" data-a="sdopen" data-v="${k.id}|${m}">${esc(k.n)}</button><div class="sm mu">${esc(kcode(k))}${k.st!=='dang'?' · '+KST[k.st]:''}</div></td><td class="s2 nw">${progShort(k)}</td>${ds.map(d=>cellH(k,r,d)).join('')}<td class="r">${r.plan}</td><td class="r">${r.planBt}</td><td class="r"><b>${r.cm}</b></td><td class="r">${r.p}</td><td class="r">${r.kp}</td><td class="r">${r.tt}</td><td class="r">${r.bv}</td><td class="r">${r.bu}</td><td class="r ${r.none?'er':''}">${r.none}</td>${L?`<td class="r nw">${fnum(inv)}</td><td class="r nw">${fnum(r.lost)}</td><td class="r nw"><b>${fnum(r.refund)}</b></td><td>${ps[1]?tg(ps[0],ps[1]):ps[0]}</td>`:''}</tr>`}).join('');
 return kp+ctl+`<div class="card"><div class="legend">${Object.entries(SYM).map(([c,l])=>`<span><i class="sc sc-${symCls(c)}">${c}</i> ${l}</span>`).join('')}</div>
 <div class="tw"><table class="sheet"><thead>${head1}</thead><tbody>${body||`<tr><td colspan="${ds.length+(L?15:11)}" class="empty">Không có trẻ phù hợp trong ${mLabel(m)}.</td></tr>`}</tbody></table></div>${p.html}
 <p class="sm mu" style="margin-top:8px">${L?'Bấm vào tên bé để xem cách tính chi tiết':'Bấm vào tên bé để xem các buổi nghỉ'}, bấm vào một ô ngày để ${isVP()?'xem':'sửa'} điểm danh. Dấu ? là buổi đã qua nhưng chưa được ghi. ${L?'Khoản hoàn trừ vào học phí tháng sau; phí mất không hoàn lại.':''}</p></div>`}
ACT.ddpost=()=>{if(!canMoney())return false;const m=S.dd.m,ks=sheetRows().map(x=>x.k),n=ks.filter(k=>settle(k,m).refund>0).length;
 ask('Ghi khoản hoàn của '+mLow(m)+' cho '+n+' trẻ vào công nợ tháng '+sm(m,1).slice(5)+'/'+sm(m,1).slice(0,4)+'? Các khoản đã ghi trước đó của tháng này sẽ được cập nhật theo bảng hiện tại.',()=>{ks.forEach(k=>postSettle(k,m));toast('Đã ghi khoản hoàn vào công nợ')},'Ghi khoản hoàn')};
/* ===== Chi tiết từng bé, xuất tệp, quy định ===== */
ACT.sdopen=v=>{const [id,m]=v.split('|');S.modal={t:'sd',id,m}};
ACT.sdpost=()=>{if(!canMoney())return false;const k=kidBy(S.modal.id);postSettle(k,S.modal.m);toast('Đã ghi khoản hoàn của '+k.n+' vào công nợ')};
ACT.nsgo=()=>{go('ns',{ns:Object.assign(S.ns||{},{tab:'cd'})})};
MODALS.sd=()=>{const {id,m}=S.modal,k=kidBy(id);if(!k||!canKid(id)){S.modal=null;return''}
 const r=settle(k,m),L=canMoney(),inv=L?billed(id,m):0,nm=sm(m,1),next=L?invoice(k,nm):0,ps=postState(k,r,m);
 const mini=(l,v,c)=>`<div class="card kpi mini"><div class="mu sm">${l}</div><div class="big ${c||''}">${v}</div></div>`;
 const pend=Object.keys(r.cells).filter(d=>r.cells[d].includes('?')).sort().map(vdm);
 const money=L?`<div class="grid">${mini('Học phí '+mLow(m),fmt(inv))}${mini('Phí mất do nghỉ',fmt(r.lost))}${mini('Hoàn trừ tháng sau',fmt(r.refund),'ok')}${mini('Học phí '+mLow(nm)+' dự kiến',fmt(Math.max(0,next-r.refund)))}</div><p class="sm mu" style="margin:-4px 0 12px">Học phí ${mLabel(nm)} dự kiến = ${fmt(next)} theo lịch${holIn(nm).length?' (đã trừ '+holIn(nm).length+' ngày nghỉ lễ)':''} trừ ${fmt(r.refund)} phí dư của ${mLow(m)}.${r.stop?' Bé đã ngưng can thiệp nên không hoàn phí dư nào.':''}</p>`:'';
 const rows=r.rows.sort((a,b)=>a.d<b.d?-1:1).map(x=>`<tr><td class="nw">${DAYS[dow(x.d)]} ${vdm(x.d)}</td><td>${x.kind==='11'?'1-1':'Bán trú'}</td><td class="nw">${x.kind==='11'?slotLb(x.slot):'Cả ngày'}</td><td>${tg(AC[x.code],x.code==='kp'?'er':x.code==='p'?'wa':x.code==='bv'?'in':'gy')}</td>${L?`<td>${esc(x.note)}</td><td class="r nw">${fnum(x.ls)}</td><td class="r nw">${fnum(x.rf)}</td>`:''}</tr>`).join('');
 return mdl('Chi tiết chấm công · '+k.n,`<p class="mu sm" style="margin-bottom:10px">${mLabel(m)} · ${esc(progShort(k))} · ${esc(mainGV(k))}</p>
 <div class="grid g3">${mini('Kế hoạch',r.plan+' 1-1'+(r.planInc?' (+'+r.planInc+' trong gói)':'')+', '+r.planBt+' ngày BT')}${mini('Có mặt',r.cm,'ok')}${mini('Nghỉ P / KP',r.p+' / '+r.kp)}${mini('TT/GV nghỉ',r.tt)}${mini('Nhập viện',r.bv)}${mini('Học bù có mặt',r.bu)}</div>${money}
 ${pend.length?`<p class="note sm" style="margin-bottom:12px"><b>Chưa điểm danh:</b> ${pend.join(', ')}. Hoàn thành điểm danh${L?' để khoản hoàn được tính đủ':' để số ngày học được tính đủ'}.</p>`:''}
 <h2>${L?'Các buổi nghỉ và cách tính':'Các buổi nghỉ'}</h2>`+tbl(['Ngày','Loại','Ca','Trạng thái'].concat(L?['Cách tính','>Mất (₫)','>Hoàn (₫)']:[]),rows,'Bé không có buổi nghỉ nào trong tháng.')
 +(L?`<div class="acts" style="margin-top:12px;justify-content:space-between"><span class="sm">Ghi nhận công nợ: ${ps[1]?tg(ps[0],ps[1]):ps[0]}</span><button class="btn y" data-a="sdpost" ${r.refund||DB.set[id+'|'+m]?'':'disabled'}>Ghi khoản hoàn của bé này</button></div>`:'')
 +(L?`<details style="margin-top:14px"><summary style="cursor:pointer" class="sm"><b>Quy định đang áp dụng</b></summary>${r.plan?policyH('m11'):''}${r.planBt?policyH('bt'):''}</details>`:''),1)};
/* --- xuất Excel và PDF --- */
ACT.ddxl=()=>{const m=S.dd.m,rows=sheetRows(),L=canMoney(),ds=mDates(m);
 const s1=[['Mã','Họ tên','Chương trình','Kế hoạch 1-1','Kế hoạch bán trú','Có mặt','Nghỉ P','Nghỉ KP','TT/GV nghỉ','Nhập viện','Học bù','Chưa ghi'].concat(L?['Học phí tháng','Phí mất do nghỉ','Hoàn trừ tháng sau']:[])].concat(rows.map(({k,r,inv})=>[kcode(k),k.n,progShort(k),r.plan,r.planBt,r.cm,r.p,r.kp,r.tt,r.bv,r.bu,r.none].concat(L?[inv,r.lost,r.refund]:[])));
 const s2=[['Mã','Họ tên','Ngày','Loại','Ca','Trạng thái'].concat(L?['Cách tính','Mất','Hoàn']:[])];
 rows.forEach(({k,r})=>r.rows.forEach(x=>s2.push([kcode(k),k.n,vd(x.d),x.kind==='11'?'1-1':'Bán trú',x.kind==='11'?slotLb(x.slot):'Cả ngày',AC[x.code]].concat(L?[x.note,x.ls,x.rf]:[]))));
 const s3=[['Mã','Họ tên'].concat(ds.map(d=>pd(d).getDate()+'/'+(+m.slice(5,7))))].concat(rows.map(({k,r})=>[kcode(k),k.n].concat(ds.map(d=>(r.cells[d]||[]).join('+')))));
 exportXLSX('bang-cham-cong-hoc-sinh-'+m+'.xlsx',[{n:'Tổng hợp',rows:s1},{n:'Chi tiết nghỉ',rows:s2},{n:'Ma trận ngày',rows:s3}])};
ACT.ddpdf=()=>{const m=S.dd.m,rows=sheetRows(),L=canMoney();let T=[0,0,0];
 const tr=rows.map(({k,r,inv})=>{T[0]+=inv;T[1]+=r.lost;T[2]+=r.refund;return`<tr><td>${esc(kcode(k))}</td><td>${esc(k.n)}</td><td>${progShort(k)}</td><td>${r.plan}/${r.planBt}</td><td>${r.cm}</td><td>${r.p}</td><td>${r.kp}</td><td>${r.tt}</td><td>${r.bv}</td><td>${r.bu}</td><td>${r.none}</td>${L?`<td align="right">${fnum(inv)}</td><td align="right">${fnum(r.lost)}</td><td align="right">${fnum(r.refund)}</td>`:''}</tr>`}).join('');
 const html=`<h2 style="margin:0 0 4px;font:700 17px 'Baloo 2','Be Vietnam Pro',sans-serif">BẢNG CHẤM CÔNG HỌC SINH ${mLabel(m).toUpperCase()}</h2><p style="font-size:11px;margin-bottom:8px;color:#6b5f50">KH: số buổi 1-1 / số ngày bán trú theo lịch. P: nghỉ có phép · KP: nghỉ không phép · TT: Trung tâm hoặc giáo viên nghỉ · Viện: nhập viện · Bù: học bù có mặt.${L?' Khoản hoàn trừ vào học phí tháng sau.':''}</p>
 <table><thead><tr><th>Mã</th><th>Họ tên</th><th>Chương trình</th><th>KH</th><th>Có mặt</th><th>P</th><th>KP</th><th>TT</th><th>Viện</th><th>Bù</th><th>Chưa ghi</th>${L?'<th>Học phí</th><th>Phí mất</th><th>Hoàn</th>':''}</tr></thead><tbody>${tr}${L?`<tr><td colspan="11" align="right"><b>Tổng cộng</b></td><td align="right"><b>${fnum(T[0])}</b></td><td align="right"><b>${fnum(T[1])}</b></td><td align="right"><b>${fnum(T[2])}</b></td></tr>`:''}</tbody></table>`;
 exportPDF('bang-cham-cong-hoc-sinh-'+m+'.pdf',html)};
/* --- tab quy định --- */
function ddRule(){if(!canMoney())return'';const c=DB.cfg,R=c.rule,dAll=c.pbtDay||0,dCN=Math.min(c.pbtDay11||0,dAll),rB=dAll-dCN,gp=gvPct();
 const rows=[['Nghỉ có phép (P)','Mất '+R.pLoss+'% phí buổi ('+fmt(c.p11*R.pLoss/100)+'), hoàn '+(100-R.pLoss)+'% ('+fmt(c.p11*(100-R.pLoss)/100)+') trừ vào học phí tháng sau','Hoàn phí ca 1-1 của ngày ('+fmt(dCN)+'), không hoàn phần còn lại ('+fmt(dAll-dCN)+')'],
  ['Nghỉ không phép (KP)','Mất 100% phí buổi ('+fmt(c.p11)+')','Không hoàn ('+fmt(dAll)+' mỗi ngày bán trú)'],
  ['Trung tâm hoặc giáo viên nghỉ (TT/GV)','Học bù nếu hai bên thỏa thuận; gia đình không nhận học bù thì hoàn '+R.ttRefund+'% phí buổi','Trung tâm xếp học bù, không tính phí nghỉ'],
  ['Nhập viện có giấy (bán trú)','Không áp dụng','Hoàn '+R.bvRefund+'% phí bán trú ('+fmt(rB*R.bvRefund/100)+') và '+bv11(R)+'% phí ca 1-1 trong ngày ('+fmt(dCN*bv11(R)/100)+'): '+fmt(rB*R.bvRefund/100+dCN*bv11(R)/100)+' mỗi ngày'],
  ['Học bù có hai bên đồng ý','Không tính phí nghỉ cho buổi được bù','Theo lịch Trung tâm điều chỉnh'],
  ['Bé ngưng can thiệp','Không hoàn khoản nào','Không hoàn khoản nào']];
 return`<div class="card"><h2>Cách hệ thống tính từ bảng chấm công</h2>`+tbl(['Tình huống','Can thiệp 1-1','Bán trú'],rows.map(r=>`<tr><td><b>${r[0]}</b></td><td>${r[1]}</td><td>${r[2]}</td></tr>`).join(''))
 +`<p class="sm mu" style="margin-top:10px">Đơn giá đang áp dụng: 1-1 ${fmt(c.p11)}/buổi; bán trú ${fmt(dAll)}/ngày, trong đó ${fmt(dCN)} là một ca 1-1 (${SLOT_MIN} phút) học trong ngày bán trú. Giá theo loại 1-1 (mỗi giờ): ${LT.map(x=>esc(x.n)+' '+fmt(ltFee(x))).join('; ')}. ${canCfg()?'<button class="btn s" data-a="nsgo">Đổi thông số</button>':'Trưởng Trung tâm có thể đổi thông số trong mục Nhân sự.'}</p></div>`
 +`<div class="card"><h2>Hệ thống đang giả định những điểm sau</h2><ol style="margin:0;padding-left:20px"><li>Bán trú tính theo ngày: số ngày bán trú theo lịch của bé trong tháng nhân với ${fmt(dAll)}. Mỗi bé chọn ngày bán trú riêng (thứ Hai đến thứ Sáu hoặc thứ Hai đến thứ Bảy, hoặc vài ngày).</li><li>Mỗi ngày bán trú gồm một ca 1-1 đã nằm trong ${fmt(dAll)}: trong đó học phí bán trú ${fmt(rB)} và phí 1-1 là ${fmt(dCN)}. Hệ thống lấy ca 1-1 sớm nhất của bé trong ngày đó làm ca trong gói. Ca 1-1 khác trong cùng ngày, và ca 1-1 vào ngày bé không bán trú, tính riêng theo đơn giá buổi.</li><li>Học phí 1-1 của tháng bằng số buổi tính riêng trong lịch cố định của tháng nhân với đơn giá buổi; học phí đóng nguyên tháng. Học phí mỗi buổi 1-1 là ${fmt(c.p11)}. Nếu nghỉ P: phụ huynh mất ${R.pLoss}%, hoàn ${100-R.pLoss}% phí của ca 1-1 đó. Nếu nghỉ KP: phụ huynh mất 100% phí buổi 1-1. Nếu Trung tâm hoặc giáo viên cho nghỉ: phụ huynh được hoàn ${R.ttRefund}% học phí 1-1.</li><li>Quy định ghi “hoàn 50% phí trong tổng số ngày nhập viện”: hệ thống hoàn ${R.bvRefund}% trên phí bán trú của ngày đó (${fmt(rB)}, không gồm ca 1-1). Riêng học phí 1-1 trong ngày bán trú được hoàn ${bv11(R)}% (${fmt(dCN)}).</li><li>Nghỉ P hay KP do giáo viên ghi dựa vào thời điểm phụ huynh báo; hệ thống không tự biết giờ báo. Khi ghi nghỉ cho ngày bán trú, ca 1-1 trong gói của ngày đó được ghi nghỉ theo.</li><li>Mọi khoản hoàn (phí dư) được trừ vào học phí tháng sau và ghi vào công nợ ngày đầu tháng đó. Học phí tháng sau mà phụ huynh phải đóng = học phí tháng sau trừ phí dư của tháng trước. Bé ngưng đột ngột thì không hoàn phí dư nào.</li><li>Học phí tính trước đầu tháng theo lịch đã trừ các ngày nghỉ lễ và ngày Trung tâm cho nghỉ (đặt ở Lịch học hoặc Học phí, tab Ngày nghỉ lễ). Ngày nghỉ không tính học phí, không cần điểm danh; giáo viên theo tháng vẫn hưởng ngày công, giáo viên theo ca không có ca dạy.</li><li>Lương giáo viên 1-1 tính theo ca: bé có mặt hoặc học bù có mặt trả đủ đơn giá ca; bé nghỉ không phép trả ${gp.kp}%; nghỉ có phép trả ${gp.p}%; Trung tâm hoặc giáo viên nghỉ, nhập viện trả ${gp.tt}% và ${gp.bv}%. Giáo viên bán trú nhận lương cố định.</li></ol></div>`
 +`<div class="two"><div class="card">${policyH('m11')}</div><div class="card">${policyH('bt')}</div></div>`}
