 return`<div class="grid">${kpi('Bản nháp',cnt('nhap'),'đang soạn')}${kpi('Chờ duyệt',cnt('cho'),'chờ Trưởng Trung tâm',cnt('cho')&&isLead()?'er':'')}${kpi('Đã duyệt',cnt('duyet'),'chờ gửi phụ huynh')}${kpi('Đã gửi',cnt('gui'),'phụ huynh xem được','ok')}</div>
 <div class="card"><div class="f2" style="margin-bottom:12px"><div><label for="bcq">Tìm theo tên bé</label><input id="bcq" data-i="bcq" value="${esc(b.q)}"></div><div><label for="bcf">Trạng thái</label><select id="bcf" data-c="bcf"><option value="">Tất cả</option>${opts(Object.entries(RPS).map(([k,v])=>[k,v[0]]),b.f)}</select></div><div><label for="bcp">Kỳ báo cáo</label><select id="bcp" data-c="bcp"><option value="">Tất cả</option>${opts([sm(CM,-2),sm(CM,-1),CM].map(x=>[x,mLabel(x)]),b.per)}</select></div></div>`
