function cpLead(){const ps=phGroups(),sent=DB.rp.filter(r=>r.s==='gui'),wait=DB.rp.filter(r=>r.s==='duyet'),acc=CLOUDMODE&&canCfg();
 const pgd=pg('cpl',ps,12);
 return head('Cổng phụ huynh','Theo dõi tài khoản phụ huynh và nội dung đã gửi')
 +`<div class="grid">${kpi('Tài khoản phụ huynh',ps.length,DB.kids.length+' bé')}${kpi('Báo cáo đã gửi',sent.length,'phụ huynh xem được','ok')}${kpi('Chờ gửi',wait.length,'đã duyệt, chưa gửi',wait.length?'er':'')}${kpi('Ảnh, video chia sẻ',medList().filter(m=>m.kind!=='doc'&&medShared(m)).length,'cho phụ huynh')}</div>`
 +(wait.length?`<div class="card"><h2>Báo cáo đã duyệt, chờ gửi</h2>`+wait.map(r=>`<div class="rw"><span><b>${esc(kn(r.hs))}</b> · ${mLabel(r.per)}</span><button class="btn s y" data-a="bcsend" data-v="${r.id}">Gửi phụ huynh</button></div>`).join('')+`</div>`:'')
 +(acc?phBulkHtml():'')
 +`<div class="card"><div class="top"><h2>Tài khoản phụ huynh</h2>${acc?`<div class="acts"><button class="btn p" data-a="phbulk" ${CLD.acc===null||(S.phBulk&&S.phBulk.run)?'disabled':''}>Cấp tài khoản cho phụ huynh chưa có</button></div>`:''}</div>`+tbl(['Phụ huynh','Đăng nhập','Các bé','Báo cáo đã nhận','Thông báo chưa đọc'].concat(acc?['Tài khoản']:[]).concat(['']),pgd.rows.map(p=>{const nr=DB.nt.filter(n=>n.aud==='ph'&&(n.tg==='all'||p.ks.some(k=>k.id===n.tg||k.gr===n.tg))&&!DB.rd[n.id+'|ph|'+p.key]).length;
  return`<tr><td><b>${esc(p.pn)}</b><br><span class="sm mu">${esc(p.pp)}</span></td><td>${esc(p.pe||p.pp||'—')}</td><td>${esc(p.ks.map(k=>k.n).join(', '))}</td><td>${sent.filter(r=>p.ks.some(k=>k.id===r.hs)).length}</td><td>${nr}</td>${acc?`<td>${phTag(p)}</td>`:''}<td>${acc&&p.key?`<button class="btn s" data-a="phopen" data-v="${esc(p.key)}">Tài khoản</button>`:''}${canMoney()&&!CLOUDMODE&&p.key?`<button class="btn s" data-a="viewas" data-v="${esc(p.key)}">Xem như phụ huynh</button>`:''}</td></tr>`}).join(''))+pgd.html+(CLOUDMODE?`<p class="sm mu" style="margin-top:8px">Phụ huynh đăng nhập bằng email hoặc số điện thoại đã ghi trong hồ sơ bé. Các bé cùng email (hoặc cùng số điện thoại) dùng chung một tài khoản.</p>`:canMoney()?`<p class="sm mu" style="margin-top:8px">“Xem như phụ huynh” chuyển bạn sang giao diện của tài khoản đó để kiểm tra. Đổi lại vai trò bằng ô “Xem thử vai trò” ở đầu trang.</p>`:`<p class="sm mu" style="margin-top:8px">Giao diện phụ huynh có phần học phí nên chỉ Trưởng Trung tâm được mở xem như phụ huynh.</p>`)+`</div>`}
ACT.viewas=v=>{if(!canMoney())return false;const a=findAccount(v);if(a)setUser(a)};
