ACT.tbdel=v=>{ask('Xóa thông báo này?',()=>{DB.nt=DB.nt.filter(n=>n.id!==v);toast('Đã xóa thông báo')},'Xóa')};
ACT.tbnew=()=>{S.modal={t:'tbn',aud:isLead()?'ph':'ph'}};
