MODALS.tbn=()=>{const m=S.modal,gs=isGV()?myGroups():DB.groups,ks=isGV()?myKids().filter(k=>k.st==='dang'):[],A=seesAll();
 const tgOpts=m.aud==='nb'?[['all','Toàn bộ nhân viên']]:(A?[['all','Mọi phụ huynh']]:[]).concat(gs.map(g=>[g.id,'Phụ huynh '+g.n])).concat(A?DB.kids.filter(k=>k.st==='dang').map(k=>['k:'+k.id,'Phụ huynh bé '+k.n]):ks.map(k=>['k:'+k.id,'Phụ huynh bé '+k.n]));
 return mdl('Soạn thông báo',`<form id="tbf" class="f"><div class="f2">${A?`<div><label for="tb-a">Gửi cho</label><select id="tb-a" data-c="tba">${opts([['ph','Phụ huynh'],['nb','Nhân viên']],m.aud)}</select></div>`:''}<div><label for="tb-g">Đối tượng cụ thể</label><select id="tb-g" name="tg">${opts(tgOpts,'')}</select></div></div><div><label for="tb-t">Tiêu đề</label><input id="tb-t" name="t" required></div><div><label for="tb-b">Nội dung</label><textarea id="tb-b" name="b" rows="5" required></textarea></div>${A?'<label class="chk"><input type="checkbox" name="pin"> Ghim lên đầu</label>':''}${canMoney()?'<label class="chk"><input type="checkbox" name="fin"> Có nội dung về học phí hoặc lương (Quản lý và Giáo viên sẽ không thấy thông báo này)</label>':''}<div class="acts" style="justify-content:flex-end"><button class="btn" type="button" data-a="mx">Hủy</button><button class="btn p" type="submit">Gửi thông báo</button></div></form>`)};
FORM.tbf=f=>{const e=f.elements,g=e.tg.value;if(!g)return false;
 DB.nt.push({id:'n'+uid(),aud:S.modal.aud,tg:g.startsWith('k:')?g.slice(2):g,t:e.t.value.trim(),b:e.b.value.trim(),by:U.id,at:TODAY,pin:!!(e.pin&&e.pin.checked),fin:canMoney()&&!!(e.fin&&e.fin.checked)});S.modal=null;toast('Đã gửi thông báo')};
