/* điểm danh trong tháng, kèm những giáo viên phụ trách buổi đó (ca 1-1: một người; bán trú: mọi giáo viên của lớp, ngang nhau). Buổi chưa có giáo viên thì bỏ qua. */
function attRows(m){const lich={},out=[];DB.lich.forEach(l=>{lich[l.id]=l});
 for(const key in DB.att){if(!key.startsWith(m))continue;const sid=key.split('|')[1],c=DB.att[key];let gvs;if(sid[0]==='G')gvs=grTs(grBy(sid));else{const l=lich[sid];gvs=l&&l.gv?[l.gv]:[]}
  if(gvs.length)out.push({gvs,c})}
 return out}
/* theo từng giáo viên: một buổi bán trú tính cho mọi giáo viên của lớp */
function attStats(m){const by={};
 attRows(m).forEach(({gvs,c})=>gvs.forEach(gv=>{const o=by[gv]=by[gv]||{t:0,cm:0,p:0,kp:0,tt:0,bv:0};o.t++;o[c]++}));
 return by}
/* tổng toàn trung tâm: mỗi lượt điểm danh tính một lần, không nhân theo số giáo viên của lớp */
const attTot=m=>attRows(m).reduce((a,r)=>({t:a.t+1,cm:a.cm+(r.c==='cm'?1:0)}),{t:0,cm:0});
function tkData(m){const act=DB.kids.filter(k=>k.st==='dang'),as=attStats(m),tot=attTot(m),fs=feeStats(m);
 const prog=[['Chỉ can thiệp 1-1',k=>wk11(k.id)&&!k.bt],['Cả 1-1 và bán trú',k=>wk11(k.id)&&k.bt],['Chỉ bán trú',k=>!wk11(k.id)&&k.bt]].map(([l,f])=>{const ks=act.filter(f);return{l,n:ks.length,due:ks.reduce((s,k)=>s+billed(k.id,m),0),paid:ks.reduce((s,k)=>s+paidM(k.id,m),0)}});
 const tr=DB.staff.filter(s=>isTeacher(s)&&s.st==='dang'&&(s.role==='gv'||teachesNow(s.id))).map(s=>({s,o:as[s.id]||{t:0,cm:0,p:0,kp:0,tt:0,bv:0},ks:act.filter(k=>k.gv===s.id).length}));
 const refund=DB.lg.filter(e=>e.kind==='hoan'&&e.m===m).reduce((s,e)=>s+e.amt,0);
 return{act,tot,fs,prog,tr,refund,rate:tot.t?Math.round(tot.cm*100/tot.t):0}}
VIEWS.tk=()=>{const t=S.tk=Object.assign({m:sm(WD.slice(0,7),0)},S.tk),m=t.m,d=tkData(m),$=canMoney(),pt=d.act.filter(k=>k.bt).length;
 const kps=$?[kpi('Trẻ đang học',d.act.length,DB.kids.length+' hồ sơ'),kpi('Chuyên cần',d.rate+'%',d.tot.t+' lượt đã điểm danh',d.rate>=85?'ok':'er'),kpi('Đã thu',fmt(d.fs.paid),'phải thu '+fmt(d.fs.due)),kpi('Công nợ',fmt(totalDebt()),debtors().length+' gia đình',totalDebt()?'er':'ok'),kpi('Hoàn phí nghỉ',fmt(d.refund),'trừ vào học phí '+mLow(m)),kpi('Nhân sự đang làm',DB.staff.filter(s=>s.st==='dang').length,activeTeachers().length+' giáo viên')]
  :[kpi('Trẻ đang học',d.act.length,DB.kids.length+' hồ sơ'),kpi('Chuyên cần',d.rate+'%',d.tot.t+' lượt đã điểm danh',d.rate>=85?'ok':'er'),kpi('Trẻ có can thiệp 1-1',d.act.filter(k=>wk11(k.id)).length,DB.lich.filter(l=>l.type==='11').length+' buổi mỗi tuần'),kpi('Trẻ bán trú',pt,DB.groups.map(g=>g.n+' '+d.act.filter(k=>k.gr===g.id).length).join(', ')),kpi('Nhân sự đang làm',DB.staff.filter(s=>s.st==='dang').length,activeTeachers().length+' giáo viên'),kpi('Chưa điểm danh',unrecorded(WD),'ngày '+vdm(WD),unrecorded(WD)?'er':'ok')];
 return head('Thống kê','Số liệu tổng hợp theo tháng, xuất Excel hoặc PDF','<button class="btn s" data-a="tkxl">Xuất Excel</button><button class="btn s" data-a="tkpdf">Xuất PDF</button>')
 +`<div class="card"><div class="f2"><div><label for="tkm">Tháng</label><select id="tkm" data-c="tkm">${opts([sm(CM,-2),sm(CM,-1),CM].map(x=>[x,mLabel(x)]),m)}</select></div></div></div>`
 +`<div class="grid g3">${kps.join('')}</div>`
 +`<div class="two">${$?`<div class="card"><h2>Học phí theo chương trình</h2>`+tbl(['Chương trình','>Số trẻ','>Phải thu','>Đã thu'],d.prog.map(p=>`<tr><td>${p.l}</td><td class="r">${p.n}</td><td class="r nw">${fnum(p.due)}</td><td class="r nw">${fnum(p.paid)}</td></tr>`).join(''))+`</div>`:`<div class="card"><h2>Trẻ theo chương trình</h2>`+tbl(['Chương trình','>Số trẻ'],d.prog.map(p=>`<tr><td>${p.l}</td><td class="r">${p.n}</td></tr>`).join(''))+`</div>`}
 <div class="card"><h2>Chuyên cần theo giáo viên</h2>`+tbl(['Giáo viên','>Trẻ 1-1','>Lượt','>Có mặt','>P','>KP','>TT/GV'],d.tr.map(({s,o,ks})=>`<tr><td>${esc(given(s.n))}</td><td class="r">${ks}</td><td class="r">${o.t}</td><td class="r">${o.t?Math.round(o.cm*100/o.t):0}%</td><td class="r">${o.p}</td><td class="r">${o.kp}</td><td class="r">${o.tt}</td></tr>`).join(''))+`</div></div>`
 +`<div class="card"><h2>Nhân sự: công và đi muộn</h2>`+tbl(['Nhân viên','Chức vụ','>Công','>Đi muộn','>Nghỉ phép','>Vắng'],DB.staff.filter(s=>s.st==='dang').map(s=>{const p=payroll(s,m);return`<tr><td>${esc(s.n)}</td><td>${esc(s.pos)}</td><td class="r">${p.cong}</td><td class="r">${p.late}</td><td class="r">${p.leave}</td><td class="r">${p.abs}</td></tr>`}).join(''))+`</div>`};
ACT.tkxl=()=>{const m=S.tk.m,d=tkData(m);
 exportXLSX('thong-ke-'+m+'.xlsx',[{n:'Tổng quan',rows:[['Chỉ số','Giá trị'],['Tháng',mLabel(m)],['Trẻ đang học',d.act.length],['Chuyên cần (%)',d.rate]].concat(canMoney()?[['Phải thu',d.fs.due],['Đã thu',d.fs.paid],['Công nợ hiện tại',totalDebt()],['Hoàn phí nghỉ',d.refund]]:[])},
  {n:'Học sinh',rows:[['Mã','Họ tên','Tuổi','Nhu cầu','Chương trình','Giáo viên','Phụ huynh','Điện thoại','Trạng thái']].concat(DB.kids.map(k=>[kcode(k),k.n,age(k.dob),k.nd,progOf(k),mainGV(k),k.pn,k.pp,KST[k.st]]))},
  {n:'Chuyên cần giáo viên',rows:[['Giáo viên','Trẻ 1-1','Lượt','Có mặt','Nghỉ P','Nghỉ KP','TT/GV nghỉ']].concat(d.tr.map(({s,o,ks})=>[s.n,ks,o.t,o.cm,o.p,o.kp,o.tt]))},
  ...(canMoney()?[{n:'Học phí',rows:[['Mã','Họ tên','Học phí '+m,'Đã thu','Công nợ hiện tại']].concat(d.act.map(k=>[kcode(k),k.n,billed(k.id,m),paidM(k.id,m),balance(k.id)]))}]:[]),
  {n:'Nhân sự',rows:[['Mã','Họ tên','Chức vụ','Công','Đi muộn','Nghỉ phép','Vắng']].concat(DB.staff.filter(s=>s.st==='dang').map(s=>{const p=payroll(s,m);return[s.id,s.n,s.pos,p.cong,p.late,p.leave,p.abs]}))}])};
ACT.tkpdf=()=>{const m=S.tk.m,d=tkData(m),r=(a,b)=>`<tr><td>${a}</td><td align="right">${b}</td></tr>`;
 exportPDF('thong-ke-'+m+'.pdf',`<h2 style="margin:0 0 8px;font:700 17px 'Baloo 2','Be Vietnam Pro',sans-serif">THỐNG KÊ ${mLabel(m).toUpperCase()}</h2><table><tbody>${r('Trẻ đang học',d.act.length)}${r('Chuyên cần',d.rate+'% ('+d.tot.t+' lượt)')}${canMoney()?r('Học phí phải thu',fmt(d.fs.due))+r('Đã thu',fmt(d.fs.paid))+r('Công nợ hiện tại',fmt(totalDebt()))+r('Hoàn phí nghỉ',fmt(d.refund)):''}</tbody></table>${canMoney()?`<h3 style="margin:14px 0 6px">Học phí theo chương trình</h3><table><thead><tr><th>Chương trình</th><th>Số trẻ</th><th>Phải thu</th><th>Đã thu</th></tr></thead><tbody>${d.prog.map(p=>`<tr><td>${p.l}</td><td>${p.n}</td><td align="right">${fnum(p.due)}</td><td align="right">${fnum(p.paid)}</td></tr>`).join('')}</tbody></table>`:`<h3 style="margin:14px 0 6px">Trẻ theo chương trình</h3><table><thead><tr><th>Chương trình</th><th>Số trẻ</th></tr></thead><tbody>${d.prog.map(p=>`<tr><td>${p.l}</td><td>${p.n}</td></tr>`).join('')}</tbody></table>`}<h3 style="margin:14px 0 6px">Chuyên cần theo giáo viên</h3><table><thead><tr><th>Giáo viên</th><th>Lượt</th><th>Có mặt</th><th>P</th><th>KP</th><th>TT/GV</th></tr></thead><tbody>${d.tr.map(({s,o})=>`<tr><td>${esc(s.n)}</td><td>${o.t}</td><td>${o.t?Math.round(o.cm*100/o.t):0}%</td><td>${o.p}</td><td>${o.kp}</td><td>${o.tt}</td></tr>`).join('')}</tbody></table>`)};
/* ===== Biểu đồ tiến bộ: dễ hiểu cho phụ huynh, đầy đủ hơn cho giáo viên ===== */
const r0=Math.round,PDFC={c1:'#047781'};
/* chú giải khi di chuột, chạm hoặc dùng bàn phím */
let TIPEL=null,TIPT=0;
function hideTip(){clearTimeout(TIPT);if(TIPEL){TIPEL.remove();TIPEL=null}}
function showTip(el){hideTip();const t=el.getAttribute('data-tip');if(!t)return;TIPEL=document.createElement('div');TIPEL.className='vtip';TIPEL.setAttribute('role','tooltip');TIPEL.textContent=t;document.body.appendChild(TIPEL);
 const r=el.getBoundingClientRect(),w=TIPEL.offsetWidth,h=TIPEL.offsetHeight;let x=r.left+r.width/2-w/2,y=r.top-h-8;x=Math.max(8,Math.min(innerWidth-w-8,x));if(y<8)y=r.bottom+8;TIPEL.style.left=x+'px';TIPEL.style.top=y+'px'}
document.addEventListener('mouseover',e=>{const t=e.target.closest&&e.target.closest('[data-tip]');if(t)showTip(t);else if(TIPEL)hideTip()});
document.addEventListener('focusin',e=>{const t=e.target.closest&&e.target.closest('[data-tip]');if(t)showTip(t)});
document.addEventListener('focusout',hideTip);
document.addEventListener('click',e=>{const t=e.target.closest&&e.target.closest('[data-tip]');if(t){showTip(t);TIPT=setTimeout(hideTip,3500)}else hideTip()},true);
window.addEventListener('scroll',hideTip,true);

const wkLab=k=>vdm(k),moLab=k=>'Tháng '+(+k.slice(5,7));
const spChip=s=>`<span class="sp sp-${s}">${esc(SUP[s].p)}</span>`;

/* --- số liệu nổi bật --- */
function heroFig(P,par){const has=P.now!=null,d=P.dAll;
 const t=!has?'Chưa có số liệu buổi can thiệp trong khoảng thời gian này.':d==null?'Bé mới bắt đầu luyện nên chưa đủ số liệu để so với đầu kỳ.':`${d>=0?'Tăng':'Giảm'} <b>${Math.abs(r0(d))} điểm</b> so với đầu kỳ, tính trên ${P.np} mục tiêu luyện từ 2 buổi trở lên: ${trendWord(d)}.`;
 return`<div class="hero"><div class="hero-n" role="img" aria-label="Chỉ số tự làm hiện tại ${has?r0(P.now):'chưa có'} trên 100"><span class="hn">${has?r0(P.now):'–'}</span><span class="hu">/100</span></div><div class="hero-t"><b>Chỉ số tự làm</b><p>${t}</p><p class="sm mu" style="margin-top:6px">${par?'Chỉ số cho biết bé làm đúng nhiều hay ít và cần cô giúp nhiều hay ít: 0 là cần giúp hoàn toàn, 100 là bé tự làm đúng hết.':'Chỉ số tự làm = tỉ lệ lượt đúng × hệ số mức hỗ trợ ('+SUPK.map(s=>SUP[s].a+' '+SUP[s].w).join(', ')+'), lấy trung bình trên các mục tiêu.'}</p></div></div>`}
function tiles(k,P){return`<div class="grid">${kpi('Buổi can thiệp',P.ss,'đã ghi trong kỳ')}${kpi('Mục tiêu đang luyện',kidPlans(k.id,'dang').length,P.goals.length+' mục có số liệu')}${kpi('Mục tiêu mới đạt',P.dat.length,'trong kỳ',P.dat.length?'ok':'')}${kpi('Lượt luyện',P.recs,'lượt có kết quả')}</div>`}

/* --- biểu đồ 1: đầu kỳ so với hiện tại theo lĩnh vực --- */
function chDom(P){const act=LDOM.map(dd=>({dd,d:P.doms.find(x=>x.id===dd.id)})).filter(x=>x.d&&x.d.l!=null);
 if(!act.length)return'<p class="mu sm">Chưa có số liệu.</p>';
 const pos=v=>Math.max(0,Math.min(100,v)),
 rows=act.map(({dd,d})=>{const a=d.f,b=d.l,dl=a!=null?b-a:null;
  return`<div class="db-r" role="listitem"><div class="db-l">${esc(dd.s)}<small>${d.n} mục tiêu</small></div><div class="db-t" role="img" aria-label="${esc(dd.n)}: ${a!=null?'đầu kỳ '+r0(a)+', ':''}hiện tại ${r0(b)} trên 100">${a!=null?`<i class="db-ln" style="left:${pos(Math.min(a,b))}%;width:${Math.abs(pos(b)-pos(a))}%"></i><b class="db-p0" tabindex="0" style="left:${pos(a)}%" data-tip="${esc(dd.n+' · Đầu kỳ: '+r0(a)+' điểm')}"></b>`:''}<b class="db-p1" tabindex="0" style="left:${pos(b)}%" data-tip="${esc(dd.n+' · Hiện tại: '+r0(b)+' điểm')}"></b></div><div class="db-v"><b>${r0(b)}</b>${dl==null?' <small class="mu">mới</small>':` <small class="${dl>=2?'up':dl<=-2?'dn':'mu'}">${dl>=0?'+':'−'}${Math.abs(r0(dl))}</small>`}</div></div>`}).join('');
 return`<div class="db" role="list"><div class="db-r db-ax" aria-hidden="true"><span></span><span class="db-tk"><i style="left:0">0</i><i style="left:50%">50</i><i style="left:100%">100</i></span><span></span></div>${rows}</div><div class="lgd"><span><i class="sw sw0"></i>Đầu kỳ</span><span><i class="sw sw1"></i>Hiện tại</span><span class="mu">Chấm càng gần 100, bé càng tự làm được</span></div>`}

/* --- biểu đồ 2: mức hỗ trợ theo thời gian --- */
function chStack(P,bands){if(!P.stack.length)return'<p class="mu sm">Chưa có số liệu.</p>';
 const lv=bands?BANDS.map((b,i)=>({n:b.n,s:b.s,c:'var(--b'+(i+1)+')',t:'var(--bt'+(i+1)+')',h:b.s.map(x=>SUP[x].p).join(', ')})):SUPK.map((s,i)=>({n:SUP[s].n,s:[s],c:'var(--o'+(i+1)+')',t:'var(--ot'+(i+1)+')',h:SUP[s].h}));
 const rows=P.stack.map(r=>{const lab=P.unit==='m'?moLab(r.k):'Tuần '+wkLab(r.k);
  return`<div class="sk-r"><div class="sk-l">${esc(lab)}<small>${r.t} lượt</small></div><div class="sk-b" role="img" aria-label="${esc(lab)}: ${lv.map(L=>{const c=L.s.reduce((a,s)=>a+r.c[s],0);return L.n+' '+r0(c*100/r.t)+'%'}).join(', ')}">${lv.map(L=>{const c=L.s.reduce((a,s)=>a+r.c[s],0),p=c*100/r.t;return c?`<i class="sk-s" tabindex="0" style="flex:${c} 1 0%;background:${L.c};color:${L.t}" data-tip="${esc(lab+' · '+L.n+': '+r0(p)+'% ('+c+' lượt)')}">${p>=14?r0(p)+'%':''}</i>`:''}).join('')}</div></div>`}).join('');
 return`<div class="sk">${rows}</div><div class="lgd">${lv.map(L=>`<span title="${esc(L.h)}"><i class="sw" style="background:${L.c}"></i>${esc(L.n)}</span>`).join('')}</div><p class="sm mu" style="margin-top:6px">Mỗi thanh là 100% lượt luyện của ${P.unit==='m'?'tháng':'tuần'}. Thanh càng nhiều màu đậm bên trái, bé càng cần ít hỗ trợ.</p>`}

/* --- biểu đồ 3: xu hướng theo tuần --- */
function chTrend(P,pdf){const w=P.weeks,n=w.length;if(n<2)return'<p class="mu sm">Cần số liệu của ít nhất 2 tuần để vẽ xu hướng.</p>';
 const X=i=>4+92*i/(n-1),Y=v=>100-v,pts=w.map((p,i)=>[+X(i).toFixed(2),Y(p.sc)]),line='M'+pts.map(p=>p[0]+' '+p[1]).join('L'),area=line+`L${pts[n-1][0]} 100L${pts[0][0]} 100Z`;
 const step=Math.ceil(n/6),col=pdf?PDFC.c1:'var(--c1)',sty=a=>pdf?a:'',attr=(f,s)=>pdf?`fill="${f}" stroke="${s}"`:`style="fill:${f};stroke:${s}"`;
 return`<div class="tr" role="img" aria-label="Chỉ số tự làm theo tuần, từ ${w[0].sc} điểm ở tuần ${wkLab(w[0].w)} đến ${w[n-1].sc} điểm ở tuần ${wkLab(w[n-1].w)}">
 <div class="tr-y" aria-hidden="true">${[0,25,50,75,100].map(v=>`<span style="bottom:${v}%">${v}</span>`).join('')}</div>
 <div class="tr-p">${[0,25,50,75,100].map(v=>`<i class="tgl" style="bottom:${v}%"></i>`).join('')}
 <svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><path d="${area}" ${attr(col,'none')} fill-opacity=".1"/><path d="${line}" ${attr('none',col)} stroke-width="2" vector-effect="non-scaling-stroke" stroke-linejoin="round" stroke-linecap="round"/></svg>
 ${w.map((p,i)=>`<b class="dt" tabindex="0" style="left:${X(i)}%;bottom:${p.sc}%" data-tip="${esc('Tuần '+wkLab(p.w)+': '+p.sc+' điểm ('+p.n+' lượt luyện)')}"></b>`).join('')}
 <span class="dtl" style="left:${X(n-1)}%;bottom:${w[n-1].sc}%">${w[n-1].sc}</span></div>
 <div class="tr-x" aria-hidden="true">${w.map((p,i)=>i%step===0||i===n-1?`<span style="left:${X(i)}%">${wkLab(p.w)}</span>`:'').join('')}</div></div>`}

/* --- mục tiêu nổi bật, gợi ý ở nhà, bảng số liệu --- */
function gcard(kind,x,par){const dm=x.dm||gDom(x.g);
 const tagk={dat:tg('Mới đạt','ok'),top:tg('Tiến bộ nhiều','in'),slow:tg('Cần thêm thời gian','wa')}[kind];
 const body=kind==='dat'?`<p class="sm">${x.dt?'Đạt ngày '+vd(x.dt)+': bé tự làm đúng từ 80% trở lên trong 3 buổi liên tiếp.':''}</p>`
  :`<div class="gc-l">${spChip(x.fs)}<span class="gc-t"><span aria-hidden="true">→</span> ${spChip(x.ls)}</span></div><p class="sm mu">Số lượt đúng: ${x.fk} → ${x.lk}${x.dl!=null?' · '+(x.dl>=0?'+':'−')+Math.abs(r0(x.dl))+' điểm':''}</p>`;
 return`<div class="gc"><div class="gc-h">${tagk} ${domTag(dm)}</div><b>${esc(gName(x.g))}</b>${body}</div>`}
function goalCards(P,par){const c=[],dg=P.dat.map(p=>p.g);P.dat.forEach(p=>c.push(gcard('dat',{g:p.g,dt:p.dt},par)));P.top.filter(x=>!dg.includes(x.g)).slice(0,4).forEach(x=>c.push(gcard('top',x,par)));if(!par)P.slow.forEach(x=>c.push(gcard('slow',x,par)));
 return c.length?`<div class="gc-grid">${c.join('')}</div>`:'<p class="mu sm">Chưa có mục tiêu nổi bật trong khoảng thời gian này. Khi bé có thêm buổi luyện, các mục tiêu mới đạt và tiến bộ nhiều sẽ hiện ở đây.</p>'}
function tipsBox(k,P){const t=homeTips(k.id,P,3);return t.length?`<ul class="tips">${t.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<p class="mu sm">Chưa có gợi ý.</p>'}
function tvDom(P){return`<details class="tvw"><summary class="sm">Xem số liệu dạng bảng</summary>`+tbl(['Lĩnh vực','>Số mục tiêu','>Đầu kỳ','>Hiện tại','>Thay đổi'],LDOM.map(dd=>{const d=P.doms.find(x=>x.id===dd.id);return`<tr><td>${esc(dd.n)}</td><td class="r">${d.n}</td><td class="r">${d.f==null?'–':r0(d.f)}</td><td class="r">${d.l==null?'–':r0(d.l)}</td><td class="r">${d.f==null||d.l==null?'–':(d.l-d.f>=0?'+':'−')+Math.abs(r0(d.l-d.f))}</td></tr>`}).join(''))+`</details>`}
function tvStack(P){return`<details class="tvw"><summary class="sm">Xem số liệu dạng bảng</summary>`+tbl(['Kỳ',...SUPK.map(s=>'>'+SUP[s].a),'>Tổng lượt'],P.stack.map(r=>`<tr><td>${esc(P.unit==='m'?moLab(r.k):'Tuần '+wkLab(r.k))}</td>${SUPK.map(s=>`<td class="r">${r.c[s]}</td>`).join('')}<td class="r">${r.t}</td></tr>`).join(''))+`</details>`}
function tvTrend(P){return`<details class="tvw"><summary class="sm">Xem số liệu dạng bảng</summary>`+tbl(['Tuần bắt đầu','>Chỉ số tự làm','>Số lượt'],P.weeks.map(w=>`<tr><td>${vd(w.w)}</td><td class="r">${w.sc}</td><td class="r">${w.n}</td></tr>`).join(''))+`</details>`}
function goalTable(P){return tbl(['Mục tiêu','Lĩnh vực','Đầu kỳ','Hiện tại','>Số buổi','>Thay đổi'],P.goals.sort((a,b)=>a.dm<b.dm?-1:a.dm>b.dm?1:b.cnt-a.cnt).map(x=>`<tr><td>${esc(gName(x.g))}</td><td>${domTag(x.dm)}</td><td>${spChip(x.fs)} <span class="sm">${x.fk}</span></td><td>${spChip(x.ls)} <span class="sm">${x.lk}</span></td><td class="r">${x.cnt}</td><td class="r">${x.dl==null?'–':(x.dl>=0?'+':'−')+Math.abs(r0(x.dl))}</td></tr>`).join(''),'Chưa có mục tiêu nào có số liệu trong kỳ.')}
const readHelp=par=>`<details class="tvw"><summary class="sm"><b>Cách đọc các biểu đồ</b></summary><div class="sm" style="padding-top:6px"><p><b>Chỉ số tự làm (0 đến 100):</b> kết hợp hai điều, bé làm đúng bao nhiêu trong 10 lượt và cần cô hỗ trợ nhiều hay ít.</p><ul class="rd">${SUPK.map(s=>`<li>${spChip(s)} ${esc(SUP[s].h)}</li>`).join('')}</ul><p style="margin-top:6px">${par?'Bé càng tự làm, thanh màu đậm bên trái càng dài và chỉ số càng gần 100.':'Mục tiêu được đánh dấu đạt khi bé làm độc lập từ 80% trở lên trong 3 buổi liên tiếp.'} Đầu kỳ và hiện tại được so sánh trên cùng các mục tiêu đã luyện từ 2 buổi trở lên.</p></div></details>`;

/* --- trang Tiến bộ (cổng phụ huynh và hồ sơ bé) --- */
ACT.prp=v=>{S.pr=Object.assign({p:'90'},S.pr,{p:v})};
function periodChips(st){return`<div class="chips" role="group" aria-label="Khoảng thời gian" style="margin-bottom:12px">${PRD.map(([v,l])=>`<button type="button" class="chip ${st.p===v?'on':''}" data-a="prp" data-v="${v}" aria-pressed="${st.p===v}">${l}</button>`).join('')}</div>`}
const gtCard=(k,par)=>`<div class="card gt-card"><h2>${par?'Mục tiêu của bé: bé đã đạt chưa?':'Cây mục tiêu của bé'}</h2>${par?'':'<p class="sm mu" style="margin:-4px 0 10px">Tính đến hôm nay, không phụ thuộc khoảng thời gian chọn bên dưới.</p>'}${gtParent(k.id)}</div>`;
function progView(k,o){o=o||{};const par=!!o.parent,st=S.pr=Object.assign({p:'90'},S.pr),R=prRange(st.p),P=progData(k.id,R.from,R.to);
 if(!P.ss)return gtCard(k,par)+periodChips(st)+`<div class="card"><p class="empty">${par?'Chưa có buổi can thiệp nào được ghi trong khoảng thời gian này. Khi giáo viên ghi buổi học, biểu đồ tiến bộ của bé sẽ hiện ở đây.':'Chưa có buổi can thiệp nào được ghi trong khoảng thời gian này.'}</p></div>`;
 const recent=sessOf(k.id,R.from,R.to).filter(s=>s.note).slice(-3).reverse();
 return gtCard(k,par)+periodChips(st)+`<p class="mu sm" style="margin:-4px 0 12px">Từ ${vd(R.from)} đến ${vd(R.to)}${par?'':' · '+esc(k.n)}</p>`
 +`<div class="card">${heroFig(P,par)}</div>`+tiles(k,P)
 +`<div class="card"><h2>${par?'Bé tiến bộ ở lĩnh vực nào?':'Tiến bộ theo lĩnh vực'}</h2>${chDom(P)}${par?'':tvDom(P)}</div>`
 +`<div class="card"><h2>${par?'Bé cần cô hỗ trợ ít dần':'Mức hỗ trợ theo '+(P.unit==='m'?'tháng':'tuần')}</h2>${chStack(P,par)}${par?'':tvStack(P)}</div>`
 +`<div class="card"><h2>Xu hướng chỉ số tự làm theo tuần</h2>${chTrend(P)}${par?'':tvTrend(P)}</div>`
 +`<div class="card"><h2>${par?'Điểm nổi bật của bé':'Mục tiêu nổi bật'}</h2>${goalCards(P,par)}</div>`
 +(par?'':`<div class="card"><h2>Chi tiết theo mục tiêu</h2>${goalTable(P)}</div>`)
 +`<div class="card"><h2>Gợi ý luyện tập tại nhà</h2>${tipsBox(k,P)}${recent.length?`<h3 style="margin-top:12px">Nhận xét gần đây của giáo viên</h3>${recent.map(s=>`<div class="rw"><span><b>${vd(s.date)}</b> · ${esc(s.note)}</span></div>`).join('')}`:''}</div>`
 +`<div class="card">${readHelp(par)}<div class="acts" style="margin-top:12px"><button class="btn p" data-a="prpdf" data-v="${k.id}">Tải báo cáo tiến bộ (PDF)</button></div></div>`}
/* bản gọn cho trang Tổng quan của phụ huynh */
function progMini(k){const R=prRange('90'),P=progData(k.id,R.from,R.to),gt=gtParent(k.id,{mini:1});
 if(!P.ss)return(/class="empty"/.test(gt)?'':gt)+'<p class="empty">Chưa có số liệu buổi can thiệp. Khi giáo viên ghi buổi học, biểu đồ sẽ hiện ở đây.</p>';
 return(/class="empty"/.test(gt)?'':'<h3 style="margin:0 0 8px">Bé đã đạt mục tiêu chưa?</h3>'+gt+'<h3 style="margin:18px 0 8px">Chỉ số tự làm của bé</h3>')+heroFig(P,true)+`<h3 style="margin:14px 0 8px">Bé tiến bộ ở lĩnh vực nào?</h3>`+chDom(P)+`<div class="acts" style="margin-top:12px"><button class="btn p" data-a="cptab" data-v="tb">Xem đầy đủ tiến bộ của bé</button></div>`}
/* khối biểu đồ đưa vào báo cáo chuyên môn hằng tháng và tệp PDF (mỗi khối .nb không bị cắt giữa hai trang PDF) */
function progBlocks(P,T,k,pdf,o){const nb=(t,h)=>`<div class="nb"><h4>${t}</h4>${h}</div>`,rg=`từ ${vd(T.from)} đến ${vd(T.to)}`;
 return(o&&o.tree?nb('Mục tiêu của bé: bé đã đạt chưa?',gtParent(k.id,{pdf:pdf})):'')+`<div class="nb">${heroFig(P,true)}</div>`
  +nb('Tiến bộ theo lĩnh vực'+(o&&o.m?' trong tháng':''),chDom(P))
  +nb('Bé cần cô hỗ trợ ít dần <span class="mu">('+rg+')</span>',chStack(T,true))
  +nb('Xu hướng chỉ số tự làm theo tuần <span class="mu">('+rg+')</span>',chTrend(T,pdf))
  +nb('Điểm nổi bật',goalCards(P,true))
  +(o&&o.tips?nb('Gợi ý luyện tập tại nhà',tipsBox(k,P)):'')}
function progReport(k,per,pdf){const from=per+'-01',to=mDates(per).slice(-1)[0],P=progData(k.id,from,to);
 if(!P.ss)return'';
 return`<div class="prg"><h3 style="margin-top:14px">Biểu đồ tiến bộ của bé trong ${mLow(per)}</h3>${progBlocks(P,progData(k.id,addD(from,-60),to),k,pdf,{m:1})}</div>`}
ACT.prpdf=v=>{const k=kidBy(v);if(!k||!canKid(k.id))return false;const st=S.pr||{p:'90'},R=prRange(st.p),P=progData(k.id,R.from,R.to);
 const html=`<h2 style="margin:0 0 4px;font:700 17px 'Baloo 2','Be Vietnam Pro',sans-serif">BÁO CÁO TIẾN BỘ CỦA BÉ</h2><p style="margin-bottom:8px"><b>${esc(k.n)}</b> · ${age(k.dob)} · Từ ${vd(R.from)} đến ${vd(R.to)}</p><div class="prg">${P.ss?progBlocks(P,P,k,true,{tips:1,tree:1}):'<p>Chưa có buổi can thiệp nào được ghi trong khoảng thời gian này.</p>'}</div>`;
 exportPDF('tien-bo-'+ascii(k.n)+'-'+R.to+'.pdf',html);return false};
/* ===== 16. Thực đơn bán trú (lớp Ong non và Ong mật) ===== */
/* DB.menu[ngày] = {s: bữa sáng, t: bữa trưa, x: bữa xế, n: ghi chú}. Quản lý, Trưởng Trung tâm và Văn phòng sửa; giáo viên và phụ huynh chỉ xem. */
const MENU_S=['Cháo thịt bằm rau củ','Phở gà','Bánh mì trứng ốp la, sữa tươi','Xôi gà xé, sữa chua','Bún thịt bò viên','Cháo cá hồi, bông cải xanh','Mì Quảng gà'];
const MENU_T=['Cơm, cá hồi áp chảo, canh bí đỏ nấu thịt, rau cải luộc','Cơm, thịt kho trứng cút, canh rau ngót','Cơm, gà kho gừng, canh bầu nấu tôm','Cơm, thịt heo xào đậu que, canh bí xanh','Cơm, cá basa sốt cà chua, canh chua rau muống','Cơm, trứng chiên thịt bằm, canh mồng tơi','Cơm, sườn non rim, canh khoai tây cà rốt'];
const MENU_X=['Sữa chua, trái cây theo mùa','Bánh flan','Chè đậu xanh','Bánh bao nhân thịt','Sữa tươi, bánh quy','Sinh tố chuối','Cháo đậu xanh'];
const menuEdit=()=>isLead()||isVP();
const bday=d=>{while(dow(d)===0)d=addD(d,1);return d};   /* thực đơn T2–T7: chủ nhật chuyển sang thứ Hai */
const menuDay=()=>bday(TODAY);
const menuDayLb=()=>'· '+DAYN[dow(menuDay())]+' '+vdm(menuDay())+(menuDay()===TODAY?' (hôm nay)':'');
function seedMenu(D){D.menu=D.menu||{};const w0=monOf(menuDay());let c=0;
 for(const w of[-1,0,1])for(let i=0;i<6;i++){const d=addD(w0,7*w+i);D.menu[d]={s:MENU_S[c%7],t:MENU_T[(c*2+1)%7],x:MENU_X[(c*3+2)%7],n:''};c++}}
const menuMini=d=>{const m=DB.menu[d];if(!m)return'<p class="empty">Chưa có thực đơn ngày này.</p>';
 return[['Bữa sáng',m.s],['Bữa trưa',m.t],['Bữa xế',m.x]].filter(x=>x[1]).map(([l,v])=>`<div class="rw" style="align-items:flex-start;flex-wrap:nowrap"><span class="mu sm" style="width:68px;flex:none">${l}</span><span style="flex:1;min-width:0">${esc(v)}</span></div>`).join('')+(m.n?`<p class="sm mu" style="margin-top:6px">${esc(m.n)}</p>`:'')};
VIEWS.tn=()=>{const t=S.tn=Object.assign({wk:monOf(menuDay())},S.tn),mon=t.wk,days=[0,1,2,3,4,5].map(i=>addD(mon,i)),E=menuEdit(),mine=isPH()?myKids().filter(k=>k.st==='dang'&&k.gr):[],cls=DB.groups.map(g=>esc(g.n)).join(' và ');
 return head('Thực đơn bán trú','Lớp '+cls+' · '+BTLB+', thứ Hai đến thứ Bảy',E?'<button class="btn s" data-a="tncopy">Sao chép từ tuần trước</button>':'')
 +(isPH()?`<div class="note sm" style="margin-bottom:12px">${mine.length?mine.map(k=>esc(given(k.n))+' học lớp '+esc((grBy(k.gr)||{}).n||'')).join('; ')+'. Thực đơn áp dụng chung cho hai lớp bán trú.':'Bé chưa đăng ký bán trú. Thực đơn dưới đây là của hai lớp bán trú '+cls+'.'}</div>`:'')
 +`<div class="card"><div class="acts" style="justify-content:space-between;margin-bottom:10px"><div class="acts"><button class="btn s" data-a="tnwk" data-v="-7">Tuần trước</button><button class="btn s" data-a="tnwk" data-v="0">Tuần này</button><button class="btn s" data-a="tnwk" data-v="7">Tuần sau</button></div><b>${vd(days[0])} đến ${vd(days[5])}</b></div>
 <div class="menu">${days.map(d=>`<div class="mday ${d===TODAY?'now':''}"><div class="mh"><b>${DAYN[dow(d)]}</b> <span class="mu sm">${vdm(d)}</span>${d===TODAY?' '+tg('Hôm nay','y'):''}</div>${menuMini(d)}${E?`<div class="acts" style="margin-top:8px"><button class="btn s" data-a="tnedit" data-v="${d}">${DB.menu[d]?'Sửa':'Thêm thực đơn'}</button></div>`:''}</div>`).join('')}</div>
 ${E?'<p class="sm mu" style="margin-top:10px">Thực đơn được phụ huynh và giáo viên xem theo từng tuần. Bấm “Sửa” ở từng ngày để nhập bữa sáng, trưa, xế.</p>':''}</div>`};
ACT.tnwk=v=>{S.tn.wk=v==='0'?monOf(menuDay()):addD(S.tn.wk,+v)};
ACT.tnedit=v=>{if(!menuEdit())return false;S.modal={t:'tnd',d:v}};
MODALS.tnd=()=>{const d=S.modal.d,m=DB.menu[d]||{s:'',t:'',x:'',n:''},f=(id,l,v)=>`<div><label for="tn-${id}">${l}</label><input id="tn-${id}" name="${id}" value="${esc(v)}" maxlength="200"></div>`;
 return mdl('Thực đơn '+DAYN[dow(d)]+' '+vd(d),`<form id="tndf" class="f">${f('s','Bữa sáng',m.s)}${f('t','Bữa trưa',m.t)}${f('x','Bữa xế',m.x)}${f('n','Ghi chú (không bắt buộc)',m.n)}<div class="acts" style="justify-content:space-between"><span>${DB.menu[d]?`<button class="btn no" type="button" data-a="tnclr" data-v="${d}">Xóa thực đơn ngày này</button>`:''}</span><span class="acts"><button class="btn" type="button" data-a="mx">Hủy</button><button class="btn p" type="submit">Lưu</button></span></div></form>`)};
FORM.tndf=f=>{if(!menuEdit())return false;const e=f.elements,d=S.modal.d,v={s:e.s.value.trim(),t:e.t.value.trim(),x:e.x.value.trim(),n:e.n.value.trim()};
 if(!v.s&&!v.t&&!v.x&&!v.n)delete DB.menu[d];else DB.menu[d]=v;S.modal=null;toast('Đã lưu thực đơn '+vdm(d))};
ACT.tnclr=v=>{if(!menuEdit())return false;ask('Xóa thực đơn ngày '+vdm(v)+'?',()=>{delete DB.menu[v];toast('Đã xóa thực đơn')},'Xóa')};
ACT.tncopy=()=>{if(!menuEdit())return false;const mon=S.tn.wk,prev=addD(mon,-7);let n=0,has=0;
 for(let i=0;i<6;i++){const a=addD(prev,i),b=addD(mon,i);if(DB.menu[a]){has++;if(!DB.menu[b]){DB.menu[b]=Object.assign({},DB.menu[a]);n++}}}
 toast(!has?'Tuần trước chưa có thực đơn để sao chép':n?'Đã sao chép '+n+' ngày, ngày đã có thực đơn được giữ nguyên':'Các ngày của tuần này đã có thực đơn')};
/* ===== 22. Ngày nghỉ lễ, Trung tâm cho nghỉ, học phí trả trước và phí dư ===== */
/* Học phí đóng trước đầu tháng nên Trung tâm đặt sẵn các ngày nghỉ. Ngày nghỉ không tính học phí bán trú, ca 1-1 và không cần điểm danh
   (xem sched, dayList, conflict, tsSt, payroll trong p04-domain.js). Học phí tháng sau của phụ huynh = học phí tháng sau trừ phí dư của tháng trước. */
const canHol=()=>isLead()||isVP();
const holList=()=>(DB.hol||[]).slice().sort((a,b)=>a.d<b.d?-1:a.d>b.d?1:0);
const holTag=h=>tg(HOLK[h.k]||HOLK.le,h.k==='tt'?'wa':'in');

/* Ảnh hưởng của một ngày nghỉ: bao nhiêu bé bán trú, buổi 1-1 tính riêng, lượt điểm danh đã ghi, và số tiền học phí giảm */
function holImpact(d){const w=dow(d),r={bt:0,s11:0,money:0,att:0,bu:0};if(w===0)return r;
 DB.kids.forEach(k=>{if(k.st!=='dang'||k.sd.slice(0,7)>d.slice(0,7))return;
  if(btHas(k,w)){r.bt++;r.money+=DB.cfg.pbtDay||0}
  const inc=incIdW(k,w);
  DB.lich.forEach(l=>{if(l.type==='11'&&l.hs===k.id&&l.day===w&&l.id!==inc){r.s11++;r.money+=feeSlot(k,l.id)}})});
 r.bu=DB.lich.filter(l=>l.type==='bu'&&l.date===d).length;
 r.att=Object.keys(DB.att).filter(key=>key.startsWith(d+'|')).length;
 return r}
const holMonthsBilled=ds=>[...new Set(ds.map(d=>d.slice(0,7)))].filter(m=>DB.lg.some(e=>e.kind==='hp'&&e.m===m));

CHG.holall=(v,t)=>{S.hol=Object.assign({},S.hol,{all:t.checked});S.pg.hol=1};
function holTab(){const h=S.hol=Object.assign({all:false},S.hol),ed=canHol(),L=canMoney(),all=holList();
 const rows=all.filter(x=>h.all||x.d>=TODAY),p=pg('hol',rows,12),up=all.filter(x=>x.d>=TODAY&&dow(x.d)!==0).length;
 const yr=+TODAY.slice(0,4);
 const list=`<div class="card"><div class="top"><div><h2>Ngày nghỉ lễ và Trung tâm cho nghỉ</h2><p class="mu sm">Học phí đóng trước đầu tháng, nên hãy đặt các ngày nghỉ trước khi tạo hóa đơn. Những ngày này không tính học phí bán trú và ca 1-1, không cần điểm danh, giáo viên theo tháng vẫn hưởng ngày công, giáo viên theo ca không có ca dạy.</p></div>
  <label class="chk" style="margin:0"><input type="checkbox" data-c="holall" ${h.all?'checked':''}> Hiện cả ngày đã qua</label></div>
  <div class="grid" style="margin:12px 0">${kpi('Ngày nghỉ sắp tới',up,'từ hôm nay trở đi')}${kpi('Tháng này',holIn(CM).length,mLabel(CM))}${kpi('Tháng sau',holIn(sm(CM,1)).length,mLabel(sm(CM,1)))}</div>`
  +tbl(['Ngày','Tên ngày nghỉ','Loại','Ảnh hưởng'].concat(L?['>Học phí giảm']:[]).concat(ed?['']:[]),p.rows.map(x=>{const im=holImpact(x.d);
   return`<tr><td class="nw"><b>${DAYN[dow(x.d)]}</b> ${vd(x.d)}</td><td>${esc(x.n)}</td><td>${holTag(x)}</td><td class="sm">${dow(x.d)===0?'Chủ nhật vốn nghỉ':im.bt+' bé bán trú, '+im.s11+' buổi 1-1 tính riêng'+(im.att?'<br><span class="mu">Đã có '+im.att+' lượt điểm danh ngày này, sẽ không còn được tính</span>':'')}</td>${L?`<td class="r nw">${im.money?'-'+fnum(im.money):'–'}</td>`:''}${ed?`<td class="r"><button class="btn s no" data-a="holdel" data-v="${x.id}">Xóa</button></td>`:''}</tr>`}).join(''),h.all?'Chưa có ngày nghỉ nào.':'Chưa có ngày nghỉ sắp tới. Hãy thêm các ngày nghỉ lễ, Tết và ngày Trung tâm cho nghỉ.')+p.html
  +`<p class="sm mu" style="margin-top:8px">Chủ nhật Trung tâm luôn nghỉ nên không cần nhập. Sau khi hóa đơn của tháng đã tạo, hóa đơn không tự đổi theo ngày nghỉ thêm vào sau; hãy đối chiếu ở mục Học phí, tab Tạo hóa đơn.</p></div>`;
 const form=ed?`<div class="card"><h2>Thêm ngày nghỉ</h2><form id="holf" class="f"><div class="f2"><div><label for="hl-a">Từ ngày</label><input id="hl-a" name="from" type="date" required></div><div><label for="hl-b">Đến ngày (bỏ trống nếu chỉ một ngày)</label><input id="hl-b" name="to" type="date"></div><div><label for="hl-n">Tên ngày nghỉ</label><input id="hl-n" name="n" placeholder="Ví dụ: Tết Nguyên đán, Giỗ Tổ Hùng Vương" required></div><div><label for="hl-k">Loại</label><select id="hl-k" name="k">${opts(Object.entries(HOLK),'le')}</select></div></div>
  <div class="acts" style="justify-content:flex-end"><button class="btn p" type="submit">Thêm ngày nghỉ</button></div></form>
  <div class="note sm" style="margin-top:12px"><b>Ngày lễ dương lịch cố định</b> (1/1, 30/4, 1/5, 2/9): <button class="btn s" data-a="holsol" data-v="${yr}">Thêm năm ${yr}</button> <button class="btn s" data-a="holsol" data-v="${yr+1}">Thêm năm ${yr+1}</button><br>Tết Nguyên đán và Giỗ Tổ Hùng Vương tính theo âm lịch và mỗi năm lệch ngày dương lịch, nên hãy nhập thủ công theo thông báo nghỉ chính thức.</div></div>`:'';
 return list+form}

/* thêm một danh sách ngày (đã lọc), cảnh báo nếu tháng đó đã tạo hóa đơn */
function holAdd(ds,n,k){const ex=new Set((DB.hol||[]).map(x=>x.d));let c=0;DB.hol=DB.hol||[];
 ds.forEach(d=>{if(ex.has(d)||dow(d)===0)return;DB.hol.push({id:'hl'+uid(),d,n,k});c++});
 const mb=holMonthsBilled(ds);
 toast(c?'Đã thêm '+c+' ngày nghỉ'+(mb.length?'. Hóa đơn '+mb.map(m=>m.slice(5)+'/'+m.slice(0,4)).join(', ')+' đã tạo trước đó, hãy đối chiếu ở mục Học phí':''):'Các ngày này đã có trong danh sách');return c}
FORM.holf=f=>{if(!canHol())return false;const e=f.elements,a=e.from.value,b=e.to.value||a,n=e.n.value.trim(),k=HOLK[e.k.value]?e.k.value:'le';
 if(!a||!n){toast('Hãy chọn ngày và nhập tên ngày nghỉ');return false}
 if(b<a){toast('Ngày kết thúc phải cùng ngày hoặc sau ngày bắt đầu');return false}
 const ds=[];for(let d=a;d<=b&&ds.length<=40;d=addD(d,1))if(dow(d)!==0)ds.push(d);
 if(ds.length>40){toast('Mỗi lần chỉ thêm tối đa 40 ngày liên tiếp');return false}
 const fresh=ds.filter(d=>!isClosed(d));if(!fresh.length){toast('Các ngày này đã có trong danh sách');return false}
 const wa=fresh.filter(d=>holImpact(d).att>0);
 if(wa.length){ask('Đã có điểm danh ở '+wa.length+' ngày ('+wa.slice(0,4).map(vdm).join(', ')+(wa.length>4?'...':'')+'). Nếu đặt các ngày này là ngày nghỉ thì các lượt điểm danh đó không còn được tính vào học phí và lương. Tiếp tục?',()=>{holAdd(fresh,n,k)},'Vẫn thêm');return}
 holAdd(fresh,n,k);f.reset()};
ACT.holsol=v=>{if(!canHol())return false;const y=String(+v||TODAY.slice(0,4));
 const fixed=[['01-01','Tết Dương lịch'],['04-30','Ngày Giải phóng miền Nam'],['05-01','Ngày Quốc tế Lao động'],['09-02','Quốc khánh']];
 let c=0;fixed.forEach(([md,n])=>{c+=holAdd([y+'-'+md],n,'le')});toast(c?'Đã thêm '+c+' ngày lễ dương lịch năm '+y:'Các ngày lễ dương lịch năm '+y+' đã có trong danh sách')};
ACT.holdel=v=>{if(!canHol())return false;const x=(DB.hol||[]).find(y=>y.id===v);if(!x)return;
 const mb=holMonthsBilled([x.d]);
 ask('Xóa ngày nghỉ “'+x.n+'” ('+vd(x.d)+')? Ngày này sẽ được tính lại là ngày học bình thường.'+(mb.length?' Hóa đơn tháng '+x.d.slice(5,7)+'/'+x.d.slice(0,4)+' đã tạo trước đó nên không tự đổi.':''),()=>{DB.hol=DB.hol.filter(y=>y.id!==v);toast('Đã xóa ngày nghỉ')},'Xóa ngày nghỉ')};

/* các ngày nghỉ sắp tới, dùng cho phụ huynh và nhân viên xem nhanh */
function holUpcoming(days){const to=addD(TODAY,days||90);return holList().filter(x=>x.d>=TODAY&&x.d<=to&&dow(x.d)!==0)}
function holCard(days){const xs=holUpcoming(days);
 return`<div class="card"><h2>Ngày Trung tâm nghỉ</h2>${xs.length?xs.map(x=>`<div class="rw"><span><b>${DAYN[dow(x.d)]} ${vd(x.d)}</b> · ${esc(x.n)}</span>${holTag(x)}</div>`).join(''):'<p class="empty">Chưa có ngày nghỉ nào trong thời gian tới.</p>'}<p class="sm mu" style="margin-top:8px">Những ngày này Trung tâm không đón bé và không tính học phí.</p></div>`}

/* --- Học phí trả trước: học phí tháng m, trừ phí dư của tháng trước --- */
/* Phí dư của tháng trước (khoản hoàn do bé nghỉ có phép, Trung tâm nghỉ, nhập viện): lấy khoản đã ghi vào công nợ tháng m, chưa ghi thì tính tạm từ điểm danh.
   Bé đã ngưng can thiệp thì không có phí dư (settle trả hoàn 0). */
function surplusPrev(k,m){const posted=DB.lg.filter(e=>e.hs===k.id&&e.kind==='hoan'&&e.m===m);
 if(posted.length)return{amt:posted.reduce((s,e)=>s+e.amt,0),posted:true};
 if(k.st!=='dang')return{amt:0,posted:false};
 return{amt:settle(k,sm(m,-1)).refund,posted:false}}
function feeBreak(k,m){const xs=sched(k,m),gross=invoice(k,m),sp=surplusPrev(k,m),st=DB.lg.filter(e=>e.hs===k.id&&e.kind==='hp'&&e.m===m);
 return{bt:xs.filter(x=>x.kind==='bt').length,s11:xs.filter(x=>x.kind==='11'&&!x.inc).length,gross,sur:sp.amt,posted:sp.posted,due:Math.max(0,gross-sp.amt),closed:holIn(m),
  has:st.length>0,stored:st.reduce((s,e)=>s+e.amt,0)}}
/* thẻ học phí tháng sau cho phụ huynh: học phí theo lịch, trừ phí dư tháng trước, số phải đóng */
function feeNextCard(k){const nm=sm(CM,1),f=feeBreak(k,nm),pm=CM;
 if(k.st==='nghi')return`<div class="card"><h2>Bé đã ngưng can thiệp</h2><p class="sm mu">Khi bé ngưng đột ngột, học phí đã đóng và phí dư không được hoàn lại. Nếu cần hỗ trợ, phụ huynh liên hệ Trung tâm.</p></div>`;
 if(k.st!=='dang'||!f.gross)return'';
 const row=(l,v,c)=>`<div class="rw"><span>${l}</span><b class="${c||''}" style="font-size:1.1em">${v}</b></div>`;
 return`<div class="card"><h2>Học phí ${mLow(nm)} (dự kiến)</h2>
  ${row('Học phí theo lịch của bé',fmt(f.gross))}
  <p class="sm mu" style="margin:-2px 0 6px">${f.bt?f.bt+' ngày bán trú':''}${f.bt&&f.s11?', ':''}${f.s11?f.s11+' buổi 1-1 tính riêng':''}${f.closed.length?'. Đã trừ '+f.closed.length+' ngày Trung tâm nghỉ: '+f.closed.map(x=>vdm(x.d)+' '+esc(x.n)).join(', '):''}.</p>
  ${row('Trừ phí dư '+mLow(pm)+(f.posted?'':' (tạm tính)'),f.sur?'-'+fmt(f.sur):fmt(0),f.sur?'ok':'')}
  ${row('Phải đóng',fmt(f.due),'ok')}
  <p class="sm mu" style="margin-top:6px">Học phí đóng trước đầu tháng. Phí dư là khoản hoàn do bé nghỉ có phép, Trung tâm nghỉ hoặc nhập viện có giấy. Số tạm tính có thể đổi nếu còn buổi chưa điểm danh.</p></div>`}
/* ===== Khóa cổng phụ huynh khi quá hạn học phí (sau ngày 10 hàng tháng) =====
   Bản chạy thật tính khóa ở máy chủ (api/_lock.js, api/parent.js); đây là bản tương đương cho chế độ ?demo và phần giao diện.
   Quy tắc phải khớp api/_lock.js: học phí tháng M trả trước, hạn hết ngày 10 của tháng M.
   Từ ngày 11 phải đã đóng đủ các tháng đến M; từ ngày 1 đến 10 chỉ cần đủ các tháng đến M-1.
   Khoản đã thu, giảm giá, hoàn phí, nhận chuyển phí trừ lần lượt vào tháng cũ nhất, gộp mọi bé của cùng phụ huynh. */
const LKS={hp:1,cfo:1,thu:-1,gg:-1,hoan:-1,cfi:-1},LK_MIN=1000,LK_MAX_DAYS=93;
const lkDue=t=>+t.slice(8,10)>10?t.slice(0,7):sm(t.slice(0,7),-1);
const lkNext10=t=>(+t.slice(8,10)<=10?t.slice(0,7):sm(t.slice(0,7),1))+'-10';
function lkCalc(entries,today,pul){
 const due=lkDue(today),ch={};let credit=0;
 (entries||[]).forEach(e=>{const s=LKS[e.kind],a=+e.amt;if(!s||!(a>0))return;
  if(s<0){credit+=a;return}
  const m=/^\d{4}-\d{2}$/.test(e.m||'')?e.m:String(e.date||'').slice(0,7);if(/^\d{4}-\d{2}$/.test(m))ch[m]=(ch[m]||0)+a});
 let amt=0;const months=[];
 Object.keys(ch).sort().forEach(m=>{const take=Math.min(credit,ch[m]);credit-=take;const rem=ch[m]-take;if(rem>0&&m<=due){amt+=rem;months.push(m)}});
 const over=amt>=LK_MIN,un=!!(pul&&/^\d{4}-\d{2}-\d{2}$/.test(String(pul.until||''))&&pul.until>=today);
 return{locked:over&&!un,overdue:over,unlocked:over&&un,amt:over?amt:0,months:over?months:[],due,until:over&&un?pul.until:'',by:(pul&&pul.by)||'',at:(pul&&pul.at)||'',note:(pul&&pul.note)||''}}

/* chế độ ?demo: tính từ sổ học phí trong trình duyệt */
function phLockOf(key){
 const ids=DB.kids.filter(k=>pkeyOf(k)===key).map(k=>k.id);
 return Object.assign(lkCalc(DB.lg.filter(e=>ids.includes(e.hs)),TODAY,(DB.pul||{})[key]),{today:TODAY,tel:DB.cfg.tel||'',name:DB.cfg.name||''})}
function plRowsLocal(){
 const by={};DB.kids.forEach(k=>{const key=pkeyOf(k);if(!key)return;const g=by[key]=by[key]||{key,name:k.pn,kids:[],ids:[]};g.kids.push(k.n);g.ids.push(k.id)});
 return Object.values(by).map(g=>Object.assign({key:g.key,name:g.name,kids:g.kids},lkCalc(DB.lg.filter(e=>g.ids.includes(e.hs)),TODAY,(DB.pul||{})[g.key]))).filter(r=>r.overdue)
  .sort((a,b)=>(b.locked-a.locked)||(b.amt-a.amt)||(a.name<b.name?-1:1))}

/* ---- màn hình khóa của phụ huynh (chữ lớn, dễ đọc) ---- */
const lkMonths=ms=>(ms||[]).map(m=>(+m.slice(5,7))+'/'+m.slice(0,4)).join(', ');
function lockHtml(lk){
 const tel=lk.tel?`<p class="plg-tel">Liên hệ Trung tâm: <b>${esc(lk.tel)}</b></p>`:'';
 return`<div class="lg"><div class="lgl"><img src="${LOGO}" alt="Logo Trung tâm Can thiệp sớm Golden Bee"><h1>${esc(lk.name||CL_NAME)}</h1></div>
 <div class="lgr"><div class="lgc plg"><h2>Cổng phụ huynh đang tạm khóa</h2>
 <p class="plg-big" role="alert">Học phí ${lk.months&&lk.months.length?'tháng '+esc(lkMonths(lk.months)):''} chưa được thanh toán sau hạn ngày 10.</p>
 ${lk.amt?`<div class="plg-amt"><span>Số tiền còn phải đóng</span><b>${fmt(lk.amt)}</b></div>`:''}
 <p>Khi Trung tâm ghi nhận khoản thanh toán, cổng sẽ tự động mở lại. Nếu bạn đã chuyển khoản, hãy báo cho Trung tâm rồi bấm “Kiểm tra lại”.</p>${tel}
 <div class="acts" style="margin-top:16px"><button class="btn p" data-a="lockchk">Kiểm tra lại</button><button class="btn" data-a="logout">Đăng xuất</button></div></div></div></div>`}
ACT.lockchk=()=>{if(CLOUDMODE){phLoad();return false}};      /* bản demo: vẽ lại là đủ */

/* ---- phía nhân viên: danh sách phụ huynh quá hạn, mở khóa tạm, khóa lại ---- */
const canPlock=()=>isTT()||isQL()||isVP();
const plRows=()=>CLOUDMODE?(CLD.plock?CLD.plock.rows:null):plRowsLocal();
async function plApi(body,again){
 const r=await fetch((typeof window.GB_API==='string'?window.GB_API:'')+'/api/plock',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+CLD.ss.at},body:JSON.stringify(body)});
 if(r.status===401&&!again&&await sbRefresh())return plApi(body,true);
 if(r.status===404)throw new Error('Máy chủ chưa có chức năng khóa cổng phụ huynh.');
 const j=await r.json().catch(()=>({}));
 if(!r.ok)throw new Error(j.error||('Lỗi '+r.status));
 return j}
async function plLoad(quiet){if(!CLOUDMODE||!U||!canPlock())return;
 try{const j=await plApi({action:'list'});const same=CLD.plock&&JSON.stringify(CLD.plock.rows)===JSON.stringify(j.rows)&&!CLD.plockErr;CLD.plock=j;CLD.plockErr='';if(!same&&CLD.stage==='app')softRender()}
 catch(e){const was=CLD.plockErr;CLD.plockErr=e.message;if(!quiet||was!==e.message){if(CLD.stage==='app')softRender()}}}

function plStatus(r){return r.locked?tg('Đang khóa','er'):`${tg('Đã mở khóa','wa')}<br><span class="sm mu">đến ${vd(r.until)}</span>`}
function plockCard(always){
 if(!canPlock())return'';
 const err=CLOUDMODE&&CLD.plockErr,rows=plRows();
 if(err)return`<div class="card"><h2>Cổng phụ huynh quá hạn học phí</h2><p class="note sm">Chưa lấy được danh sách: ${esc(err)}</p></div>`;
 if(rows===null)return'';
 if(!rows.length)return always?`<div class="card"><h2>Cổng phụ huynh quá hạn học phí</h2><p class="mu">Không có phụ huynh nào quá hạn. Phụ huynh chưa đóng học phí sau ngày 10 hàng tháng sẽ tự động bị khóa cổng, ghi nhận thu đủ là tự mở lại.</p></div>`:'';
 const p=pg('plk',rows,8),$=canMoney(),nl=rows.filter(r=>r.locked).length;
 return`<div class="card" id="plock"><div class="top" style="align-items:center"><h2 style="margin:0">Cổng phụ huynh quá hạn học phí</h2>${tg(nl+' đang khóa',nl?'er':'ok')}</div>
 <p class="sm mu" style="margin:6px 0 10px">Phụ huynh chưa đóng đủ học phí sau ngày 10 hàng tháng bị khóa cổng tự động; ghi nhận thu đủ là cổng tự mở lại. Trưởng Trung tâm, Quản lý và Văn phòng có thể mở khóa tạm.</p>`
 +tbl(['Phụ huynh','Quá hạn',...($?['>Số tiền']:[]),'Tình trạng',''],p.rows.map(r=>`<tr><td><b>${esc(r.name||'(chưa có tên)')}</b><br><span class="sm mu">${esc((r.kids||[]).join(', '))}</span></td><td class="nw">${esc(lkMonths(r.months))}</td>${$?`<td class="r nw"><b>${fnum(r.amt)}</b></td>`:''}<td>${plStatus(r)}${r.unlocked&&r.by?`<br><span class="sm mu">bởi ${esc(r.by)}</span>`:''}</td><td class="nw">${r.unlocked?`<button class="btn s" data-a="plrelock" data-v="${esc(r.key)}">Khóa lại</button>`:`<button class="btn s p" data-a="plopen" data-v="${esc(r.key)}">Mở khóa</button>`}</td></tr>`).join(''))+p.html+`</div>`}

ACT.plopen=v=>{if(!canPlock())return false;const r=(plRows()||[]).find(x=>x.key===v);if(!r)return false;S.modal={t:'pl',key:v}};
MODALS.pl=()=>{const r=(plRows()||[]).find(x=>x.key===S.modal.key);if(!r||!canPlock()){S.modal=null;return''}
 const d=lkNext10(TODAY);
 return mdl('Mở khóa cổng phụ huynh',`<p><b>${esc(r.name)}</b> · ${esc((r.kids||[]).join(', '))}</p><p class="sm mu">Quá hạn học phí ${esc(lkMonths(r.months))}${canMoney()?' · '+fmt(r.amt):''}. Mở khóa tạm cho phụ huynh vào xem; đến hết ngày đã chọn cổng sẽ khóa lại nếu vẫn chưa đóng đủ.</p>
 <form id="plf" class="f"><div class="f2"><div><label for="pl-d">Mở đến hết ngày</label><input id="pl-d" name="until" type="date" value="${d}" min="${TODAY}" max="${addD(TODAY,LK_MAX_DAYS)}" required></div><div><label for="pl-n">Ghi chú (không bắt buộc)</label><input id="pl-n" name="note" maxlength="200" placeholder="Ví dụ: hẹn đóng ngày 15"></div></div>
 <div class="acts"><button class="btn p" type="submit">Mở khóa</button><button class="btn" type="button" data-a="mx">Hủy</button></div></form>`)};
FORM.plf=f=>{if(!canPlock())return false;
 const key=S.modal.key,until=f.elements.until.value,note=f.elements.note.value.trim().slice(0,200);
 if(!/^\d{4}-\d{2}-\d{2}$/.test(until)||until<TODAY||until>addD(TODAY,LK_MAX_DAYS)){toast('Ngày mở khóa phải từ hôm nay đến '+vd(addD(TODAY,LK_MAX_DAYS)));return false}
 if(!CLOUDMODE){DB.pul=DB.pul||{};DB.pul[key]={k:key,until,by:U.name,role:U.role,at:TODAY,note};S.modal=null;toast('Đã mở khóa đến hết ngày '+vd(until));return}
 plRun({action:'unlock',key,until,note},'Đã mở khóa đến hết ngày '+vd(until));return false};
ACT.plrelock=v=>{if(!canPlock())return false;const r=(plRows()||[]).find(x=>x.key===v);if(!r)return false;
 ask('Khóa lại cổng của phụ huynh '+(r.name||'')+'? Phụ huynh sẽ không vào được cho đến khi đóng đủ học phí hoặc được mở khóa lại.',()=>{
  if(!CLOUDMODE){if(DB.pul)delete DB.pul[v];toast('Đã khóa lại');return}
  plRun({action:'relock',key:v},'Đã khóa lại')},'Khóa lại')};
async function plRun(body,msg){
 try{await plApi(body);S.modal=null;toast(msg);await plLoad()}
 catch(e){toast(e.message)}
 render()}
/* ===== Cổng phụ huynh: hạn chế chụp màn hình, in, sao chép và truy vết khi hình bị gửi ra ngoài =====
   GIỚI HẠN: trình duyệt web KHÔNG thể chặn hẳn chụp màn hình của hệ điều hành hay chụp bằng điện thoại khác.
   Các biện pháp dưới đây làm khó và răn đe, và nhất là gắn tên + liên hệ + giờ xem lên mọi khung hình để truy được nguồn
   nếu hình bị chia sẻ. Chặn thật sự cần ứng dụng riêng (Android FLAG_SECURE, iOS phát hiện chụp/quay màn hình).
   Chỉ áp dụng cho tài khoản phụ huynh; nhân viên không bị ảnh hưởng. */
const guardOn=()=>!!(U&&U.role==='ph'&&DB&&!$q('.plg'));
const gEsc=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function gStamp(){
 const pad=n=>String(n).padStart(2,'0'),d=new Date(),when=pad(d.getDate())+'/'+pad(d.getMonth()+1)+'/'+d.getFullYear()+' '+pad(d.getHours())+':'+pad(d.getMinutes());
 const k=String(U.pkey||'').replace(/^tel:/,''),who=k.includes('@')?k:(k?'SĐT '+k.replace(/^84/,'0'):'');
 return{a:U.name||'Phụ huynh',b:who,c:when}}
function gTile(){
 const s=gStamp(),t=(y,x)=>`<text x="${x}" y="${y}" transform="rotate(-24 ${x} ${y})">`,
  svg=`<svg xmlns="http://www.w3.org/2000/svg" width="340" height="220"><g fill="#808080" fill-opacity=".2" font-family="Arial,sans-serif" font-size="15" font-weight="700">${t(120,20)}${gEsc(s.a)}</text>${t(142,20)}${gEsc(s.b)}</text>${t(164,20)}${gEsc(s.c)}</text></g></svg>`;
 return'url("data:image/svg+xml;utf8,'+encodeURIComponent(svg)+'")'}
let GM=null,GMO=null,GT=0;
function guardMark(){
 if(!GM||!document.body.contains(GM)){
  GM=document.createElement('div');GM.id='gmark';GM.setAttribute('aria-hidden','true');document.body.appendChild(GM)}
 const t=gTile();if(GM.dataset.t!==t){GM.dataset.t=t;GM.style.backgroundImage=t}
 /* gỡ lớp phủ bằng cách xóa phần tử thì dựng lại ngay (răn đe; người rành kỹ thuật vẫn gỡ được) */
 if(!GMO)GMO=new MutationObserver(()=>{if(guardOn())guardMark()});
 GMO.disconnect();GMO.observe(document.body,{childList:true});GMO.observe(GM,{attributes:true});
 if(GM.style.display)GM.style.display='';if(GM.hidden)GM.hidden=false}
function guardSync(){
 const on=guardOn();document.body.classList.toggle('gph',on);
 if(on)guardMark();else if(GM){GM.remove();GM=null}
 if(!on)document.body.classList.remove('gaway','gcover')}
/* vẽ lại thì đồng bộ lớp phủ */
const _renderG=render;render=function(){_renderG.apply(this,arguments);guardSync()};

/* che nội dung một lúc (PrintScreen, in, phím chụp) */
function guardCover(ms){if(!guardOn())return;document.body.classList.add('gcover');clearTimeout(GT);GT=setTimeout(()=>document.body.classList.remove('gcover'),ms||1500)}
const gEditable=t=>!!(t&&t.closest&&t.closest('input,textarea,select,[contenteditable="true"]'));
const gBlock=e=>{if(guardOn()&&!gEditable(e.target)){e.preventDefault();return true}return false};
['contextmenu','copy','cut','dragstart','selectstart'].forEach(ev=>document.addEventListener(ev,gBlock,true));
document.addEventListener('keydown',e=>{
 if(!guardOn())return;
 const k=String(e.key||'').toLowerCase(),mod=e.ctrlKey||e.metaKey;
 if(mod&&['p','s'].includes(k)){e.preventDefault();guardCover(1800);return}                   /* in, lưu trang */
 if(mod&&['c','x','a','u'].includes(k)&&!gEditable(e.target)){e.preventDefault();return}       /* sao chép, chọn hết, xem nguồn */
 if(e.metaKey&&e.shiftKey&&['3','4','5','#','$','%'].includes(e.key)){guardCover(2500)}        /* chụp màn hình trên Mac */
 if(e.key==='PrintScreen'||e.key==='Snapshot'){e.preventDefault();guardCover(2500)}},true);
document.addEventListener('keyup',e=>{
 if(!guardOn())return;
 if(e.key==='PrintScreen'||e.key==='Snapshot'){guardCover(2500);try{navigator.clipboard.writeText('Nội dung chỉ dành cho gia đình bé.').catch(()=>{})}catch(x){}}},true);
window.addEventListener('beforeprint',()=>guardCover(3000));
/* cửa sổ mất tiêu điểm hoặc bị ẩn (chuyển ứng dụng, công cụ chụp): làm mờ, để ảnh chụp màn hình chuyển tác vụ cũng mờ */
const gAway=on=>{if(on&&guardOn())document.body.classList.add('gaway');else document.body.classList.remove('gaway')};
window.addEventListener('blur',()=>gAway(true));
window.addEventListener('focus',()=>gAway(false));
document.addEventListener('visibilitychange',()=>gAway(document.visibilityState==='hidden'));
/* ===== Cây mục tiêu: mục tiêu buổi ⇒ mục tiêu ngắn hạn ⇒ mục tiêu dài hạn =====
   - Mục tiêu dài hạn là kế hoạch h:'d'. Mục tiêu ngắn hạn là kế hoạch h:'n', trường `up` giữ mã kế hoạch dài hạn mà nó thuộc về.
   - Mục tiêu buổi là một dòng mục tiêu trong buổi can thiệp, trường `pl` giữ mã kế hoạch ngắn hạn mà dòng đó thuộc về.
   - Dữ liệu cũ chưa có `up` hay `pl` vẫn chạy: dòng buổi gắn vào kế hoạch có cùng mục tiêu; ngắn hạn chưa gắn nằm ở nhóm "chưa gắn".
   - Trạng thái "đạt" của mục tiêu buổi theo số liệu: bé tự làm (mức Độc lập) đúng từ 80% trở lên trong 3 buổi liên tiếp.
     Mục tiêu ngắn hạn và dài hạn chỉ là "Đã đạt" khi nhân viên bấm xác nhận; khi mọi mục tiêu con đã đạt thì hiện "Gần đạt". */
const GTS={dat:['Đã đạt','✓'],gan:['Gần đạt','✓'],tien:['Đang tiến bộ','↗'],luyen:['Cần luyện thêm','!'],moi:['Sắp luyện','○'],tam:['Tạm dừng','‖']};
const gtChip=(st,big)=>`<span class="gt-chip s-${st}${big?' big':''}"><span class="gt-i" aria-hidden="true">${GTS[st][1]}</span>${GTS[st][0]}</span>`;
const gtBar=(pct,st,lb)=>`<div class="gt-bar s-${st}" role="img" aria-label="${esc(lb||'Hoàn thành')} ${pct}%"><i style="width:${Math.max(0,Math.min(100,pct))}%"></i></div>`;

/* trạng thái của MỘT mục tiêu buổi từ các lượt luyện của nó (theo thứ tự thời gian) */
function gtState(rs){const n=rs.length;if(!n)return{st:'moi',pct:0,n:0,run:0,last:null,rs};
 let run=0;for(let i=n-1;i>=0;i--){const r=rs[i];if(r.sup==='I'&&trN(r.tr)>=5&&trOk(r.tr)/trN(r.tr)>=.8)run++;else break}
 const l=avg(rs.slice(-2).map(r=>r.sc)),f=avg(rs.slice(0,2).map(r=>r.sc)),dl=n>=2?l-f:null,st=run>=3?'dat':((dl!=null&&dl>=2)||l>=60)?'tien':'luyen';
 return{st,pct:st==='dat'?100:Math.round(l),n,run,last:rs[n-1],dl,rs}}

/* mục tiêu dài hạn mà kế hoạch ngắn hạn p đang thuộc về (null nếu chưa gắn hoặc mã không còn hợp lệ) */
function gtUp(p){const l=p&&p.h==='n'&&p.up?planBy(p.up):null;return l&&l.k===p.k&&l.h==='d'?l:null}
/* kế hoạch mà một dòng mục tiêu trong buổi thuộc về */
function gtItemPlan(k,it,byG){if(it.pl){const p=planBy(it.pl);if(p&&p.k===k)return p}
 const a=byG[it.g];return a?(a.find(p=>p.s!=='dat')||a[0]):null}

/* dựng cây cho một bé: {longs:[nút dài hạn], orph:[nút ngắn hạn chưa gắn], shorts:[mọi nút ngắn hạn]} */
function gtTree(kid){
 const ps=kidPlans(kid),byG={};ps.forEach(p=>(byG[p.g]=byG[p.g]||[]).push(p));
 const recs={},seen={};
 sessOf(kid,'','9999-12-31',true).forEach(s=>s.it.forEach(it=>{const p=gtItemPlan(kid,it,byG);if(!p)return;
  (seen[p.id]=seen[p.id]||{})[it.g]=1;if(!trN(it.tr))return;const sc=recSc(it);if(sc==null)return;
  const o=recs[p.id]=recs[p.id]||{};(o[it.g]=o[it.g]||[]).push({d:s.date,g:it.g,sup:it.sup,tr:it.tr,sc})}));
 const goalsOf=p=>Object.keys(seen[p.id]||{}).map(g=>Object.assign({g},gtState((recs[p.id]||{})[g]||[]))).sort((a,b)=>(b.last?b.last.d:'')<(a.last?a.last.d:'')?-1:1);
 const alive=n=>n.p.s!=='tam';
 const shorts=ps.filter(p=>p.h==='n').map(p=>{const gs=goalsOf(p),dn=gs.filter(x=>x.st==='dat').length,any=gs.some(x=>x.n);
  const pct=p.s==='dat'?100:gs.length?Math.round(avg(gs.map(x=>x.pct))):0,
   st=p.s==='dat'?'dat':p.s==='tam'?'tam':!any?'moi':dn===gs.length?'gan':gs.some(x=>x.st==='dat'||x.st==='tien')?'tien':'luyen';
  return{p,gs,dn,total:gs.length,pct,st,ready:p.s==='dang'&&gs.length>0&&dn===gs.length}});
 const longs=ps.filter(p=>p.h==='d').map(p=>{const ch=shorts.filter(s=>gtUp(s.p)&&s.p.up===p.id),gs=goalsOf(p),live=ch.filter(alive),
   units=live.map(s=>s.pct).concat(gs.map(x=>x.pct)),dn=live.filter(s=>s.st==='dat').length+gs.filter(x=>x.st==='dat').length,total=live.length+gs.length,
   any=live.some(s=>s.gs.some(x=>x.n))||gs.some(x=>x.n),
   pct=p.s==='dat'?100:units.length?Math.round(avg(units)):0,
   st=p.s==='dat'?'dat':p.s==='tam'?'tam':!any?'moi':total&&dn===total?'gan':(live.some(s=>s.st==='dat'||s.st==='gan'||s.st==='tien')||gs.some(x=>x.st==='dat'||x.st==='tien'))?'tien':'luyen';
  return{p,ch,gs,dn,total,pct,st,ready:p.s==='dang'&&total>0&&dn===total}});
 const orph=shorts.filter(s=>!gtUp(s.p));
 return{longs,orph,shorts}}

/* ---------------- Cổng phụ huynh và báo cáo: chữ lớn, màu và biểu tượng cho từng trạng thái ---------------- */
const gtLast=x=>x.last?`Buổi gần nhất: đúng <b>${trOk(x.last.tr)}/${trN(x.last.tr)}</b> lượt · ${esc(SUP[x.last.sup].p.toLowerCase())}`:'Chưa luyện';
function gtGoals(n,m){const gs=n.gs;if(!gs.length)return'';
 return`<ul class="gtg">${gs.map(x=>`<li class="s-${x.st}"><span class="gt-ic" aria-hidden="true">${GTS[x.st][1]}</span><div><span class="gt-k">Mục tiêu buổi</span><span class="gtg-n">${esc(gName(x.g))}</span><span class="gtg-s">${gtChip(x.st)} ${gtLast(x)}</span>${x.rs.length>1?`<span class="gtg-h">Các buổi gần đây: ${x.rs.slice(-5).map(r=>trOk(r.tr)+'/'+trN(r.tr)).join(' → ')}</span>`:''}${m==='pdf'?'':gxHtml(goalOf(x.g),'p')}</div></li>`).join('')}</ul>`}
function gtShort(s,par,m){return`<div class="gts s-${s.st}"><div class="gts-h"><span class="gt-ic" aria-hidden="true">${GTS[s.st][1]}</span><div class="gts-t"><span class="gt-k">Mục tiêu ngắn hạn</span><b>${esc(gName(s.p.g))}</b></div>${gtChip(s.st)}</div>
 <div class="gt-pb">${gtBar(s.pct,s.st)}<b>${s.pct}%</b></div>${s.total?`<p class="gt-sub">${s.dn}/${s.total} mục tiêu buổi đã đạt</p>`:'<p class="gt-sub">Chưa có mục tiêu buổi nào được ghi.</p>'}${gxHtml(goalOf(s.p.g),m==='pdf'?'pdf':'p',{open:1})}${gtGoals(s,m)}</div>`}
function gtParent(kid,o){o=o||{};const T=gtTree(kid),L=T.longs.filter(n=>n.p.s!=='tam'),O=T.orph.filter(s=>s.p.s!=='tam'),m=o.pdf?'pdf':'p';
 if(!L.length&&!O.length)return'<p class="empty">Giáo viên chưa đặt mục tiêu cho bé. Khi có mục tiêu, bé đạt hay chưa đạt sẽ hiện ở đây.</p>';
 const sh=T.shorts.filter(s=>s.p.s!=='tam'),cnt={dat:0,tien:0,luyen:0,moi:0};
 sh.forEach(s=>{cnt[s.st==='gan'?'tien':s.st]++});
 const box=(st,l)=>`<div class="gt-n s-${st}"><span class="gt-ic" aria-hidden="true">${GTS[st][1]}</span><b>${cnt[st]}</b><span>${l}</span></div>`;
 const sum=sh.length?`<div class="gt-sum" role="group" aria-label="Tóm tắt các mục tiêu ngắn hạn">${box('dat','mục tiêu đã đạt')}${box('tien','mục tiêu đang tiến bộ')}${box('luyen','mục tiêu cần luyện thêm')}${box('moi','mục tiêu sắp luyện')}</div>`:'';
 const lg=`<p class="gt-help">Bé <b>đạt</b> một mục tiêu buổi khi tự làm đúng từ 8/10 lượt trở lên trong 3 buổi liên tiếp. Mỗi mục tiêu dài hạn gồm nhiều mục tiêu ngắn hạn, mỗi mục tiêu ngắn hạn gồm nhiều mục tiêu buổi.</p>`;
 const mc=(lb,n)=>`<div class="gtp s-${n.st}"><div class="gtp-h"><div><span class="gt-k">${lb}</span><b class="gtp-t">${esc(gName(n.p.g))}</b></div>${gtChip(n.st,1)}</div><div class="gt-pb">${gtBar(n.pct,n.st)}<b>${n.pct}%</b></div></div>`;
 if(o.mini)return sum+`<div class="gtl">${L.map(n=>mc('Mục tiêu dài hạn',n)).join('')}${O.map(n=>mc('Mục tiêu ngắn hạn',n)).join('')}</div>`
  +`<div class="acts" style="margin-top:12px"><button class="btn p" data-a="cptab" data-v="tb">Xem từng mục tiêu của bé</button></div>`;
 const card=n=>`<article class="gtp nb s-${n.st}"><div class="gtp-h"><div><span class="gt-k">Mục tiêu dài hạn</span><h3 class="gtp-t">${esc(gName(n.p.g))}</h3></div>${gtChip(n.st,1)}</div>
  <div class="gt-pb">${gtBar(n.pct,n.st)}<b>${n.pct}%</b></div><p class="gt-sub">${n.total?n.dn+'/'+n.total+' mục tiêu con đã đạt':'Chưa có mục tiêu ngắn hạn.'}</p>
  ${gxHtml(goalOf(n.p.g),m==='pdf'?'pdf':'p',{open:1})}${n.ch.filter(s=>s.p.s!=='tam').map(s=>gtShort(s,1,m)).join('')}${n.gs.length?`<div class="gts"><div class="gts-h"><div class="gts-t"><span class="gt-k">Luyện trực tiếp</span></div></div>${gtGoals(n,m)}</div>`:''}</article>`;
 return sum+lg+L.map(card).join('')+(O.length?`<article class="gtp nb"><div class="gtp-h"><div><span class="gt-k">Mục tiêu ngắn hạn khác</span></div></div>${O.map(s=>gtShort(s,1,m)).join('')}</article>`:'')}

/* ---------------- Phía nhân viên: cây trong tab Kế hoạch mục tiêu ---------------- */
function gtKidsStaff(n){if(!n.gs.length)return'';
 return`<ul class="gt-ks">${n.gs.map(x=>`<li>${gtChip(x.st)} <span class="gt-gn">${esc(gName(x.g))}</span> <span class="sm mu">${x.n?x.n+' buổi · '+gtLast(x).replace(/<\/?b>/g,''):'chưa luyện'}</span></li>`).join('')}</ul>`}
function gtUpSel(p,longs){return`<div class="gt-up"><label class="sm" for="gu-${p.id}">Thuộc mục tiêu dài hạn</label>${longs.length?`<select id="gu-${p.id}" data-c="plup" data-v="${p.id}">${opts([['','— Chưa gắn —']].concat(longs.map(l=>[l.id,gName(l.g)])),gtUp(p)?p.up:'')}</select>`:'<span class="sm mu">Chưa có mục tiêu dài hạn nào để gắn</span>'}</div>`}
function gtShortStaff(s,longs){return planRow(s.p)+`<div class="gt-x">${s.total?`<div class="sm"><b>Mục tiêu buổi</b> · ${s.dn}/${s.total} đã đạt · ${s.pct}%</div>`+gtKidsStaff(s):'<div class="sm mu">Chưa có mục tiêu buổi. Khi ghi buổi can thiệp, chọn mục tiêu ngắn hạn này cho từng dòng mục tiêu.</div>'}${gtUpSel(s.p,longs)}</div>`}
function gtLongStaff(n,longs){const sh=n.ch;
 return`<section class="gt-b s-${n.st}">${planRow(n.p)}<div class="gt-x"><div class="gt-pb">${gtBar(n.pct,n.st)}<b>${n.pct}%</b></div><div class="sm">${n.total?n.dn+'/'+n.total+' mục tiêu con đã đạt':'Chưa có mục tiêu ngắn hạn thuộc mục tiêu này'}</div>
  <div class="acts" style="margin-top:6px"><button class="btn s p" data-a="pkopenu" data-v="${n.p.id}">Thêm mục tiêu ngắn hạn</button></div></div>
  <div class="gt-in">${sh.map(s=>gtShortStaff(s,longs)).join('')}${n.gs.length?`<div class="gt-x"><div class="sm"><b>Luyện trực tiếp mục tiêu dài hạn</b></div>${gtKidsStaff(n)}</div>`:''}</div></section>`}
function gtStaff(k){const T=gtTree(k.id),longs=T.longs.map(n=>n.p).filter(l=>l.s!=='dat');
 const open=T.longs.filter(n=>n.p.s!=='dat'),done=T.longs.filter(n=>n.p.s==='dat'),orph=T.orph;
 let h=`<h3 style="margin-top:12px">Mục tiêu dài hạn <span class="mu sm">· ${HZ.d[1]} · ${open.length} mục tiêu</span></h3><p class="sm mu" style="margin:0 0 8px">Mục tiêu buổi ⇒ mục tiêu ngắn hạn ⇒ mục tiêu dài hạn. Mỗi mục tiêu dài hạn gồm các mục tiêu ngắn hạn; mỗi mục tiêu ngắn hạn gồm các mục tiêu buổi (các dòng mục tiêu trong buổi can thiệp).</p>`;
 h+=open.length?open.map(n=>gtLongStaff(n,longs)).join(''):'<p class="mu sm" style="margin:0 0 8px">Chưa có mục tiêu dài hạn. Bấm “Chọn mục tiêu từ ngân hàng”, chọn loại “Dài hạn”.</p>';
 const oa=orph.filter(s=>s.p.s!=='dat');
 h+=`<h3 style="margin-top:14px">Mục tiêu ngắn hạn chưa gắn mục tiêu dài hạn <span class="mu sm">· ${oa.length} mục tiêu</span></h3>`;
 h+=oa.length?(longs.length?`<div class="acts" style="margin:0 0 6px"><button class="btn s" data-a="plauto" data-v="${k.id}">Tự gắn theo lĩnh vực</button><span class="sm mu">Gắn mỗi mục tiêu ngắn hạn vào mục tiêu dài hạn cùng lĩnh vực.</span></div>`:'')+oa.map(s=>gtShortStaff(s,longs)).join(''):'<p class="mu sm" style="margin:0 0 8px">Mọi mục tiêu ngắn hạn đều đã được gắn vào một mục tiêu dài hạn.</p>';
 if(done.length||orph.some(s=>s.p.s==='dat')){
  h+=`<h3 style="margin-top:14px">Đã đạt <span class="mu sm">· ${done.length+orph.filter(s=>s.p.s==='dat').length} mục tiêu</span></h3>`
   +done.sort((a,b)=>(b.p.dt||'')<(a.p.dt||'')?-1:1).map(n=>gtLongStaff(n,longs)).join('')+orph.filter(s=>s.p.s==='dat').map(s=>gtShortStaff(s,longs)).join('')}
 return{html:h,T}}

/* ---------------- Thao tác ---------------- */
CHG.plup=(v,t)=>{const p=planBy(t.dataset.v);if(!p||p.h!=='n'||!canKid(p.k))return false;
 const l=v?planBy(v):null;if(l&&l.k===p.k&&l.h==='d')p.up=v;else delete p.up};
ACT.plauto=v=>{if(!canKid(v))return false;const ls=kidPlans(v).filter(p=>p.h==='d'&&p.s!=='dat');let n=0;
 kidPlans(v).filter(p=>p.h==='n'&&p.s!=='dat'&&!gtUp(p)).forEach(p=>{const dm=gDom(p.g),l=ls.find(x=>x.s==='dang'&&gDom(x.g)===dm)||ls.find(x=>gDom(x.g)===dm);if(l){p.up=l.id;n++}});
 toast(n?'Đã gắn '+n+' mục tiêu ngắn hạn vào mục tiêu dài hạn cùng lĩnh vực':'Không có mục tiêu ngắn hạn nào cùng lĩnh vực với một mục tiêu dài hạn')};
ACT.pkopenu=v=>{const l=planBy(v);if(!l||!canKid(l.k))return false;
 S.modal={t:'gp',mode:'plan',k:l.k,up:l.id,back:S.modal&&S.modal.t==='hs'?S.modal:null,f:{dom:gDom(l.g),src:'',head:'',age:'',q:''},sel:[],hz:'n'};S.pg.gp=1};
/* mục tiêu dài hạn còn mở cùng lĩnh vực với mục tiêu g (để gắn mặc định cho mục tiêu ngắn hạn mới) */
const gtAutoUp=(k,g)=>{const dm=gDom(g),ls=kidPlans(k).filter(p=>p.h==='d'&&p.s!=='dat'),l=ls.find(x=>x.s==='dang'&&gDom(x.g)===dm);return l?l.id:''};
/* ===== Vi phạm nội quy và trừ lương ===== */
/* Theo thông báo "Nhắc nhở chung về giờ làm việc và quy định Trung tâm": các lỗi dưới đây được note lại và xử lý, mỗi lần bị note 20.000 đến 30.000 ₫;
   tùy mức độ, hậu quả và số lần tái diễn có thể cao hơn; trường hợp đặc biệt hoặc tái phạm nhiều lần do Trưởng Trung tâm quyết định.
   Quy trình: Quản lý ghi vi phạm và đề xuất mức (không thấy số tiền) → Trưởng Trung tâm duyệt và quyết định số tiền → chỉ vi phạm đã duyệt mới trừ vào lương của tháng có ngày vi phạm (payroll, vpen).
   Dữ liệu: DB.vio (collection vio, không phải tiền) = {id,st,d,r,n,lv,s,by,at,dby,dat,dn}; số tiền nằm ở DB.vam[nhânviên|mã] (money_records, collection vam: chỉ Trưởng Trung tâm, Văn phòng; nhân viên đọc phần của mình). */
const VIO_R=[['r1','Đi làm trễ nhưng không báo'],['r2','Đồ chơi, học cụ bị hư hỏng, thiếu nhưng không kiểm tra hoặc không báo lại'],['r3','Để học sinh làm hỏng đồ chơi, học cụ do thiếu giám sát'],['r4','Không note đồ chơi vào file danh sách mượn đồ chơi'],['r5','Sử dụng điện thoại trong giờ dạy khi không phục vụ công việc'],['r6','Nói chuyện, làm việc riêng, thiếu tập trung trong giờ dạy'],['r7','Gửi thiếu tiến độ, video hoặc hình ảnh giờ học theo yêu cầu'],['r8','Để học sinh chạy ra ngoài hoặc không đảm bảo an toàn cho học sinh'],['r9','Có hành vi, lời nói hoặc cách xử lý không phù hợp khi quản lý hành vi học sinh'],['r10','Dạy không đủ thời lượng (giáo viên cá nhân)'],['r11','Cắt bỏ tiết học của học sinh (giáo viên nhóm)'],['r12','Không báo cho phụ huynh khi phát hiện vết thương hoặc dấu hiệu bất thường của học sinh'],['rx','Lý do khác, ghi rõ ở ghi chú']];
const VIO_LV=[[1,'Mức 1, nhẹ'],[2,'Mức 2, vừa'],[3,'Mức cao hơn, trường hợp đặc biệt hoặc tái phạm']];
const VIO_ST={cho:['Chờ duyệt','wa'],duyet:['Đã duyệt','ok'],tuchoi:['Không áp dụng','gy']};
const vioR=id=>{const r=VIO_R.find(x=>x[0]===id);return r?r[1]:String(id||'')};
const vioLvT=n=>{const r=VIO_LV.find(x=>x[0]===+n);return r?r[1]:VIO_LV[0][1]};
const vioLvAmt=n=>+n===1?(+DB.cfg.v1||0):+n===2?(+DB.cfg.v2||0):0;
const vioOf=id=>(DB.vio||[]).find(v=>v.id===id);
const vioMoney=()=>canMoney()||isGV();   /* thấy số tiền trừ: Trưởng Trung tâm, Văn phòng, và nhân viên với phần của chính mình */
const vioKey=v=>v.st+'|'+v.id;
/* số lần đã được ghi nhận của cùng nhân sự trong cùng tháng (không tính lần đang xét và lần không áp dụng), để Trưởng Trung tâm cân nhắc tái diễn */
const vioPrev=v=>{const m=String(v.d).slice(0,7),o=DB.vio.filter(x=>x.id!==v.id&&x.st===v.st&&x.s!=='tuchoi'&&String(x.d).slice(0,7)===m);return{n:o.length,same:o.filter(x=>x.r===v.r).length}};
const vioMonths=()=>[0,-1,-2,-3,-4,-5].map(k=>sm(CM,k));

VIEWS.vi=()=>{const c=S.vi=Object.assign({tab:'ds',m:CM,st:''},S.vi),gv=isGV(),pend=DB.vio.filter(v=>v.s==='cho').length;
 const tabs=gv?[['ds','Của tôi'],['quy','Quy định']]:[['ds','Danh sách'+(pend?' ('+pend+' chờ duyệt)':'')],['quy','Quy định']];
 if(!tabs.some(t=>t[0]===c.tab))c.tab='ds';
 return head(gv?'Vi phạm của tôi':'Vi phạm nội quy',gv?'Các lần vi phạm đã được Trưởng Trung tâm duyệt':'Ghi nhận lỗi theo quy định Trung tâm và mức trừ lương',isLead()?'<button class="btn p" data-a="vinew">Ghi vi phạm</button>':'')+tabsH(tabs,c.tab,'vitab')+(c.tab==='quy'?vioRules():vioList2())};
ACT.vitab=v=>{S.vi.tab=v};
CHG.vim=v=>{S.vi.m=v};
CHG.vist=v=>{S.vi.st=v};
function vioList2(){const c=S.vi,gv=isGV(),money=vioMoney();
 let rows=DB.vio.filter(v=>(!c.m||String(v.d).slice(0,7)===c.m)&&(!c.st||v.st===c.st)&&(!gv||(v.st===U.id&&v.s==='duyet'))).sort((a,b)=>a.s===b.s?(a.d<b.d?1:-1):a.s==='cho'?-1:b.s==='cho'?1:(a.d<b.d?1:-1));
 const tot=rows.filter(v=>v.s==='duyet').reduce((a,v)=>a+vioAmt(v),0);
 const ctl=`<div class="card"><div class="f2" style="margin-bottom:12px"><div><label for="vi-m">Tháng</label><select id="vi-m" data-c="vim">${opts([['','Mọi tháng']].concat(vioMonths().map(m=>[m,mLabel(m)])),c.m)}</select></div>${gv?'':`<div><label for="vi-s">Nhân sự</label><select id="vi-s" data-c="vist"><option value="">Tất cả</option>${opts(DB.staff.filter(s=>s.st==='dang').map(s=>[s.id,s.n]),c.st)}</select></div>`}</div>`;
 const th=['Ngày'].concat(gv?[]:['Nhân sự'],['Lý do','Mức'],money?['>Số tiền trừ']:[],['Ghi chú'],gv?[]:['Người ghi'],['Trạng thái',''].slice(0,gv?1:2));
 const body=rows.map(v=>{const st=VIO_ST[v.s]||VIO_ST.cho;
  return`<tr><td class="nw">${vd(v.d)}</td>${gv?'':`<td><b>${esc(sn(v.st))}</b></td>`}<td>${esc(vioR(v.r))}</td><td class="nw">${esc(vioLvT(v.lv).split(',')[0])}</td>${money?`<td class="r nw">${v.s==='duyet'?fmt(vioAmt(v)):'–'}</td>`:''}<td>${esc(v.n||'')}${v.dn?`<br><span class="sm mu">Trưởng Trung tâm: ${esc(v.dn)}</span>`:''}</td>${gv?'':`<td>${esc(sn(v.by))}</td>`}<td>${tg(st[0],st[1])}</td>${gv?'':`<td class="nw">${vioActs(v)}</td>`}</tr>`}).join('');
 return ctl+tbl(th,body,gv?'Bạn chưa có vi phạm nào được duyệt trong thời gian này.':'Chưa có ghi nhận vi phạm nào.')
  +(money&&rows.some(v=>v.s==='duyet')?`<p class="sm" style="margin-top:8px"><b>Tổng trừ lương đã duyệt: ${fmt(tot)}</b></p>`:'')
  +`<p class="sm mu" style="margin-top:8px">${gv?'Số tiền trừ được tính vào phiếu lương của tháng có ngày vi phạm.':isTT()?'Bấm "Duyệt" để quyết định số tiền trừ lương. Chỉ vi phạm đã duyệt mới trừ vào lương của tháng có ngày vi phạm.':isQL()?'Quản lý ghi vi phạm và đề xuất mức; Trưởng Trung tâm duyệt và quyết định số tiền. Quản lý không xem số tiền.':'Chỉ xem, việc ghi và duyệt do Quản lý và Trưởng Trung tâm thực hiện.'}</p></div>`}
function vioActs(v){
 if(isTT())return(v.s==='duyet'?`<button class="btn s" data-a="vinew" data-v="${v.id}">Sửa</button> `:`<button class="btn s p" data-a="videc" data-v="${v.id}">${v.s==='cho'?'Duyệt':'Duyệt lại'}</button> `)+`<button class="btn s no" data-a="videl" data-v="${v.id}">Xóa</button>`;
 if(isQL()&&v.s==='cho'&&v.st!==U.id)return`<button class="btn s" data-a="vinew" data-v="${v.id}">Sửa</button> <button class="btn s no" data-a="videl" data-v="${v.id}">Xóa</button>`;
 return''}
function vioRules(){const mo=canMoney(),c=DB.cfg;
 return`<div class="card"><h2>Các lỗi được note lại và xử lý theo quy định</h2><ol class="sm" style="margin:8px 0 12px 20px;line-height:1.7">${VIO_R.slice(0,12).map(r=>`<li>${esc(r[1])}</li>`).join('')}<li>Các trường hợp khác (v.v.), Quản lý ghi rõ lý do.</li></ol>
 <h3>Mức xử lý</h3><p class="sm">${mo?`Mỗi lần bị note: mức 1 ${fmt(c.v1==null?20000:c.v1)}, mức 2 ${fmt(c.v2==null?30000:c.v2)} (đổi ở Nhân sự, Cài đặt).`:'Mỗi lần bị note, Trung tâm trừ lương theo mức đã thông báo chung.'} Tùy theo mức độ vi phạm, hậu quả và số lần tái diễn, mức xử lý có thể cao hơn. Các trường hợp đặc biệt hoặc tái phạm nhiều lần do Trưởng Trung tâm xem xét và quyết định mức xử lý cụ thể.</p>
 <p class="note sm" style="margin-top:10px">Quản lý ghi vi phạm và đề xuất mức; Trưởng Trung tâm duyệt và quyết định số tiền. Chỉ vi phạm đã duyệt mới trừ vào lương của tháng có ngày vi phạm, và hiện trên phiếu lương của nhân viên.</p></div>`}

/* --- ghi, sửa --- */
ACT.vinew=v=>{if(!isLead())return false;const x=v?vioOf(v):null;
 if(x&&!isTT()&&(x.s!=='cho'||x.st===U.id)){toast('Vi phạm đã được xử lý, chỉ Trưởng Trung tâm sửa được');return false}
 S.modal={t:'vif',id:x?x.id:''}};
MODALS.vif=()=>{const id=S.modal.id,v=id?vioOf(id):null,tt=isTT(),sl=DB.staff.filter(s=>s.st==='dang'&&(tt||s.id!==U.id)),amt=v&&DB.vam?DB.vam[vioKey(v)]:'';
 return mdl(v?'Sửa ghi nhận vi phạm':'Ghi nhận vi phạm',`<form id="vif" class="f"><div class="f2"><div><label for="vi-st">Nhân sự</label><select id="vi-st" name="st" required><option value="">Chọn nhân sự</option>${opts(sl.map(s=>[s.id,s.n+' · '+s.pos]),v?v.st:'')}</select></div><div><label for="vi-d">Ngày vi phạm</label><input id="vi-d" name="d" type="date" max="${TODAY}" value="${v?v.d:TODAY}" required></div></div>
 <div><label for="vi-r">Lý do (theo quy định của Trung tâm)</label><select id="vi-r" name="r">${opts(VIO_R,v?v.r:'r1')}</select></div>
 <div><label for="vi-n">Ghi chú chi tiết (bắt buộc nếu chọn "Lý do khác")</label><textarea id="vi-n" name="n" rows="3">${esc(v?v.n:'')}</textarea></div>
 <div class="f2"><div><label for="vi-lv">Mức xử lý${tt?'':' đề xuất'}</label><select id="vi-lv" name="lv">${opts(VIO_LV,v?v.lv:1)}</select></div>${tt?`<div><label for="vi-a">Số tiền trừ lương (₫)</label><input id="vi-a" name="a" type="number" min="0" step="1000" value="${amt||''}" placeholder="Để trống: theo mức 1 hoặc mức 2"></div>`:''}</div>
 <p class="sm mu">${tt?`Mức 1 là ${fmt(DB.cfg.v1)}, mức 2 là ${fmt(DB.cfg.v2)}. Mức cao hơn thì nhập số tiền. Trưởng Trung tâm ghi trực tiếp thì được duyệt luôn.`:'Quản lý ghi lý do và đề xuất mức, Trưởng Trung tâm sẽ duyệt và quyết định số tiền trừ lương.'} Ghi chú sẽ hiện cho nhân sự sau khi vi phạm được duyệt.</p>
 <div class="acts" style="justify-content:flex-end"><button class="btn" type="button" data-a="mx">Hủy</button><button class="btn p" type="submit">${tt?'Lưu và duyệt':'Gửi Trưởng Trung tâm duyệt'}</button></div></form>`)};
FORM.vif=f=>{if(!isLead())return false;const e=f.elements,id=S.modal.id,old=id?vioOf(id):null,tt=isTT();
 const st=e.st.value,d=e.d.value,r=e.r.value,n=e.n.value.trim(),lv=Math.min(3,Math.max(1,+e.lv.value||1));
 if(!stBy(st)||!d){toast('Hãy chọn nhân sự và ngày vi phạm');return false}
 if(d>TODAY){toast('Ngày vi phạm không được ở tương lai');return false}
 if(r==='rx'&&!n){toast('Lý do khác cần ghi rõ ở ghi chú');return false}
 if(!tt&&st===U.id){toast('Quản lý không ghi vi phạm cho chính mình');return false}
 if(old&&!tt&&(old.s!=='cho'||old.st===U.id)){toast('Vi phạm đã được xử lý, chỉ Trưởng Trung tâm sửa được');return false}
 let a=0;if(tt){a=Math.round(+e.a.value)||vioLvAmt(lv);if(!(a>0)){toast('Mức cao hơn cần nhập số tiền trừ lương');return false}}
 const x=old||{id:'vi'+uid(),by:U.id,at:TODAY,s:'cho'};
 if(old&&DB.vam[vioKey(old)]!=null)delete DB.vam[vioKey(old)];   /* đổi nhân sự thì đổi khóa tiền */
 Object.assign(x,{st,d,r,n,lv});
 if(tt){x.s='duyet';x.dby=U.id;x.dat=TODAY;DB.vam[vioKey(x)]=a}
 if(!old)DB.vio.push(x);
 S.modal=null;toast(tt?'Đã ghi và duyệt vi phạm':'Đã gửi Trưởng Trung tâm duyệt')};

/* --- duyệt, không áp dụng, xóa (Trưởng Trung tâm) --- */
ACT.videc=v=>{if(!isTT()||!vioOf(v))return false;S.modal={t:'vid',id:v}};
MODALS.vid=()=>{const v=vioOf(S.modal.id);if(!v)return'';const pv=vioPrev(v),a=(DB.vam&&DB.vam[vioKey(v)])||vioLvAmt(v.lv)||'';
 return mdl('Duyệt vi phạm',`<p><b>${esc(sn(v.st))}</b> · ${vd(v.d)}</p><p style="margin-top:4px">${esc(vioR(v.r))}</p>${v.n?`<p class="mu sm" style="margin-top:4px">Ghi chú: ${esc(v.n)}</p>`:''}
 <p class="sm mu" style="margin:8px 0">Quản lý ${esc(sn(v.by))} đề xuất: ${esc(vioLvT(v.lv))}. Trong tháng này nhân sự đã có ${pv.n} lần được ghi nhận khác (${pv.same} lần cùng lý do).</p>
 <form id="vidf" class="f"><div class="f2"><div><label for="vd-a">Số tiền trừ lương (₫)</label><input id="vd-a" name="a" type="number" min="0" step="1000" value="${a}" required></div><div><label for="vd-n">Ghi chú của Trưởng Trung tâm (nếu có)</label><input id="vd-n" name="dn" value="${esc(v.dn||'')}"></div></div>
 <p class="sm mu">Mức 1 là ${fmt(DB.cfg.v1)}, mức 2 là ${fmt(DB.cfg.v2)}; tái diễn hoặc nặng thì nhập số cao hơn. Trừ vào lương tháng ${+v.d.slice(5,7)}/${v.d.slice(0,4)}.</p>
 <div class="acts" style="justify-content:flex-end"><button class="btn no" type="button" data-a="vireject">Không áp dụng</button><button class="btn" type="button" data-a="mx">Hủy</button><button class="btn p" type="submit">Duyệt, trừ lương</button></div></form>`)};
FORM.vidf=f=>{if(!isTT())return false;const v=vioOf(S.modal.id);if(!v)return false;const a=Math.round(+f.elements.a.value);
 if(!(a>0)){toast('Hãy nhập số tiền trừ lương lớn hơn 0');return false}
 Object.assign(v,{s:'duyet',dby:U.id,dat:TODAY,dn:f.elements.dn.value.trim()});DB.vam[vioKey(v)]=a;S.modal=null;toast('Đã duyệt, trừ '+fmt(a)+' vào lương')};
ACT.vireject=()=>{if(!isTT())return false;const v=vioOf(S.modal&&S.modal.id);if(!v)return false;const n=$q('#vd-n');
 Object.assign(v,{s:'tuchoi',dby:U.id,dat:TODAY,dn:n?n.value.trim():''});delete DB.vam[vioKey(v)];S.modal=null;toast('Đã đặt không áp dụng, không trừ lương')};
ACT.videl=id=>{const v=vioOf(id);if(!v||!(isTT()||(isQL()&&v.s==='cho'&&v.st!==U.id)))return false;
 ask('Xóa ghi nhận vi phạm của '+sn(v.st)+' ngày '+vd(v.d)+'?'+(v.s==='duyet'?' Số tiền đã trừ sẽ không còn trong lương.':''),()=>{DB.vio=DB.vio.filter(x=>x.id!==id);delete DB.vam[vioKey(v)];toast('Đã xóa')},'Xóa')};
/* Nút "Hiển thị / Ẩn" mật khẩu: gắn cho mọi ô type=password, kể cả ô được vẽ lại sau mỗi lần render. Chỉ đổi kiểu hiển thị của ô, không lưu gì. */
(function(){
 const enh=root=>{
  if(!root||!root.querySelectorAll)return;
  root.querySelectorAll('input[type=password]').forEach(inp=>{
   if(inp.dataset.pwOn||!inp.parentNode)return;
   inp.dataset.pwOn='1';
   const wrap=document.createElement('span');wrap.className='pw-wrap';
   inp.parentNode.insertBefore(wrap,inp);wrap.appendChild(inp);
   const b=document.createElement('button');b.type='button';b.className='pw-eye';
   b.textContent='Hiển thị';b.setAttribute('aria-pressed','false');b.setAttribute('aria-label','Hiển thị mật khẩu');
   b.addEventListener('click',()=>{
    const show=inp.type==='password';
    inp.type=show?'text':'password';
    b.textContent=show?'Ẩn':'Hiển thị';
    b.setAttribute('aria-pressed',String(show));
    b.setAttribute('aria-label',show?'Ẩn mật khẩu':'Hiển thị mật khẩu');
   });
   wrap.appendChild(b);
  });
 };
 if(typeof document!=='undefined'){
  const start=()=>{enh(document.body);new MutationObserver(ms=>{for(const m of ms)m.addedNodes.forEach(n=>{if(n.nodeType===1)enh(n)})}).observe(document.body,{childList:true,subtree:true})};
  if(document.body)start();else document.addEventListener('DOMContentLoaded',start);
 }
})();
/* ===== Khởi động ===== */
/* Nâng cấp dữ liệu đã lưu từ bản 2 (chưa có thư viện mục tiêu) lên bản 3, giữ nguyên nhân sự, học sinh, lịch, điểm danh, học phí */
function migrate(d){
 DB=d;
 d.cfg.addr=d.cfg.addr||'28 Trường Thi 1, Quận Hải Châu, TP. Đà Nẵng';d.cfg.tel=d.cfg.tel||'0793502567';
 delete d.goals;
 seedProg(d);
 d.rp.forEach(r=>{if(/^r\d{1,3}$/.test(r.id)){const k=d.kids.find(x=>x.id===r.hs);if(k)r.sec=autoSec(k,r.per)}});
 d.v=3}
/* Bản 4: thêm vai trò Văn phòng, khung giờ 07:15–20:00 (ca 50 phút), hai lớp bán trú Ong non và Ong mật, thực đơn bán trú.
   Giữ nguyên học sinh, lịch, điểm danh, học phí, kế hoạch mục tiêu, báo cáo; chỉ đổi giờ ca, gộp 4 nhóm bán trú cũ thành 2 lớp. */
function migrate4(d){
 DB=d;
 const near=s=>{if(SLOTS.includes(s))return s;const m=x=>{const [h,n]=String(x).split(':').map(Number);return h*60+n},t=m(s);let b=SLOTS[0];SLOTS.forEach(x=>{const a=Math.abs(m(x)-t),c=Math.abs(m(b)-t);if(a<c||(a===c&&m(x)>m(b)))b=x});return b};
 d.lich.forEach(l=>{if(l.slot)l.slot=near(l.slot)});
 d.mk.forEach(r=>{if(r.from&&r.from.slot)r.from.slot=near(r.from.slot);(r.props||[]).forEach(p=>{if(p.slot)p.slot=near(p.slot)})});
 /* 4 nhóm bán trú cũ: Mầm, Chồi (dưới 6 tuổi) thành Ong non; Lá, Nắng thành Ong mật */
 const old=d.groups.slice(),map={G1:'G1',G2:'G1',G3:'G2',G4:'G2'};
 if(old.length!==2||old[0].n!==BTN[0]||old[1].n!==BTN[1]){
  const o1=old.find(g=>g.id==='G1'),o2=old.find(g=>g.id==='G2')||old[1]||old[0];
  d.groups=[{id:'G1',n:BTN[0],gv:o1?o1.gv:'nv18',tg:o1?o1.tg:'nv20'},{id:'G2',n:BTN[1],gv:o2?o2.gv:'nv19',tg:o2?o2.tg:'nv21'}];
  const keep=new Set([d.groups[0].gv,d.groups[0].tg,d.groups[1].gv,d.groups[1].tg]);
  /* giáo viên của các nhóm cũ không còn phụ trách lớp bán trú: chuyển sang dạy 1-1 nếu hồ sơ còn nguyên mặc định */
  old.forEach(g=>[g.gv,g.tg].forEach(id=>{const s=d.staff.find(x=>x.id===id);
   if(s&&!keep.has(id)&&s.role==='gv'&&/bán trú/i.test(s.pos)&&s.pay&&(s.pay.rateBt===30e3||s.pay.rateBt===20e3)&&(s.pay.base===9e6||s.pay.base===7e6)){
    s.pos=['Giáo viên ngôn ngữ trị liệu','Giáo viên giáo dục đặc biệt','Chuyên viên hoạt động trị liệu'][(+id.slice(2)||0)%3];s.pay={mode:'buoi',base:0,rate:220e3,rateBt:0,allow:5e5,bh:0,latePen:s.pay.latePen||0}}}));
  d.kids.forEach(k=>{if(k.gr)k.gr=map[k.gr]||(k.gr==='G1'?'G1':'G2')});
  const att={};Object.keys(d.att).forEach(key=>{const p=key.split('|');if(/^G\d+$/.test(p[1]))p[1]=map[p[1]]||'G2';const nk=p.join('|');if(!(nk in att))att[nk]=d.att[key]});d.att=att;
  d.nt.forEach(n=>{if(map[n.tg])n.tg=map[n.tg]});
  d.nt.forEach(n=>{if(n.t==='Hoạt động ngoại khóa Nhóm Chồi'){n.t='Hoạt động ngoại khóa lớp Ong non';n.b='Lớp Ong non có hoạt động vận động ngoài trời vào thứ Sáu tuần này. Bé mặc quần áo thoải mái, mang theo nước uống.';n.tg='G1';if(n.by==='nv19')n.by='nv18'}})}
 /* Văn phòng: nhân viên kế toán cũ (nv26) giữ chức vụ văn phòng nếu chưa có ai giữ vai trò này */
 if(!d.staff.some(s=>s.role==='vp')){const s=d.staff.find(x=>x.id==='nv26'&&x.role==='hc')||d.staff.find(x=>x.role==='hc'&&/kế toán/i.test(x.pos));
  if(s){s.role='vp';if(/kế toán/i.test(s.pos))s.pos='Nhân viên văn phòng';s.sup=s.sup||'nv02'}}
 /* thông báo về học phí hoặc lương chỉ Trưởng Trung tâm và Văn phòng thấy */
 d.nt.forEach(n=>{if(n.fin===undefined)n.fin=/học phí|lương|thu chi|công nợ|đóng tiền/i.test(n.t+' '+n.b);
  if(n.t==='Nhắc đóng học phí đầu tháng'&&n.by==='nv01'&&d.staff.some(s=>s.id==='nv26'&&s.role==='vp'))n.by='nv26'});
 if(!d.nt.some(n=>n.t==='Giờ học 1-1 và bán trú'))d.nt.push({id:'n'+uid(),aud:'ph',tg:'all',t:'Giờ học 1-1 và bán trú',b:'Can thiệp 1-1 nhận bé từ '+DAY_OPEN+' đến '+DAY_CLOSE+', mỗi ca '+SLOT_MIN+' phút. Bán trú hai lớp Ong non và Ong mật học từ '+BT.s+' đến '+BT.e+' (thứ Hai đến thứ Sáu). Phụ huynh xem lịch học và giờ 1-1 của bé ở mục Lịch học của bé, thực đơn bán trú ở mục Thực đơn bán trú.',by:'nv02',at:TODAY,pin:false,fin:false});
 if(!d.menu||typeof d.menu!=='object')seedMenu(d);
 d.v=4}
/* Bản 5: bán trú tính theo ngày (380.000 ₫/ngày gồm 180.000 ₫ ca 1-1), ngày bán trú theo từng bé, chẩn đoán, thời khóa biểu bán trú, lương giáo viên 1-1 theo ca.
   Giữ nguyên học sinh, lịch, điểm danh, công nợ. Phí bán trú theo tháng cũ được bỏ; hóa đơn đã ghi vào công nợ không đổi. */
function migrate5(d){
 DB=d;const c=d.cfg;
 if(c.pbtDay==null)c.pbtDay=380000;if(c.pbtDay11==null)c.pbtDay11=180000;
 delete c.pbtCN;delete c.pbtKhac;
 c.rule=Object.assign({gvKp:50,gvP:0},c.rule);
 if(!Array.isArray(d.tkb)||!d.tkb.length)d.tkb=tkbDefault(d.groups);
 d.kids.forEach(k=>{if(!Array.isArray(k.dx))k.dx=[]});
 d.v=5}
/* Bản 6: danh sách ngày nghỉ lễ / Trung tâm cho nghỉ (hol). Học phí trả trước tính theo lịch đã trừ các ngày này. Giữ nguyên mọi dữ liệu cũ. */
function migrate6(d){
 DB=d;
 if(!Array.isArray(d.hol))d.hol=[];
 if(!d.pul||typeof d.pul!=='object'||Array.isArray(d.pul))d.pul={};
 d.v=6}
/* Bản 7: chấm công do Quản lý thực hiện (cờ s.cc: nhân sự chỉ trả theo ca 1-1 không chấm công), vi phạm nội quy và trừ lương (vio, vam), giờ chấm công mặc định và mức trừ lương trong cấu hình. Giữ nguyên mọi dữ liệu cũ. */
function migrate7(d){
 DB=d;
 d.staff.forEach(s=>{if(s.cc==null)s.cc=ccOf(s.pay)});
 if(!Array.isArray(d.vio))d.vio=[];
 if(!d.vam||typeof d.vam!=='object'||Array.isArray(d.vam))d.vam={};
 if(!d.kpr||typeof d.kpr!=='object'||Array.isArray(d.kpr))d.kpr={};
 const c=d.cfg;if(!c.ccIn)c.ccIn='07:15';if(!c.ccOut)c.ccOut='18:00';if(c.v1==null)c.v1=20000;if(c.v2==null)c.v2=30000;
 d.v=7}
const okDB=d=>d&&Array.isArray(d.staff)&&Array.isArray(d.kids)&&d.cfg&&d.cfg.rule&&d.set&&d.rd&&d.att&&Array.isArray(d.rp)&&Array.isArray(d.tpl);
(function boot(){
 if(CLOUDMODE){try{const th=localStorage.getItem('gb_th');if(th)document.documentElement.dataset.theme=th}catch(e){}cloudBoot();initCaps();return}
 let d=null;try{d=JSON.parse(localStorage.getItem(KEY)||'null')}catch(e){}
 if(okDB(d)&&d.v===7&&Array.isArray(d.vio)&&d.vam&&Array.isArray(d.hol)&&Array.isArray(d.plans)&&Array.isArray(d.sess)&&Array.isArray(d.cg)&&d.menu&&Array.isArray(d.groups)&&Array.isArray(d.tkb))DB=d;
 else if(okDB(d)&&d.v>=2&&d.v<=6){try{if(d.v===2)migrate(d);if(d.v<=3)migrate4(d);if(d.v<=4)migrate5(d);if(d.v<=5)migrate6(d);migrate7(d);save()}catch(e){DB=null;seed();save()}}
 else{seed();save()}
 if(!DB.kpr||typeof DB.kpr!=='object'||Array.isArray(DB.kpr))DB.kpr={};   /* dữ liệu mẫu bản 7 cũ chưa có giá riêng từng bé */
 try{const th=localStorage.getItem('gb_th');if(th)document.documentElement.dataset.theme=th}catch(e){}
 try{const em=localStorage.getItem('gb_u');if(em){const a=findAccount(em);if(a){U=a;S.v=ACCESS[a.role][0]}}}catch(e){}
 render();initCaps();
})();
